  });

  it('leaves the escrowId query param untouched rather than stripping or redirecting on it', async () => {
    window.history.pushState({}, '', '/?escrowId=deal-2');
    render(<EscrowView user={user} />);
    await waitFor(() => expect(new URLSearchParams(window.location.search).get('escrowId')).toBe('deal-2'));
  });
});

// STAGE 5F.5 — the UI permission mirror must equal the server catalogue (the server stays the authority; a drift here
// shows or hides the wrong menu entries and hides the real access boundary from the operator).
import { describe, it, expect } from 'vitest';
import * as server from '../../../backend/config/roles.js';
import * as ui from '../../utils/permissions';

const sorted = (a: readonly string[]) => [...a].sort();

describe('frontend permission mirror ≡ backend/config/roles.js', () => {
  it('has the same permission keys and values', () => {
    expect(ui.PERM).toEqual(server.PERM);
  });
  it('has the same assignable permission set', () => {
    expect(sorted(ui.ASSIGNABLE_PERMISSIONS)).toEqual(sorted(server.ASSIGNABLE_PERMISSIONS));
  });
  it('gives every staff role the same default permissions', () => {
    const staff = Object.keys(server.ROLE_PERMISSIONS);
    for (const role of staff) {
      if (role === 'superadmin') continue; // server: all permissions; mirror handles it in getEffectivePermissions
      expect(sorted((ui.ROLE_PERMISSIONS as any)[role] ?? []), `role ${role}`).toEqual(sorted(server.ROLE_PERMISSIONS[role]));
    }
  });
  it('computes the same effective permissions for grants and revocations', () => {
    const cases = [
      { role: 'marketing', grantedPermissions: ['manage_finance'], revokedPermissions: ['manage_ads'] },
      { role: 'hr', grantedPermissions: [], revokedPermissions: ['manage_users'] },
      { role: 'moderator', grantedPermissions: ['view_analytics'], revokedPermissions: [] },
      { role: 'accounts', grantedPermissions: [], revokedPermissions: [] },
      { role: 'admin', grantedPermissions: [], revokedPermissions: ['manage_platform'] },
      { role: 'user', grantedPermissions: ['manage_cars'], revokedPermissions: [] },
    ];
    for (const c of cases) expect(sorted(ui.getEffectivePermissions(c as any)), c.role).toEqual(sorted(server.getEffectivePermissions(c)));
  });
  it('labels exist for every assignable permission', () => {
    for (const p of ui.ASSIGNABLE_PERMISSIONS) expect((ui.PERM_LABELS as any)[p], p).toBeTruthy();
  });
});

import axios from 'axios';
import { clearCSRFToken, getCSRFToken, getCsrfHeaders, setCSRFToken } from '../utils/csrf';

const configuredApiUrl = String(import.meta.env.VITE_API_URL || '').trim().replace(/\/$/, '');

// One transport contract for every browser API call:
//   - unset VITE_API_URL -> same-origin /api
//   - VITE_API_URL=/api -> same-origin /api
//   - VITE_API_URL=https://api.kayad.space -> https://api.kayad.space/api
//   - VITE_API_URL=https://api.kayad.space/api -> same canonical API origin
// All service modules therefore keep using their existing /cars, /auth, etc.
// paths while the adapter normalizes /api-prefixed auth paths in httpRequest.
const apiOrigin = configuredApiUrl.replace(/\/api$/, '');
const API_URL = configuredApiUrl && apiOrigin && /^https?:\/\//i.test(apiOrigin)
  ? `${apiOrigin}/api`
  : '/api';

// Auth routes are mounted at /api/v1/auth on the backend. Axios already has
// /api in its baseURL, so the request path is /v1/auth/... in every deployment.
const CSRF_BOOTSTRAP_PATH = '/v1/auth/csrf';

export const api = axios.create({
  baseURL: API_URL,
  withCredentials: true,
  // A hanging request must not hang the UI forever — network
  // interruptions surface as an error the page can render honestly.
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
});

let csrfBootstrapPromise: Promise<void> | null = null;
let refreshSessionPromise: Promise<void> | null = null;

const ensureCsrfToken = async (): Promise<void> => {
  if (typeof document === 'undefined') return;
  if (getCSRFToken()) return;

  if (!csrfBootstrapPromise) {
    csrfBootstrapPromise = api
      .get(CSRF_BOOTSTRAP_PATH, { withCredentials: true })
      .then((response) => {
        const token = response?.data?.csrfToken;
        if (typeof token === 'string' && token.length >= 32) {
          // Keep a memory copy as well as the readable cookie. This matters
          // when the API is on api.kayad.space and the UI is on a separate
          // KAYAD subdomain, or when a browser privacy mode hides a cookie
          // from document.cookie even though it is still sent to the API.
          setCSRFToken(token);
          return;
        }
        throw new Error('CSRF bootstrap did not return a valid token');
      })
      .finally(() => {
        csrfBootstrapPromise = null;
      });
  }

  await csrfBootstrapPromise;
};

api.interceptors.request.use(async (config) => {
  const method = String(config.method || 'get').toUpperCase();
  if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
    // A brand-new browser has no XSRF cookie yet. Bootstrap it before the
    // first state-changing request; otherwise the server correctly rejects
    // registration/login/etc. with "CSRF token validation failed".
    await ensureCsrfToken();
  }
  Object.assign(config.headers, getCsrfHeaders(method));
  return config;
});

// Authentication endpoints have different 401 semantics. Do not collapse
// login failures, registration failures, session probes and refresh failures
// into one generic "session expired" path.
type AuthEndpointKind =
  | 'login'
  | 'register'
  | 'refresh'
  | 'session-probe'
  | 'logout'
  | 'verification'
  | 'recovery'
  | 'other';

const classifyAuthEndpoint = (url: string = ''): AuthEndpointKind => {
  const path = String(url).split('?')[0];
  if (/\/auth\/(login)(?:$|\?)/.test(path)) return 'login';
  if (/\/auth\/(register)(?:$|\?)/.test(path)) return 'register';
  if (/\/auth\/(refresh)(?:$|\?)/.test(path)) return 'refresh';
  if (/\/auth\/(me|profile)(?:$|\?)/.test(path)) return 'session-probe';
  if (/\/auth\/logout(?:$|\?)/.test(path)) return 'logout';
  if (/\/auth\/(verify-email|resend-verification)(?:\/|$)/.test(path)) return 'verification';
  if (/\/auth\/(forgot-password|reset-password)(?:$|\?)/.test(path)) return 'recovery';
  return 'other';
};

const shouldAttemptRefresh = (kind: AuthEndpointKind) =>
  kind === 'other' || kind === 'session-probe';

const shouldDispatchAuthExpired = (kind: AuthEndpointKind) =>
  kind === 'other' || kind === 'refresh';

/** True only when the server explicitly rejected the credential: 401, or a 403
 * that is an authorization/session verdict rather than a CSRF-token mismatch.
 * Network errors (no response), timeouts, 5xx, 429 and CSRF failures are
 * "unknown", never "logged out". */
export const isDefinitiveSessionRejection = (err: unknown): boolean => {
  const response = (err as { response?: { status?: number; data?: { message?: unknown } } } | undefined)?.response;
  const status = response?.status;
  if (status === 401) return true;
  if (status === 403) return !/csrf/i.test(String(response?.data?.message ?? ''));
  return false;
};

const refreshSession = async (): Promise<void> => {
  if (!refreshSessionPromise) {
    refreshSessionPromise = api
      .post('/v1/auth/refresh')
      .then(() => undefined)
      .finally(() => {
        refreshSessionPromise = null;
      });
  }
  await refreshSessionPromise;
};

api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const original = error?.config as (typeof error.config & { _kayadRetried?: boolean; _kayadCsrfRetried?: boolean }) | undefined;
    const status = error?.response?.status;

    // A stale/missing double-submit token is recoverable. Clear only the
    // in-memory copy, bootstrap a fresh server-issued token, and retry the
    // mutation once. This is deliberately separate from authentication expiry.
    if (status === 403 && original && !original._kayadCsrfRetried && /csrf token validation failed/i.test(String(error?.response?.data?.message || error?.message || ''))) {
      original._kayadCsrfRetried = true;
      try {
        clearCSRFToken();
        await ensureCsrfToken();
        return api.request(original);
      } catch {
        return Promise.reject(error);
      }
    }

    // Access cookies are intentionally short-lived. On the first 401 from a
    // normal authenticated endpoint, rotate the refresh cookie and retry the
    // original request once. Login/register/refresh failures remain terminal
    // auth errors and never recurse through this path.
    const endpointKind = classifyAuthEndpoint(original?.url || error?.config?.url || '');

    if (status === 401 && original && !original._kayadRetried && shouldAttemptRefresh(endpointKind)) {
      original._kayadRetried = true;
      try {
        await refreshSession();
        return api.request(original);
      } catch (refreshError) {
        // Only a DEFINITIVE rejection of the refresh credential (401, or a 403
        // that is not a CSRF problem) proves the session is over. A refresh that
        // failed for any other reason (network error, timeout, 5xx, CORS, a CSRF
        // mismatch) tells us nothing about the session: surface THAT error so
        // callers can show a recoverable state, and never broadcast expiry.
        if (!isDefinitiveSessionRejection(refreshError)) {
          return Promise.reject(refreshError);
        }
        // A normal login/registration/session-probe failure must not be
        // converted into a global redirect signal. A refresh failure is the
        // explicit session-expiry boundary.
        if (shouldDispatchAuthExpired(endpointKind)) {
          window.dispatchEvent(new Event('kayad:auth-expired'));
        }
        return Promise.reject(error);
      }
    }

    if (status === 401 && shouldDispatchAuthExpired(endpointKind)) {
      window.dispatchEvent(new Event('kayad:auth-expired'));
    }
    return Promise.reject(error);
  }
);

export const unwrap = (response: any) => {
  if (response && response.data !== undefined) {
    return response.data;
  }
  return response;
};

// Admin Table Row Component
// Reusable row component for admin tables

import { MoreVertical, Edit, Trash2, Eye, CheckCircle, XCircle } from 'lucide-react';
import { useState, type ReactNode } from 'react';

interface Action {
  label: string;
  icon?: ReactNode;
  onClick: () => void;
  variant?: 'primary' | 'danger' | 'default';
}

interface AdminTableRowProps {
  id: string | number;
  columns: string[];
  actions?: Action[];
  onEdit?: () => void;
  onDelete?: () => void;
  onView?: () => void;
  selected?: boolean;
  onSelect?: (selected: boolean) => void;
  className?: string;
}

export function AdminCarRow({
  car,
  onView,
  onEdit,
  onDelete
}: {
  car: any;
  onView?: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
}) {
  return (
    <tr className="border-b border-[#D7E7E4] hover:bg-[#F6FAF9]">
      <td className="py-3 px-4">
        <div className="flex items-center gap-3">
          {car.image && (
            <img
              src={car.image}
              alt={car.title}
              loading="lazy"
              decoding="async"
              className="w-12 h-12 object-cover rounded"
            />
          )}
          <div>
            <p className="font-medium">{car.title || car.brand}</p>
            <p className="text-sm text-[#64748B]">{car.year} • {car.mileage?.toLocaleString()} km</p>
          </div>
        </div>
      </td>
      <td className="py-3 px-4">
        <span className="font-semibold">KES {(car.price || 0).toLocaleString()}</span>
      </td>
      <td className="py-3 px-4">
        <span className={`px-2 py-1 rounded text-xs font-medium ${
          car.status === 'active' ? 'bg-green-100 text-green-700' :
          car.status === 'pending' ? 'bg-[#DDF4F0] text-[#12576D]' :
          'bg-[#EEF7F5] text-[#12576D]'
        }`}>
          {car.status || 'Unknown'}
        </span>
      </td>
      <td className="py-3 px-4">
        <div className="flex items-center gap-2">
          {onView && (
            <button onClick={onView} className="p-1 hover:bg-[#EEF7F5] rounded">
              <Eye className="h-4 w-4 text-[#64748B]" />
            </button>
          )}
          {onEdit && (
            <button onClick={onEdit} className="p-1 hover:bg-[#EEF7F5] rounded">
              <Edit className="h-4 w-4 text-[#2F8F87]" />
            </button>
          )}
          {onDelete && (
            <button onClick={onDelete} className="p-1 hover:bg-[#EEF7F5] rounded">
              <Trash2 className="h-4 w-4 text-red-500" />
            </button>
          )}
        </div>
      </td>
    </tr>
  );
}

export function AdminUserRow({
  user,
  onView,
  onSuspend,
  onDelete
}: {
  user: any;
  onView?: () => void;
  onSuspend?: () => void;
  onDelete?: () => void;
}) {
