};

const staffActions = [{label:'Control plane',nav:'admin',icon:LayoutDashboard},{label:'Vehicle moderation',nav:'admin',icon:Car},{label:'Inspections',nav:'inspections',icon:ClipboardCheck},{label:'Support',nav:'support',icon:Users}];

export default function DashboardHub({ user, vehicles = [], onNavigate }: Props) {
  const role = user?.role || 'user';
  // Phase 13E: a private seller is still a buyer. individual_seller no longer gets a seller-only view; it gets the buyer dashboard
  // plus the seller workspace entry. The seller section itself is driven by the real capability state (SellerCapabilityPanel).
  const isPersonal = role === 'user' || role === 'buyer' || role === 'individual_seller';
  const { capability, loading: capLoading, error: capError, reload: reloadCap } = usePrivateSellerCapability(isPersonal);
  const sellerApproved = capability ? capability.status === 'approved' : role === 'individual_seller';
  const baseConfig = configs[role === 'individual_seller' ? 'user' : role];
  // Phase 13F: a legacy individual_seller whose real capability is suspended/revoked/rejected is not offered the seller workspace entry (the backend refuses their seller writes).
  const sellerBlocked = !!capability && ['suspended', 'revoked', 'rejected'].includes(capability.status);
  const personalConfig = role === 'individual_seller' ? { ...baseConfig, title: 'My Dashboard', subtitle: 'Buy and sell from one account: your saved vehicles, active transactions and private-seller tools.', actions: sellerBlocked ? baseConfig.actions : [...baseConfig.actions, {label:'Seller workspace',nav:'seller-platform',icon:LayoutDashboard}] } : (isPersonal && capability?.status === 'approved' ? { ...baseConfig, actions: [...baseConfig.actions, {label:'Seller workspace',nav:'seller-platform',icon:LayoutDashboard}] } : baseConfig);
  const config = (isPersonal ? personalConfig : undefined) || configs[role] || (['admin','superadmin','marketing','technical_support','hr','accounts','escrow_officer','ad_manager','moderator'].includes(role) ? { title: 'Platform Operations Dashboard', subtitle: 'Role-scoped control, queues and platform health.', accent: '#5AAFA4', actions: staffActions } : configs.user);
  const [density, setDensity] = useState<'comfortable'|'compact'>('comfortable');
  const [hidden, setHidden] = useState<string[]>([]);
  const [snapshot, setSnapshot] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [sourceError, setSourceError] = useState('');

  const cards = useMemo(() => {
    const owned = vehicles.filter((v) => v?.sellerId && v.sellerId === (user?.id || user?._id));
    if (role === 'dealer' || role === 'broker') return [{id:'inventory',label:'Your inventory',value:owned.length,icon:Car},{id:'saved',label:'Saved vehicles',value:0,icon:ShoppingBag},{id:'activity',label:'Marketplace activity',value:vehicles.length,icon:Activity}];
    if (['admin','superadmin','marketing','technical_support','hr','accounts','escrow_officer','ad_manager','moderator'].includes(role)) return [{id:'users',label:'Users',value:snapshot?.counts?.users ?? '—',icon:Users},{id:'cars',label:'Vehicles',value:snapshot?.counts?.cars ?? '—',icon:Car},{id:'incidents',label:'Incidents',value:snapshot?.counts?.incidents ?? '—',icon:Activity},{id:'alerts',label:'Alerts',value:snapshot?.counts?.alerts ?? '—',icon:Bell}];
    if (role === 'ghost_checker') return [{id:'assigned',label:'Assigned inspections',value:Array.isArray(snapshot?.orders) ? snapshot.orders.length : '—',icon:ClipboardCheck},{id:'messages',label:'Messages',value:'—',icon:Bell},{id:'market',label:'Marketplace',value:vehicles.length,icon:Car}];
    const buyerCards = [{id:'saved',label:'Saved vehicles',value:'—',icon:ShoppingBag},{id:'vehicles',label:'Marketplace inventory',value:vehicles.length,icon:Car},{id:'alerts',label:'Action alerts',value:'—',icon:Bell}];
    return sellerApproved ? [{id:'inventory',label:'Your inventory',value:owned.length,icon:Car}, ...buyerCards] : buyerCards;
  }, [vehicles, user, role, snapshot, sellerApproved]);

  const refresh = async () => {
    setLoading(true); setSourceError('');
    try {
      if (['admin','superadmin','marketing','technical_support','hr','accounts','escrow_officer','ad_manager','moderator'].includes(role)) {
        const result = await getControlPlaneSnapshot(); setSnapshot(result?.data || result);
      } else if (role === 'dealer') {
        const result = await dealerApi.getDealerDashboard(); setSnapshot(result?.data || result);
      } else if (role === 'user' || role === 'buyer' || role === 'individual_seller') {
        const result = await getOwnershipDashboard(); setSnapshot(result);
      } else if (role === 'ghost_checker') {
        const result = await inspectionAPI.myAssigned(); setSnapshot(result?.data || result);
      }
    } catch (e) { setSourceError('Live dashboard data could not be refreshed. Existing values were not replaced with mock data.'); }
    finally { setLoading(false); }
  };

  useEffect(() => { refresh(); }, [role]);

  const toggle = (id: string) => setHidden((prev) => prev.includes(id) ? prev.filter(x=>x!==id) : [...prev,id]);

  return <section className={`space-y-6 pb-10 auction-dashboard-experience kayad-portal kayad-portal--${role}`} data-kayad-portal={role} data-dashboard-role={role}>
    {!isStaffRole(role) && <>
      <AuctionExperienceRail current="wallet" />
      <BidderIdentityCard user={user} savedCount={null} onPayments={() => onNavigate('payments')} />
    </>}
    <div className="rounded-3xl p-6 text-white shadow-lg" style={{background:`linear-gradient(135deg, ${config.accent}, #0A3340)`}}>
      <div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between">
        <div><p className="text-[10px] font-black uppercase tracking-[0.2em] text-white/60">KAYAD workspace</p><h1 className="mt-1 text-2xl font-black">{config.title}</h1><p className="mt-1 max-w-2xl text-sm text-white/70">{config.subtitle}</p></div>
        <div className="flex flex-wrap gap-2"><button onClick={refresh} disabled={loading} className="inline-flex items-center gap-2 rounded-xl border border-white/20 bg-white/10 px-3 py-2 text-xs font-bold hover:bg-white/15"><RefreshCw size={14} className={loading?'animate-spin':''}/> Refresh</button><button onClick={()=>setDensity(density==='comfortable'?'compact':'comfortable')} className="inline-flex items-center gap-2 rounded-xl border border-white/20 bg-white/10 px-3 py-2 text-xs font-bold"><Settings2 size={14}/> {density==='comfortable'?'Compact':'Comfortable'}</button></div>
      </div>
    </div>

    {isPersonal && <SellerCapabilityPanel capability={capability} loading={capLoading} error={capError} onReload={reloadCap} onOpenWorkspace={() => onNavigate('seller-platform')} />}

    {sourceError && <div className="rounded-xl border border-[#BDE5DE] bg-[#F3FAF9] p-3 text-xs font-bold text-[#0A3340]">{sourceError}</div>}

    <div className={`grid gap-3 ${density==='compact'?'sm:grid-cols-4':'sm:grid-cols-2 lg:grid-cols-4'}`}>
      {cards.filter(c=>!hidden.includes(c.id)).map((card)=>{const Icon=card.icon;return <div key={card.id} className="group rounded-2xl border border-[#D7E7E4] bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><div><p className="text-[10px] font-black uppercase tracking-wider text-[#5B6B7D]">{card.label}</p><p className="mt-1 text-2xl font-black text-[#0A3340]">{card.value}</p></div><Icon size={20} style={{color:config.accent}}/></div><button onClick={()=>toggle(card.id)} className="mt-3 text-[10px] font-bold text-[#5B6B7D] opacity-0 group-hover:opacity-100">Hide card</button></div>})}
    </div>

    <div className="grid gap-5 lg:grid-cols-[1.3fr_.7fr]">
      <div className="rounded-2xl border border-[#D7E7E4] bg-white p-5"><div className="mb-4 flex items-center justify-between"><div><h2 className="text-sm font-black text-[#0A3340]">Workspace controls</h2><p className="text-xs text-[#64748B]">Role-scoped shortcuts into the existing canonical modules.</p></div><BarChart3 size={18} className="text-[#BDE5DE]"/></div><div className="grid gap-3 sm:grid-cols-2">{config.actions.map((action)=>{const Icon=action.icon;return <button key={action.label+action.nav} onClick={()=>onNavigate(action.nav)} className="flex items-center gap-3 rounded-xl border border-[#D7E7E4] p-3 text-left hover:border-[#BDE5DE] hover:shadow-sm"><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#F6FAF9] text-[#0A3340]"><Icon size={17}/></span><span className="flex-1 text-xs font-black text-[#12576D]">{action.label}</span><ChevronRight size={15} className="text-[#BDE5DE]"/></button>})}</div></div>
      <div className="rounded-2xl border border-[#D7E7E4] bg-[#F6FAF9] p-5"><h2 className="text-sm font-black text-[#0A3340]">Dashboard controls</h2><div className="mt-4 space-y-3 text-xs text-[#64748B]"><button onClick={()=>setHidden([])} className="w-full rounded-xl bg-white px-3 py-2.5 text-left font-bold border border-[#D7E7E4]">Restore hidden cards</button><button onClick={()=>setDensity('comfortable')} className="w-full rounded-xl bg-white px-3 py-2.5 text-left font-bold border border-[#D7E7E4]">Reset comfortable density</button><p className="pt-2 text-[11px] leading-5 text-[#5B6B7D]">The dashboard shell changes presentation only. Counts and workflow state remain sourced from KAYAD APIs; no placeholder records are created.</p></div></div>
    </div>
  </section>;
}

import { timeAgo } from '../utils/helpers';
import { Shield, DollarSign, Truck, CheckCircle, AlertTriangle } from 'lucide-react';

const STEP_CONFIG = [
  { key: 'created', label: 'Escrow Created', icon: Shield },
  { key: 'funded', label: 'Payment Funded', icon: DollarSign },
  { key: 'buyer_requested_release', label: 'Delivery Confirmed', icon: Truck },
  { key: 'released', label: 'Funds Released', icon: CheckCircle },
];

interface EscrowTimelineProps {
  history: Array<{
    action: string;
    timestamp?: string;
    note?: string;
  }>;
}

export default function EscrowTimeline({ history }: EscrowTimelineProps) {
  if (!history || history.length === 0) {
    return (
      <div className="text-center py-6 text-warm-400 text-sm">
        No timeline events yet
      </div>
    );
  }

  const doneKeys = new Set(history.map(h => h.action));

  return (
    <div className="space-y-0">
      {STEP_CONFIG.map((step, idx) => {
        const event = history.find(h => h.action === step.key);
        const isDone = doneKeys.has(step.key);
        const Icon = step.icon;

        return (
          <div key={step.key} className="flex gap-4">
            {/* Timeline line */}
            <div className="flex flex-col items-center">
              <div className={`
                w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0
                ${isDone ? 'bg-emerald-500' : 'bg-[#DDF4F0]'}
              `}>
                <Icon size={14} className={isDone ? 'text-white' : 'text-warm-400'} />
              </div>
              {idx < STEP_CONFIG.length - 1 && (
                <div className={`w-0.5 flex-1 min-h-[40px] ${isDone ? 'bg-emerald-500' : 'bg-[#DDF4F0]'}`} />
              )}
            </div>

            {/* Event content */}
            <div className={`pb-6 flex-1 ${idx === STEP_CONFIG.length - 1 ? 'pb-0' : ''}`}>
              <div className="flex items-center justify-between">
                <p className={`font-sans text-sm font-semibold ${isDone ? 'text-[#0A3340]' : 'text-warm-400'}`}>
                  {step.label}
                </p>
                {event?.timestamp && (
                  <span className="font-sans text-xs text-warm-400">
                    {timeAgo(event.timestamp)}
                  </span>
                )}
              </div>
              {event?.note && (
                <p className="font-sans text-xs text-warm-500 mt-1">{event.note}</p>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// Simple escrow stepper component
interface EscrowStepperProps {
  status: 'pending' | 'funded' | 'released' | 'disputed';
}

export function EscrowStepper({ status }: EscrowStepperProps) {
  const statusOrder = ['pending', 'funded', 'released'];
  const currentIdx = statusOrder.indexOf(status);
  const isDisputed = status === 'disputed';

  return (
    <div className="flex items-center justify-between gap-2 py-4">
      {['Created', 'Funded', 'Released'].map((label, idx) => {
        const isDone = idx <= currentIdx;
        const isCurrent = idx === currentIdx;

        return (
          <div key={label} className="flex-1 flex flex-col items-center">
            <div className={`
              w-10 h-10 rounded-full flex items-center justify-center mb-2
              ${isDone ? 'bg-emerald-500' : 'bg-[#DDF4F0]'}
              ${isCurrent && !isDisputed ? 'ring-2 ring-[#5AAFA4] ring-offset-2' : ''}
            `}>
              {isDone ? (
                <CheckCircle size={18} className="text-white" />
              ) : (
                <span className="text-warm-400 text-sm font-bold">{idx + 1}</span>
              )}
            </div>
            <span className={`font-sans text-xs font-medium text-center ${isDone ? 'text-[#0A3340]' : 'text-warm-400'}`}>
              {label}
            </span>
          </div>
        );
      })}
    </div>
  );
}

import { useState } from 'react';
import { formatDistanceToNow } from 'date-fns';
import { Eye, Download, Trash2, CheckCircle, XCircle } from 'lucide-react';
import { disputeAPI } from '../api/api';
import { useToast } from '../context/ToastContext';
import { useAuth } from '../context/AuthContext';

const TYPE_META = {
  image:             { icon: '📷', label: 'Image', color: 'text-[#5AAFA4]' },
  video:             { icon: '🎥', label: 'Video', color: 'text-[#5AAFA4]' },
  document:          { icon: '📄', label: 'Document', color: 'text-[#13B8A6]' },
  inspection_report: { icon: '🔍', label: 'Inspection Report', color: 'text-green-400' },
  payment_record:    { icon: '💳', label: 'Payment Record', color: 'text-emerald-400' },
  chat_log:          { icon: '💬', label: 'Chat Log', color: 'text-[#5AAFA4]' },
};

export default function EvidenceTimeline({ evidence, disputeId, onRefresh }) {
  const { toast } = useToast();
  const { user } = useAuth();
  const [previewUrl, setPreviewUrl] = useState(null);
  const isAdmin = ['admin', 'superadmin', 'escrow_officer'].includes(user?.role);

  const handleDelete = async (evidenceId) => {
    if (!confirm('Delete this evidence?')) return;
    try {
      await disputeAPI.deleteEvidence(disputeId, evidenceId);
      toast('Evidence deleted', 'success');
      if (onRefresh) onRefresh();
    } catch (err) {
      toast(err?.response?.data?.message || 'Delete failed', 'error');
    }
  };

  const handleVerify = async (evidenceId) => {
    try {
      await disputeAPI.verifyEvidence(disputeId, evidenceId);
      toast('Evidence verified', 'success');
      if (onRefresh) onRefresh();
    } catch (err) {
      toast('Verification failed', 'error');
    }
  };

  if (!evidence || evidence.length === 0) {
    return (
      <div className="text-center py-8 text-[#64748B]">
        <p className="text-3xl mb-2">📁</p>
        <p className="text-sm">No evidence uploaded yet</p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {evidence.map((item) => {
        const meta = TYPE_META[item.type] || { icon: '📄', label: item.type, color: 'text-[#94A3B8]' };
        const isOwner = item.uploadedBy?._id === user?.id || item.uploadedBy === user?.id;

        return (
          <div key={item._id} className="bg-[#0A3340] border border-[#12576D] rounded-lg p-3 flex items-start gap-3 group">
            <span className={`text-xl mt-1 ${meta.color}`}>{meta.icon}</span>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-[#DDF4F0] truncate">{item.fileName}</p>
              <p className="text-xs text-[#64748B]">{meta.label}</p>
              {item.description && <p className="text-xs text-[#94A3B8] mt-1">{item.description}</p>}
              <div className="flex items-center gap-3 mt-2 text-xs text-[#64748B]">
                <span>{(item.size / 1024).toFixed(0)}KB</span>
                <span>{item.uploadedBy?.name || 'Unknown'}</span>
                <span>{formatDistanceToNow(new Date(item.createdAt), { addSuffix: true })}</span>
                {item.verified && <span className="text-green-400 flex items-center gap-1"><CheckCircle size={12} /> Verified</span>}
              </div>
            </div>
            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition">
              <button onClick={() => setPreviewUrl(previewUrl === item.url ? null : item.url)}
                className="p-1.5 hover:bg-[#12576D] rounded text-[#94A3B8] hover:text-[#DDF4F0]" title="Preview">
                <Eye size={16} />
              </button>
              <a href={item.url} download={item.fileName}
                className="p-1.5 hover:bg-[#12576D] rounded text-[#94A3B8] hover:text-[#DDF4F0]" title="Download">
                <Download size={16} />
              </a>
              {isAdmin && !item.verified && (
                <button onClick={() => handleVerify(item._id)}
                  className="p-1.5 hover:bg-[#12576D] rounded text-green-400 hover:text-green-300" title="Verify">
                  <CheckCircle size={16} />
                </button>
              )}
              {(isAdmin || isOwner) && (
                <button onClick={() => handleDelete(item._id)}
                  className="p-1.5 hover:bg-[#12576D] rounded text-red-400 hover:text-red-300" title="Delete">
                  <Trash2 size={16} />
                </button>
              )}
            </div>
          </div>
        );
      })}

      {previewUrl && (
        <div className="fixed inset-0 z-50 bg-[#0A3340]/80 flex items-center justify-center p-4" onClick={() => setPreviewUrl(null)}>
          <div className="max-w-4xl max-h-[90vh]" onClick={e => e.stopPropagation()}>
            {previewUrl.match(/\.(mp4|webm|mov)$/i) ? (
              <video src={previewUrl} controls className="max-h-[80vh] rounded-lg" />
            ) : previewUrl.match(/\.pdf$/i) ? (
              <iframe src={previewUrl} className="w-full h-[80vh] rounded-lg" />
            ) : (
              <img src={previewUrl} alt="evidence" className="max-h-[80vh] rounded-lg" />
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import type React from 'react';
import { X, ChevronLeft, ChevronRight, Star } from 'lucide-react';
import LazyImage from './LazyImage';

interface CarImage {
  url?: string;
  thumb?: string;
}

interface Car {
  images?: (string | CarImage)[];
  title?: string;
  isPromoted?: boolean;
}

interface GalleryModalProps {
  car: Car | null;
  initialIdx?: number;
  onClose: () => void;
}

function firstImage(car: Car | null, idx = 0): string | null {
  const imgs = car?.images || [];
  const img = imgs[idx];
  if (!img) return null;
  return typeof img === 'string' ? img : img?.url || null;
}

export default function GalleryModal({ car, initialIdx = 0, onClose }: GalleryModalProps) {
  const [idx, setIdx] = useState(initialIdx);
  const touchX = useRef<number | null>(null);

  const images = car?.images || [];
  const total = images.length;

  const prev = useCallback(() => setIdx(i => (i > 0 ? i - 1 : total - 1)), [total]);
  const next = useCallback(() => setIdx(i => (i < total - 1 ? i + 1 : 0)), [total]);

  useEffect(() => {
    const h = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowLeft') prev();
      if (e.key === 'ArrowRight') next();
    };
    window.addEventListener('keydown', h);
    return () => window.removeEventListener('keydown', h);
  }, [onClose, prev, next]);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = ''; };
  }, []);

  const handleTouchStart = useCallback((e: React.TouchEvent) => { touchX.current = e.touches[0].clientX; }, []);
  const handleTouchEnd = useCallback((e: React.TouchEvent) => {
    if (touchX.current === null) return;
    const dx = e.changedTouches[0].clientX - touchX.current;
    if (dx > 50) prev();
    else if (dx < -50) next();
    touchX.current = null;
  }, [prev, next]);

  if (!car || total === 0) return null;

  const src = firstImage(car, idx);

  return (
    <div
      onClick={onClose}
      onKeyDown={(e) => e.key === 'Escape' && onClose()}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      role="button"
      tabIndex={0}
      aria-label="Close gallery"
      style={{
        position: 'fixed', inset: 0, zIndex: 1000,
        background: 'rgba(10, 51, 64, 0.92)',
        display: 'flex', flexDirection: 'column',
        alignItems: 'center', justifyContent: 'center',
        cursor: 'zoom-out',
        animation: 'fadeIn 0.2s ease',
      }}
    >
      <button onClick={onClose} style={{
        position: 'absolute', top: 16, right: 16, zIndex: 10,
        background: 'rgba(10, 51, 64, 0.5)', border: '1px solid rgba(255,255,255,0.15)',
        borderRadius: '50%', width: 40, height: 40,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        color: '#fff', cursor: 'pointer', transition: 'all 0.2s',
      }}
        onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.15)'; }}
        onMouseLeave={e => { e.currentTarget.style.background = 'rgba(10, 51, 64, 0.5)'; }}
      >
        <X size={18} />
      </button>

      {total > 1 && (
        <>
          <button onClick={e => { e.stopPropagation(); prev(); }} style={{
            position: 'absolute', left: 16, top: '50%', transform: 'translateY(-50%)', zIndex: 10,
            background: 'rgba(10, 51, 64, 0.5)', border: '1px solid rgba(255,255,255,0.15)',
            borderRadius: '50%', width: 48, height: 48,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: '#fff', cursor: 'pointer', transition: 'all 0.2s',
          }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.15)'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'rgba(10, 51, 64, 0.5)'; }}
          >
            <ChevronLeft size={22} />
          </button>
          <button onClick={e => { e.stopPropagation(); next(); }} style={{
            position: 'absolute', right: 16, top: '50%', transform: 'translateY(-50%)', zIndex: 10,
            background: 'rgba(10, 51, 64, 0.5)', border: '1px solid rgba(255,255,255,0.15)',
            borderRadius: '50%', width: 48, height: 48,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: '#fff', cursor: 'pointer', transition: 'all 0.2s',
          }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.15)'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'rgba(10, 51, 64, 0.5)'; }}
          >
            <ChevronRight size={22} />
          </button>
        </>
      )}

      <div onClick={e => e.stopPropagation()} className="gallery-modal-image" style={{
        flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
        padding: '60px 80px', width: '100%', maxHeight: 'calc(100vh - 120px)',
        cursor: 'default',
      }}>
        <div style={{
          position: 'relative', maxWidth: '100%', maxHeight: '100%',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <LazyImage
            src={src}
            alt={car?.title || 'Vehicle'}
            style={{
              maxWidth: '100%', maxHeight: 'calc(100vh - 120px)',
              width: 'auto', height: 'auto',
              borderRadius: 4,
              objectFit: 'contain',
            }}
          />
          {car?.isPromoted && (
            <div style={{
              position: 'absolute', top: 12, right: 12,
              display: 'inline-flex', alignItems: 'center', gap: 4,
              background: 'rgba(19, 184, 166, 0.92)', backdropFilter: 'blur(8px)',
              borderRadius: 8, padding: '5px 10px',
            }}>
              <Star size={10} style={{ color: '#0a3340' }} />
              <span style={{ fontSize: 10, color: '#0a3340', fontWeight: 800, letterSpacing: '0.08em' }}>FEATURED</span>
            </div>
          )}
        </div>
      </div>

      <div onClick={e => e.stopPropagation()} style={{
        height: 80, display: 'flex', alignItems: 'center', justifyContent: 'center',
        gap: 8, padding: '0 16px', width: '100%',
        background: 'rgba(10, 51, 64, 0.4)',
      }}>
        <span style={{ fontSize: 11, color: 'rgba(255,255,255,0.3)', fontWeight: 600, letterSpacing: '0.05em' }}>
          {idx + 1} / {total}
        </span>
        <div style={{ display: 'flex', gap: 6, alignItems: 'center', overflow: 'auto', padding: '0 12px', flex: 1, justifyContent: 'center' }}>
          {images.map((img, i) => {
            const thumbSrc = typeof img === 'string' ? img : (img?.thumb || img?.url);
            return (
              <button key={i} onClick={() => setIdx(i)} style={{
                width: 48, height: 36, flexShrink: 0,
                border: i === idx ? '2px solid var(--brand)' : '2px solid rgba(255,255,255,0.1)',
                borderRadius: 4, overflow: 'hidden', cursor: 'pointer',
                padding: 0, background: '#0a3340', transition: 'border 0.2s',
                opacity: i === idx ? 1 : 0.5,
              }}>
                <img src={thumbSrc} alt="" loading="lazy" decoding="async" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef, type TouchEvent } from 'react';
import { ChevronLeft, ChevronRight, MapPin, Shield, Star, Eye, Clock } from 'lucide-react';
import { formatKES, timeAgo } from '../utils/helpers';
import { carsAPI } from '../api/api';

interface FeaturedCar {
  _id: string;
  title: string;
  brand: string;
  model: string;
  price: number;
  currentBid?: number;
  year: number;
  mileage?: number | string;
  fuel?: string;
  location?: { city?: string };
  images?: Array<{ url?: string } | string>;
  isPromoted?: boolean;
  views?: number;
  createdAt?: string;
  escrowEnabled?: boolean;
  auctionStatus?: string;
  auctionEnd?: string;
  ntsaVerified?: boolean;
  dealer?: { name?: string; isBank?: boolean };
}

interface HeroCarouselProps {
  onViewCar: (car: FeaturedCar) => void;
}

export default function HeroCarousel({ onViewCar }: HeroCarouselProps) {
  const [cars, setCars] = useState<FeaturedCar[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const autoPlayRef = useRef<NodeJS.Timeout | null>(null);

  // Fetch featured cars (promoted or top-viewed) using API client
  useEffect(() => {
    const fetchFeatured = async () => {
      try {
        const data = await carsAPI.list({ page: 1, limit: 20, status: 'active' });
        const fetchedCars = data?.cars || data?.data || [];
        // Filter for promoted or top viewed
        const featured = fetchedCars.filter((car: FeaturedCar) =>
          car.isPromoted || (car.views && car.views > 100)
        ).slice(0, 5);
        setCars(featured.length > 0 ? featured : fetchedCars.slice(0, 5));
      } catch {
        // API unavailable; keep the featured carousel empty
      } finally {
        setLoading(false);
      }
    };
    fetchFeatured();
  }, []);

  const displayCars = cars;

  const nextSlide = useCallback(() => {
    setCurrentIndex(prev => (prev + 1) % displayCars.length);
  }, [displayCars.length]);

  const prevSlide = useCallback(() => {
    setCurrentIndex(prev => (prev - 1 + displayCars.length) % displayCars.length);
  }, [displayCars.length]);

  const goToSlide = useCallback((index: number) => {
    setCurrentIndex(index);
  }, []);

  // Auto-play
  useEffect(() => {
    if (displayCars.length <= 1) return;
    autoPlayRef.current = setInterval(nextSlide, 5000);
    return () => {
      if (autoPlayRef.current) clearInterval(autoPlayRef.current);
    };
  }, [nextSlide, displayCars.length]);

  const pauseAutoplay = () => {
    if (autoPlayRef.current) clearInterval(autoPlayRef.current);
  };

  const resumeAutoplay = () => {
    if (displayCars.length <= 1) return;
    autoPlayRef.current = setInterval(nextSlide, 5000);
  };

  // Touch handlers for swipe
  const handleTouchStart = (e: TouchEvent) => {
    setTouchStart(e.touches[0].clientX);
    pauseAutoplay();
  };

  const handleTouchEnd = (e: TouchEvent) => {
    if (touchStart === null) return;
    const touchEnd = e.changedTouches[0].clientX;
    const diff = touchStart - touchEnd;
    if (diff > 50) nextSlide();
    else if (diff < -50) prevSlide();
    setTouchStart(null);
    resumeAutoplay();
  };

  const currentCar = displayCars[currentIndex];
  if (!currentCar) return null;

  const firstImage = (car: FeaturedCar) => {
    const imgs = car.images || [];
    const img = imgs[0];
    if (typeof img === 'string') return img;
    return img?.url || '';
  };

  return (
    <div
      className="relative w-full overflow-hidden rounded-2xl"
      onMouseEnter={pauseAutoplay}
      onMouseLeave={resumeAutoplay}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
    >
      {/* Slides Container */}
      <div
        className="flex transition-transform duration-500 ease-out"
        style={{ transform: `translateX(-${currentIndex * 100}%)` }}
      >
        {displayCars.map((car, idx) => (
          <div
            key={car._id || idx}
            className="w-full flex-shrink-0"
            onClick={() => onViewCar(car as any)}
          >
            <div className="relative aspect-[21/9] bg-[#12576D] overflow-hidden">
              <img
                src={firstImage(car)}
                alt={car.title}
                className="w-full h-full object-cover"
                loading={idx === 0 ? 'eager' : 'lazy'}
              />

              {/* Gradient Overlay */}
              <div className="absolute inset-0 bg-gradient-to-r from-[#0A3340]/90 via-[#0A3340]/50 to-transparent" />
              <div className="absolute inset-0 bg-gradient-to-t from-[#0A3340]/80 via-transparent to-transparent" />

              {/* Content */}
              <div className="absolute inset-0 flex items-center">
                <div className="max-w-7xl mx-auto w-full px-6 sm:px-8 lg:px-12">
                  <div className="max-w-xl">
                    {/* Badges */}
                    <div className="flex flex-wrap gap-2 mb-4">
                      {car.isPromoted && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-[#13B8A6]/90 text-[#0A3340] text-xs font-bold rounded-full">
                          <Star size={12} /> FEATURED
                        </span>
                      )}
                      {car.escrowEnabled && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-[#12576D]/80 text-white text-xs font-semibold rounded-full backdrop-blur-sm">
                          <Shield size={12} /> ESCROW
                        </span>
                      )}
                      {car.ntsaVerified && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-emerald-500/90 text-white text-xs font-semibold rounded-full">
                          ✓ NTSA OK
                        </span>
                      )}
                    </div>

                    {/* Title */}
                    <h2 className="font-serif text-2xl sm:text-3xl lg:text-4xl text-white font-bold mb-2 leading-tight">
                      {car.title}
                    </h2>

                    {/* Quick Specs */}
                    <div className="flex flex-wrap items-center gap-4 text-white/70 text-sm mb-4">
                      {car.year && <span>{car.year}</span>}
                      {car.mileage && <span>· {car.mileage}</span>}
                      {car.fuel && <span>· {car.fuel}</span>}
                      {car.location?.city && (
                        <span className="flex items-center gap-1">
                          <MapPin size={14} /> {car.location.city}
                        </span>
                      )}
                    </div>

                    {/* Price & Stats */}
                    <div className="flex items-end justify-between">
                      <div>
                        <p className="text-white/50 text-xs font-semibold uppercase tracking-wider mb-1">
                          {car.currentBid ? 'Current Bid' : 'Price'}
                        </p>
                        <p className="font-serif text-3xl sm:text-4xl text-[#13B8A6] font-bold">
                          {formatKES(car.currentBid || car.price)}
                        </p>
                      </div>

                      <div className="hidden sm:flex items-center gap-4 text-white/50 text-xs">
                        {car.views && (
                          <span className="flex items-center gap-1">
                            <Eye size={14} /> {car.views.toLocaleString()}
                          </span>
                        )}
                        {car.createdAt && (
                          <span className="flex items-center gap-1">
                            <Clock size={14} /> {timeAgo(car.createdAt)}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              {/* Live Badge */}
              {car.auctionStatus === 'live' && (
                <div className="absolute top-4 left-4 flex items-center gap-2 px-3 py-1.5 bg-red-500/90 text-white text-xs font-bold rounded-full">
                  <span className="w-2 h-2 bg-white rounded-full animate-pulse" />
                  LIVE AUCTION
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Navigation Arrows */}
      {displayCars.length > 1 && (
        <>
          <button
            onClick={(e) => { e.stopPropagation(); prevSlide(); }}
            className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm text-white rounded-full flex items-center justify-center transition-all z-10"
          >
            <ChevronLeft size={20} />
          </button>
          <button
            onClick={(e) => { e.stopPropagation(); nextSlide(); }}
            className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm text-white rounded-full flex items-center justify-center transition-all z-10"
          >
            <ChevronRight size={20} />
          </button>
        </>
      )}

      {/* Pagination Dots */}
      {displayCars.length > 1 && (
        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2 z-10">
          {displayCars.map((_, idx) => (
            <button
              key={idx}
              onClick={(e) => { e.stopPropagation(); goToSlide(idx); }}
              className={`w-2 h-2 rounded-full transition-all ${
                idx === currentIndex
                  ? 'w-6 bg-[#13B8A6]'
                  : 'bg-white/40 hover:bg-white/60'
              }`}
            />
          ))}
        </div>
      )}

      {/* Loading State */}
      {loading && (
        <div className="absolute inset-0 bg-[#12576D] animate-pulse flex items-center justify-center">
          <div className="text-[#13B8A6] font-serif text-xl">Loading featured vehicles...</div>
        </div>
      )}
    </div>
  );
}

