import React, { useEffect, useMemo, useState } from 'react';
import { getVisibleAdSlots, AdDisplayMode, AdSlot } from '../services/adApi';
import { adminAPI } from '../api/api';

/**
 * KAYAD's broadcast notice board. Content, ordering, colors, visibility and
 * animation behavior are persisted through the admin Ad Manager.
 */
export const TopNoticeStrip: React.FC = () => {
  const [slots, setSlots] = useState<AdSlot[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [fadeIndex, setFadeIndex] = useState(0);
  const [fadeVisible, setFadeVisible] = useState(true);
  const [heroTickerConfig, setHeroTickerConfig] = useState({ enabled: true, fallbackText: 'KAYAD · Verified vehicles across East Africa · Live auctions · Transparent bidding · Protected transactions', backgroundColor: '#0A3340', textColor: '#FFFFFF', heightPx: 36, scrollSeconds: 34, direction: 'left' as 'left' | 'right', transition: 'scroll' as 'scroll' | 'fade' | 'pop' | 'slide' });

  useEffect(() => {
    let cancelled = false;
    Promise.allSettled([getVisibleAdSlots('top_ticker'), adminAPI.getPublicConfig()])
      .then(([adsResult, configResult]) => {
        if (cancelled) return;
        if (adsResult.status === 'fulfilled') setSlots(adsResult.value);
        if (configResult.status === 'fulfilled') {
          const cfg = (configResult.value as any)?.config || configResult.value || {};
          const hp = cfg?.heroPresentation || {};
          setHeroTickerConfig((prev) => ({
            ...prev,
            enabled: hp.tickerEnabled !== false,
            fallbackText: hp.tickerFallbackText || prev.fallbackText,
            backgroundColor: hp.tickerBackgroundColor || prev.backgroundColor,
            textColor: hp.tickerTextColor || prev.textColor,
            heightPx: Math.max(28, Math.min(60, Number(hp.tickerHeightPx) || prev.heightPx)),
            scrollSeconds: Math.max(10, Math.min(90, Number(hp.tickerScrollSeconds) || prev.scrollSeconds)),
            direction: hp.tickerDirection === 'right' ? 'right' : 'left',
            transition: ['scroll', 'fade', 'pop', 'slide'].includes(hp.tickerTransition) ? hp.tickerTransition : 'scroll',
          }));
        }
      })
      .catch(() => { /* notice board must never block the main site */ })
      .finally(() => { if (!cancelled) setLoaded(true); });
    return () => { cancelled = true; };
  }, []);

  const mode: AdDisplayMode = useMemo(() => heroTickerConfig.transition === 'fade' || heroTickerConfig.transition === 'pop' || heroTickerConfig.transition === 'slide' ? 'fade' : (slots[0]?.displayMode || 'scroll'), [slots, heroTickerConfig.transition]);
  const activeFadeDuration = Math.max(1200, slots[0]?.fadeDurationMs || 4500);
  const scrollDuration = Math.max(10, slots[0]?.scrollDurationSeconds || 28);

  useEffect(() => {
    if (mode !== 'fade' || slots.length < 2) return;
    let swapTimer: number | undefined;
    const timer = window.setInterval(() => {
      setFadeVisible(false);
      swapTimer = window.setTimeout(() => {
        setFadeIndex((current) => (current + 1) % slots.length);
        setFadeVisible(true);
      }, 350);
    }, activeFadeDuration);
    return () => {
      window.clearInterval(timer);
      if (swapTimer !== undefined) window.clearTimeout(swapTimer);
    };
  }, [mode, activeFadeDuration, slots.length]);

  useEffect(() => {
    if (fadeIndex >= slots.length) setFadeIndex(0);
  }, [fadeIndex, slots.length]);

  if (!heroTickerConfig.enabled) return null;

  if (!loaded || slots.length === 0) {
    const fallback = heroTickerConfig.fallbackText.split(' · ').filter(Boolean);
    const items = [...fallback, ...fallback];
    return (
      <div className="kayad-top-ticker w-full overflow-hidden border-b border-white/10" style={{ height: heroTickerConfig.heightPx, backgroundColor: heroTickerConfig.backgroundColor, ['--kayad-ticker-height' as any]: `${heroTickerConfig.heightPx}px` }} role="region" aria-label="KAYAD notices">
        <div className="flex min-w-max h-full animate-marquee whitespace-nowrap" style={{ animationDuration: `${heroTickerConfig.scrollSeconds}s`, animationDirection: heroTickerConfig.direction === 'right' ? 'reverse' : 'normal' }}>
          {items.map((item, index) => (
            <span key={`${item}-${index}`} aria-hidden={index >= fallback.length ? true : undefined} className="flex items-center gap-6 px-8 py-2 text-[11px] sm:text-xs font-semibold tracking-[0.01em]" style={{ color: heroTickerConfig.textColor }}>
              <span className="h-1.5 w-1.5 rounded-full bg-[#13B8A6]" aria-hidden="true" />
              {item}
              <span className="text-white/25" aria-hidden="true">|</span>
            </span>
          ))}
        </div>
      </div>
    );
  }

  const renderSlot = (slot: AdSlot, extraClass = '') => {
    const content = (
      <span className={`flex items-center justify-center gap-2 px-5 sm:px-8 py-2 text-[11px] sm:text-xs font-semibold tracking-[0.01em] ${extraClass}`}>
        <span className="font-bold">{slot.title}</span>
        {slot.tagline && <span className="opacity-80 font-normal">— {slot.tagline}</span>}
        {slot.priceTag && <span className="font-bold">{slot.priceTag}</span>}
        {slot.buttonText && <span className="font-bold underline underline-offset-2">{slot.buttonText}</span>}
      </span>
    );

    return slot.buttonUrl ? (
      <a href={slot.buttonUrl} className="block" aria-label={slot.title}>{content}</a>
    ) : content;
  };

  if (mode === 'fade') {
    const slot = slots[fadeIndex];
    return (
      <div
        className="kayad-top-ticker w-full overflow-hidden border-b border-white/10" style={{ height: heroTickerConfig.heightPx, backgroundColor: heroTickerConfig.backgroundColor, ['--kayad-ticker-height' as any]: `${heroTickerConfig.heightPx}px` }}
        role="region"
        aria-label="KAYAD notices"
        aria-live="polite"
      >
        <div
          className={`h-full flex items-center justify-center transition-all duration-700 ease-in-out ${heroTickerConfig.transition === 'pop' ? (fadeVisible ? 'scale-100' : 'scale-95') : ''} ${heroTickerConfig.transition === 'slide' ? (fadeVisible ? 'translate-y-0' : 'translate-y-2') : ''}`}
          key={slot.id}
          style={{
            opacity: (fadeVisible ? 1 : 0) * (slot.opacity / 100),
            backgroundColor: slot.backgroundColor || '#0A3340',
            color: slot.textColor || '#FFFFFF',
          }}
        >
          {renderSlot(slot)}
        </div>
      </div>
    );
  }

  const loopItems = [...slots, ...slots];
  return (
    <div
      className="kayad-top-ticker w-full overflow-hidden border-b border-white/10" style={{ height: heroTickerConfig.heightPx, backgroundColor: heroTickerConfig.backgroundColor, ['--kayad-ticker-height' as any]: `${heroTickerConfig.heightPx}px` }}
      role="region"
      aria-label="KAYAD notices"
    >
      <div
        className="flex min-w-max h-full animate-marquee hover:[animation-play-state:paused] whitespace-nowrap"
        style={{ animationDuration: `${Math.max(10, heroTickerConfig.scrollSeconds || scrollDuration)}s`, animationDirection: heroTickerConfig.direction === 'right' ? 'reverse' : 'normal', transform: heroTickerConfig.transition === 'slide' ? 'translateZ(0)' : undefined }}
      >
        {loopItems.map((slot, index) => (
          <span
            key={`${slot.id}-${index}`}
            aria-hidden={index >= slots.length ? true : undefined}
            style={{
              backgroundColor: slot.backgroundColor || '#0A3340',
              color: slot.textColor || '#FFFFFF',
              opacity: slot.opacity / 100,
            }}
          >
            {renderSlot(slot)}
          </span>
        ))}
      </div>
    </div>
  );
};

export default TopNoticeStrip;

import React from 'react';
import { Vehicle } from '../types';
import { isEscrowApplicable, getEscrowBadgeLabel } from '../utils/escrow';
import {
  ShieldCheck,
  CheckCircle2,
  Lock,
  Landmark,
  Gavel,
  Zap,
  UserCheck
} from 'lucide-react';

interface TrustBadgeMatrixProps {
  vehicle: Vehicle;
  variant?: 'compact' | 'full' | 'pills';
  className?: string;
}

export const TrustBadgeMatrix: React.FC<TrustBadgeMatrixProps> = ({
  vehicle,
  variant = 'full',
  className = ''
}) => {
  const isPrivateSeller = vehicle.sellerType === 'Private Seller';

  // Rule: Private sellers ALWAYS require escrow; Dealers ONLY display escrow if explicitly enabled (escrowEligible = true)
  const isEscrowActive = isEscrowApplicable(vehicle);

  // Rule: Inspection badges ONLY appear when inspection exists (inspectionPassed = true)
  const isInspectionActive = Boolean(vehicle.inspectionPassed);

  // Rule: Auction badges ONLY appear for auction-enabled listings (isAuction = true)
  const isAuctionActive = Boolean(vehicle.isAuction);

  // Finance badge only if financeAvailable = true
  const isFinanceActive = Boolean(vehicle.financeAvailable);

  // Verified status
  const isVerifiedSeller = Boolean(vehicle.verified);

  if (variant === 'compact') {
    return (
      <div className={`flex flex-wrap items-center gap-1.5 ${className}`}>
        {/* Verified Seller / Dealer Badge */}
        {isVerifiedSeller && (
          <span className="inline-flex items-center gap-1 bg-[#176B87] text-white text-[10px] font-extrabold px-2 py-0.5 rounded-md shadow-xs">
            <ShieldCheck className="w-3 h-3 text-[#13B8A6] shrink-0" />
            {vehicle.sellerType}
          </span>
        )}

        {/* Inspection Badge - ONLY when inspectionPassed is true */}
        {isInspectionActive && (
          <span className="inline-flex items-center gap-1 bg-emerald-700 text-white text-[10px] font-extrabold px-2 py-0.5 rounded-md shadow-xs">
            <CheckCircle2 className="w-3 h-3 shrink-0" />
            Inspected
          </span>
        )}

        {/* Escrow Badge - ONLY when applicable (Always for private, explicit for dealer) */}
        {isEscrowActive && (
          <span className="inline-flex items-center gap-1 bg-[#13B8A6] text-[#0A3340] text-[10px] font-black px-2 py-0.5 rounded-md shadow-xs">
            <Lock className="w-3 h-3 shrink-0" />
            {isPrivateSeller ? 'Escrow Required' : 'Escrow Vault Enabled'}
          </span>
        )}

        {/* Auction Badge - ONLY when isAuction is true */}
        {isAuctionActive && (
          <span className="inline-flex items-center gap-1 bg-rose-600 text-white text-[10px] font-extrabold px-2 py-0.5 rounded-md shadow-xs animate-pulse">
            <Gavel className="w-3 h-3 shrink-0 text-[#5AAFA4]" />
            Live Auction
          </span>
        )}

        {/* Finance Badge */}
        {isFinanceActive && (
          <span className="inline-flex items-center gap-1 bg-[#F3FAF9] text-[#0A3340] border border-[#D7E7E4] text-[10px] font-bold px-2 py-0.5 rounded-md">
            <Landmark className="w-3 h-3 text-[#176B87] shrink-0" />
            Finance Ready
          </span>
        )}
      </div>
    );
  }

  if (variant === 'pills') {
    return (
      <div className={`flex flex-wrap gap-2 text-xs ${className}`}>
        {/* Seller Trust Pill */}
        {isVerifiedSeller && (
          <div className="bg-[#F6FAF9] p-2 rounded-xl border border-[#D7E7E4] flex items-center gap-2 flex-1 min-w-[130px]">
            {isPrivateSeller ? (
              <UserCheck className="w-4 h-4 text-[#176B87] shrink-0" />
            ) : (
              <ShieldCheck className="w-4 h-4 text-[#176B87] shrink-0" />
            )}
            <div className="min-w-0">
              <p className="text-[9px] text-[#94A3B8] font-bold uppercase truncate">Seller</p>
              <p className="font-extrabold text-[#176B87] truncate text-[11px]">{vehicle.sellerType}</p>
            </div>
          </div>
        )}

        {/* Inspection Pill - Only if inspection exists */}
        {isInspectionActive && (
          <div className="bg-emerald-50/80 p-2 rounded-xl border border-emerald-200 flex items-center gap-2 flex-1 min-w-[130px]">
            <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
            <div className="min-w-0">
              <p className="text-[9px] text-emerald-800 font-bold uppercase truncate">Inspection</p>
              <p className="font-extrabold text-emerald-900 truncate text-[11px]">Certified Passed</p>
            </div>
          </div>
        )}

        {/* Escrow Pill - Only if escrow active */}
        {isEscrowActive && (
          <div className="bg-[#F3FAF9] p-2 rounded-xl border border-[#BDE5DE] flex items-center gap-2 flex-1 min-w-[130px]">
            <Lock className="w-4 h-4 text-[#176B87] shrink-0" />
            <div className="min-w-0">
              <p className="text-[9px] text-[#0A3340] font-bold uppercase truncate">Escrow Vault</p>
              <p className="font-extrabold text-[#0A3340] truncate text-[11px]">
                {isPrivateSeller ? 'Mandatory Escrow' : 'Verified Escrow'}
              </p>
            </div>
          </div>
        )}

        {/* Auction Pill - Only if auction active */}
        {isAuctionActive && (
          <div className="bg-rose-50 p-2 rounded-xl border border-rose-200 flex items-center gap-2 flex-1 min-w-[130px]">
            <Gavel className="w-4 h-4 text-rose-600 shrink-0" />
            <div className="min-w-0">
              <p className="text-[9px] text-rose-800 font-bold uppercase truncate">Listing Type</p>
              <p className="font-extrabold text-rose-900 truncate text-[11px]">Live Auction</p>
            </div>
          </div>
        )}

        {/* Financing Pill - Only if finance active */}
        {isFinanceActive && (
          <div className="bg-[#F3FAF9]/80 p-2 rounded-xl border border-[#D7E7E4] flex items-center gap-2 flex-1 min-w-[130px]">
            <Landmark className="w-4 h-4 text-[#176B87] shrink-0" />
            <div className="min-w-0">
              <p className="text-[9px] text-[#0E4655] font-bold uppercase truncate">Asset Finance</p>
              <p className="font-extrabold text-[#0A3340] truncate text-[11px]">Pre-Approved</p>
            </div>
          </div>
        )}
      </div>
    );
  }

  // Full Trust Matrix Banner - Rendered in Detail Modal
  const activeBadgesCount = [isVerifiedSeller, isInspectionActive, isEscrowActive, isAuctionActive, isFinanceActive].filter(Boolean).length;
  if (activeBadgesCount === 0) return null;

  return (
    <div className={`bg-gradient-to-r from-[#0A3340] via-[#176B87] to-[#0A3340] text-white p-4 rounded-2xl shadow-lg border border-[#91CEC5]/30 space-y-3 ${className}`}>
      <div className="flex items-center justify-between pb-2 border-b border-white/10 text-xs">
        <span className="font-extrabold uppercase tracking-wider text-[#13B8A6] flex items-center gap-1.5 font-display">
          <ShieldCheck className="w-4 h-4" />
          Verified Listing Specifications
        </span>
        <span className="bg-[#13B8A6] text-[#0A3340] text-[10px] font-black px-2.5 py-0.5 rounded-full">
          {vehicle.sellerType}
        </span>
      </div>

      <div className="flex flex-wrap gap-4 text-xs">
        {/* 1. Verified Seller */}
        {isVerifiedSeller && (
          <div className="space-y-0.5 min-w-[120px]">
            <p className="text-[10px] text-[#BDE5DE] uppercase font-bold flex items-center gap-1">
              <ShieldCheck className="w-3 h-3 text-[#13B8A6]" /> Seller Status
            </p>
            <p className="font-bold text-white text-xs">{vehicle.sellerType}</p>
            <p className="text-[10px] text-[#BDE5DE]">{vehicle.sellerName}</p>
          </div>
        )}

        {/* 2. Inspection Status - Only when passed */}
        {isInspectionActive && (
          <div className="space-y-0.5 min-w-[120px]">
            <p className="text-[10px] text-[#BDE5DE] uppercase font-bold flex items-center gap-1">
              <CheckCircle2 className="w-3 h-3 text-emerald-400" /> Technical Audit
            </p>
            <p className="font-bold text-emerald-300 text-xs">Inspection on record</p>
            <p className="text-[10px] text-[#BDE5DE]">Logbook & Engine Audited</p>
          </div>
        )}

        {/* 3. Escrow Status - Only when active */}
        {isEscrowActive && (
          <div className="space-y-0.5 min-w-[120px]">
            <p className="text-[10px] text-[#BDE5DE] uppercase font-bold flex items-center gap-1">
              <Lock className="w-3 h-3 text-[#13B8A6]" /> Payment Protection
            </p>
            <p className="font-bold text-[#5AAFA4] text-xs">
              {isPrivateSeller ? 'Escrow Mandatory' : 'Escrow Vault Enabled'}
            </p>
            <p className="text-[10px] text-[#BDE5DE]">Funds recorded as held by KAYAD</p>
          </div>
