                <span className="flex items-center gap-2">
                  <Zap className="w-4 h-4 text-[#176B87]" /> Powertrain & Engine Specifications
                </span>
                {openSpecSections.powertrain ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
