import { useEffect, useState } from 'react';
import { CreditCard, Landmark, Smartphone, ShieldCheck } from 'lucide-react';
import { getCustomerPaymentMethods, type CustomerPaymentContext, type CustomerPaymentGateway } from '@/lib/payment-gateways';

const icons = { 'mobile-money': Smartphone, card: CreditCard, bank: Landmark } as const;

export function CustomerPaymentMethods({ context, value, onChange, onGatewayChange }: { context: CustomerPaymentContext; value: string | null; onChange: (method: 'mpesa'|'card'|'bank_transfer') => void; onGatewayChange?: (gatewayKey: string) => void }) {
  const [methods, setMethods] = useState<CustomerPaymentGateway[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => { let active = true; setLoading(true); setError(''); getCustomerPaymentMethods(context).then(rows => { if (!active) return; setMethods(rows); if (!value && rows[0]) { onChange(rows[0].payment_method); onGatewayChange?.(rows[0].gateway_key); } }).catch(() => { if (active) setError('Payment options are temporarily unavailable. Please try again.'); }).finally(() => active && setLoading(false)); return () => { active = false; }; }, [context]);

  if (loading) return <div className="rounded-xl border p-4 text-sm text-muted-foreground">Loading secure payment options…</div>;
  if (error) return <div className="rounded-xl border border-[#BDE5DE] bg-[#F3FAF9] p-4 text-sm text-[#0A3340]">{error}</div>;
  if (!methods.length) return <div className="rounded-xl border border-[#BDE5DE] bg-[#F3FAF9] p-4 text-sm text-[#0A3340]">Online payment is not currently available. Please contact Topline for payment instructions.</div>;

  return <div className="space-y-3"><div className="flex items-center gap-2 text-sm font-semibold"><ShieldCheck className="h-4 w-4"/> Secure payment options</div>{methods.map(method => { const Icon = icons[method.icon_key as keyof typeof icons] || CreditCard; return <label key={method.gateway_key} className={`flex cursor-pointer items-start gap-3 rounded-xl border p-4 transition ${value === method.payment_method ? 'border-primary bg-primary/5' : 'hover:bg-muted/40'}`}><input type="radio" name={`payment-${context}`} className="mt-1" checked={value === method.payment_method} onChange={() => onChange(method.payment_method)}/><Icon className="mt-0.5 h-5 w-5"/><span><span className="block font-medium">{method.display_name}</span>{method.customer_description && <span className="block text-xs text-muted-foreground mt-1">{method.customer_description}</span>}</span></label>; })}</div>;
}

import { useState } from 'react';
import {
  LayoutDashboard,
  Gavel,
  ShieldCheck,
  Heart,
  Plus,
  Car,
  User,
  Building2,
  DollarSign,
  ArrowUpRight,
  Sparkles,
  FileText,
  BellRing,
  Bell,
  Trash2,
  ExternalLink,
  TrendingDown
} from 'lucide-react';
import { useMarketplace } from '../../context/MarketplaceContext';
import { useAuth } from '../../context/AuthContext';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';
import { Input } from '../ui/Input';
import { Modal } from '../ui/Modal';
import { VehicleCard } from '../gallery/VehicleCard';
import { SearchBar } from '../ui/SearchBar';
import type React from 'react';
import type { FC } from 'react';

export const DashboardPage: FC = () => {
  const { vehicles, savedVehicleIds, bids, escrowContracts, navigateTo, addNewVehicle, priceAlerts, removePriceAlert } = useMarketplace();
  const { user } = useAuth();

  const [activeTab, setActiveTab] = useState<'overview' | 'bids' | 'escrow' | 'saved' | 'alerts'>('overview');
  const [searchQuery, setSearchQuery] = useState('');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // New Listing Form state
  const [newTitle, setNewTitle] = useState('');
  const [newMake, setNewMake] = useState('Porsche');
  const [newPrice, setNewPrice] = useState('125000');
  const [newYear, setNewYear] = useState('2023');
  const [newVin, setNewVin] = useState('');

  const savedVehicles = vehicles.filter(v => savedVehicleIds.includes(v.id));
  const myBids = bids.filter(b => b.bidderId === user?.id || b.bidderName === user?.name);

  const filteredSavedVehicles = savedVehicles.filter(v => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return v.title?.toLowerCase().includes(q) || v.make?.toLowerCase().includes(q) || v.vin?.toLowerCase().includes(q);
  });

  const filteredBids = myBids.filter(b => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return b.vehicleId?.toLowerCase().includes(q) || b.amount?.toString().includes(q);
  });

  const handleCreateListing = (e: React.FormEvent) => {
    e.preventDefault();
    addNewVehicle({
      title: newTitle || `${newYear} ${newMake} Performance Edition`,
      make: newMake,
      price: parseFloat(newPrice) || 100000,
      buyNowPrice: parseFloat(newPrice) || 100000,
      year: parseInt(newYear) || 2023,
      vin: newVin || 'VIN' + Math.floor(Math.random() * 90000000)
    });
    setIsAddModalOpen(false);
    setNewTitle('');
  };

  return (
    <div className="py-10 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto space-y-8 bg-[#F6FAF9]">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-6 border-b border-[#D7E7E4]">
        <div>
          <div className="flex items-center gap-2">
            <Badge variant="blue" icon={<LayoutDashboard className="w-3.5 h-3.5" />}>
              KAYAD Workspace
            </Badge>
            <span className="text-xs text-[#64748b] capitalize font-bold">Role: {user?.role ?? 'user'}</span>
          </div>
          <h1 className="text-3xl font-extrabold text-[#176B87] font-serif tracking-tight mt-1">
            Welcome back, {user?.name || 'Member'}
          </h1>
        </div>

        <div className="flex items-center gap-3">
          {user?.role === 'dealer' && (
            <Button
              variant="primary"
              className="bg-[#176B87] hover:bg-[#0A3340] text-white font-bold"
              onClick={() => setIsAddModalOpen(true)}
              leftIcon={<Plus className="w-4 h-4" />}
            >
              List New Vehicle
            </Button>
          )}
        </div>
      </div>

      {/* Workspace Metric Cards */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
        <div className="p-4 rounded-2xl bg-white border border-[#D7E7E4] shadow-xs">
          <span className="text-xs font-bold text-[#64748b] uppercase tracking-wider block">Active Bids</span>
          <span className="text-2xl font-black text-[#176B87] font-serif">{myBids.length}</span>
        </div>
        <div className="p-4 rounded-2xl bg-white border border-[#D7E7E4] shadow-xs">
          <span className="text-xs font-bold text-[#64748b] uppercase tracking-wider block">Saved Vehicles</span>
          <span className="text-2xl font-black text-[#DC3545] font-serif">{savedVehicles.length}</span>
        </div>
        <div className="p-4 rounded-2xl bg-white border border-[#D7E7E4] shadow-xs">
          <span className="text-xs font-bold text-[#64748b] uppercase tracking-wider block">Price Alerts</span>
          <span className="text-2xl font-black text-[#13B8A6] font-serif">{priceAlerts.length}</span>
        </div>
        <div className="p-4 rounded-2xl bg-white border border-[#D7E7E4] shadow-xs">
          <span className="text-xs font-bold text-[#64748b] uppercase tracking-wider block">Escrow Deals</span>
          <span className="text-2xl font-black text-[#13B8A6] font-serif">{escrowContracts.length}</span>
        </div>
        <div className="p-4 rounded-2xl bg-white border border-[#D7E7E4] shadow-xs">
          <span className="text-xs font-bold text-[#64748b] uppercase tracking-wider block">Inventory</span>
          <span className="text-2xl font-black text-[#176B87] font-serif">{vehicles.length}</span>
        </div>
      </div>

      {/* Tabs Switcher */}
      <div className="flex items-center gap-2 border-b border-[#D7E7E4] pb-2 overflow-x-auto no-scrollbar">
        {[
          { id: 'overview', label: 'Overview' },
          { id: 'bids', label: 'Bidding History' },
          { id: 'alerts', label: `Price Alerts (${priceAlerts.length})` },
          { id: 'escrow', label: 'Escrow Contracts' },
          { id: 'saved', label: 'Saved Vehicles' },
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-4 py-2 text-xs font-bold rounded-xl transition-all whitespace-nowrap cursor-pointer ${
              activeTab === tab.id
                ? 'bg-[#176B87] text-white font-bold shadow-xs'
                : 'text-[#64748b] hover:text-[#176B87]'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Standardized KAYAD Search Bar */}
      <SearchBar
        value={searchQuery}
        onChange={setSearchQuery}
        placeholder="Search workspace records by vehicle title, make, VIN, or bid..."
        resultCount={
          activeTab === 'saved' || activeTab === 'overview'
            ? filteredSavedVehicles.length
            : activeTab === 'bids'
            ? filteredBids.length
            : escrowContracts.length
        }
        badgeLabel={`WORKSPACE · ${activeTab.toUpperCase()}`}
      />

      {/* Tab Content */}
      {activeTab === 'overview' && (
        <div className="space-y-6">
          <h3 className="text-base font-extrabold text-[#176B87] font-serif">Your Saved Favorites ({filteredSavedVehicles.length})</h3>
          {filteredSavedVehicles.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {filteredSavedVehicles.map(v => (
                <VehicleCard key={v.id} vehicle={v} />
              ))}
            </div>
          ) : (
            <div className="p-8 text-center rounded-2xl bg-white border border-[#D7E7E4] text-[#64748b] font-mono text-xs">
              No matching saved vehicles found in workspace.
            </div>
          )}
        </div>
      )}

      {activeTab === 'saved' && (
        <div className="space-y-6">
          <h3 className="text-base font-extrabold text-[#176B87] font-serif">Saved Favorites ({filteredSavedVehicles.length})</h3>
          {filteredSavedVehicles.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {filteredSavedVehicles.map(v => (
                <VehicleCard key={v.id} vehicle={v} />
              ))}
            </div>
          ) : (
            <div className="p-8 text-center rounded-2xl bg-white border border-[#D7E7E4] text-[#64748b] font-mono text-xs">
              No matching saved vehicles found.
            </div>
          )}
        </div>
      )}

      {activeTab === 'bids' && (
        <div className="space-y-4">
          <h3 className="text-base font-extrabold text-[#176B87] font-serif">Active Bidding Activity ({filteredBids.length})</h3>
          {filteredBids.length > 0 ? (
            <div className="bg-white border border-[#D7E7E4] rounded-2xl divide-y divide-[#D7E7E4] shadow-xs">
              {filteredBids.map((bid, idx) => (
                <div key={idx} className="p-4 flex items-center justify-between text-xs font-mono font-bold">
                  <div>
                    <span className="text-[#176B87] font-extrabold block">Vehicle ID: {bid.vehicleId}</span>
                    <span className="text-[#64748b]">Placed by: {bid.bidderName}</span>
                  </div>
                  <span className="text-[#13B8A6] bg-[#176B87] px-3 py-1 rounded-xl font-mono font-black">
                    KES {bid.amount.toLocaleString()}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <div className="p-8 text-center rounded-2xl bg-white border border-[#D7E7E4] text-[#64748b] font-mono text-xs">
              No active bid records matching query.
            </div>
          )}
        </div>
      )}

      {activeTab === 'alerts' && (
        <div className="space-y-4">
          <h3 className="text-base font-extrabold text-[#176B87] font-serif">Configured Price Alerts ({priceAlerts.length})</h3>
          {priceAlerts.length > 0 ? (
            <div className="bg-white border border-[#D7E7E4] rounded-2xl divide-y divide-[#D7E7E4] shadow-xs overflow-hidden">
              {priceAlerts.map((alert) => {
                const targetVehicle = vehicles.find(v => v.id === alert.vehicleId);
                return (
                  <div key={alert.id} className="p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-4 hover:bg-[#EEF7F5]/40 transition-colors">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-xl bg-[#13B8A6]/15 border border-[#13B8A6]/30 flex items-center justify-center text-[#13B8A6] shrink-0">
                        <BellRing className="w-5 h-5" />
                      </div>
                      <div>
                        <span className="text-sm font-extrabold text-[#176B87] block">
                          {alert.vehicleTitle}
                        </span>
                        <div className="flex flex-wrap items-center gap-2 mt-0.5 text-xs text-[#64748b]">
                          <span>Current: <strong className="text-[#176B87]">KSh {targetVehicle?.price.toLocaleString() || alert.currentPriceAtSet.toLocaleString()}</strong></span>
                          <span>•</span>
                          <span className="text-emerald-700 font-bold">Alert Target: KSh {alert.targetPrice.toLocaleString()}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 self-end sm:self-center">
                      <button
                        onClick={() => navigateTo('vehicle_detail', alert.vehicleId)}
                        className="px-3 py-1.5 rounded-xl bg-[#176B87] hover:bg-[#176B87] text-white font-extrabold text-xs flex items-center gap-1 transition-all cursor-pointer"
                      >
                        <span>View Vehicle</span>
                        <ExternalLink className="w-3.5 h-3.5 text-[#13B8A6]" />
                      </button>

                      <button
                        onClick={() => removePriceAlert(alert.vehicleId)}
                        className="p-1.5 rounded-xl text-rose-600 hover:bg-rose-50 transition-colors cursor-pointer"
                        title="Remove alert"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="p-8 text-center rounded-2xl bg-white border border-[#D7E7E4] text-[#64748b] font-mono text-xs">
              No active price alerts set. Browse vehicles and click "Set Price Alert" to get notified on price drops!
            </div>
          )}
        </div>
      )}

      {activeTab === 'escrow' && (
        <div className="space-y-4">
          <h3 className="text-base font-extrabold text-[#176B87] font-serif">Active Escrow Contracts ({escrowContracts.length})</h3>
          {escrowContracts.length > 0 ? (
            <div className="bg-white border border-[#D7E7E4] rounded-2xl divide-y divide-[#D7E7E4] shadow-xs">
              {escrowContracts.map(contract => (
                <div key={contract.id} className="p-4 flex items-center justify-between text-xs font-mono font-bold">
                  <div>
                    <span className="text-[#176B87] font-extrabold block">Contract ID: {contract.id}</span>
                    <span className="text-[#64748b]">Status: {contract.status}</span>
                  </div>
                  <span className="text-emerald-700 bg-emerald-50 border border-emerald-200 px-3 py-1 rounded-xl">
                    KES {contract.agreedPrice.toLocaleString()}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <div className="p-8 text-center rounded-2xl bg-white border border-[#D7E7E4] text-[#64748b] font-mono text-xs">
              No active escrow contracts found.
            </div>
          )}
        </div>
      )}

      {/* Add New Listing Modal */}
      <Modal
        isOpen={isAddModalOpen}
        onClose={() => setIsAddModalOpen(false)}
        title="List New Vehicle on KAYAD"
        subtitle="Add your vehicle details. Buyers can request an independent inspection before they commit"
      >
        <form onSubmit={handleCreateListing} className="space-y-4">
          <Input label="Vehicle Title" placeholder="e.g. 2023 Porsche 911 Carrera S" value={newTitle} onChange={e => setNewTitle(e.target.value)} required />
          <div className="grid grid-cols-2 gap-3">
            <Input label="Make" value={newMake} onChange={e => setNewMake(e.target.value)} />
            <Input label="Year" value={newYear} onChange={e => setNewYear(e.target.value)} />
          </div>
          <Input label="Asking Price ($)" type="number" value={newPrice} onChange={e => setNewPrice(e.target.value)} />
          <Input label="VIN Number" placeholder="WP0AF2..." value={newVin} onChange={e => setNewVin(e.target.value)} />
          <Button type="submit" variant="primary" className="w-full">Publish Verified Listing</Button>
        </form>
      </Modal>
    </div>
  );
};

import type { FC } from 'react';
import type React from 'react';
import { useState } from 'react';
import { Building2, Star, MapPin, Phone, Mail, ShieldCheck, CheckCircle2, Calendar } from 'lucide-react';
import { useMarketplace } from '../../context/MarketplaceContext';
import { VehicleCard } from '../gallery/VehicleCard';
import { Button } from '../ui/Button';
import { Modal } from '../ui/Modal';
import { Input } from '../ui/Input';
import { SearchBar } from '../ui/SearchBar';

export const DealerProfilePage: FC = () => {
  const { vehicles, openChat } = useMarketplace();
  const dealer = null;

  if (!dealer) {
    return (
      <div className="py-16 px-6 text-center max-w-3xl mx-auto">
        <h1 className="text-2xl font-bold text-[#176B87]">Dealer profile unavailable</h1>
        <p className="mt-2 text-sm text-[#64748b]">A real dealer profile must be loaded from the KAYAD backend before inventory is displayed.</p>
      </div>
    );
  }

  const dealerVehicles = vehicles.filter(v => v.dealerId === dealer.id || v.sellerId === dealer.id);

  const [searchQuery, setSearchQuery] = useState('');
  const [listingFilter, setListingFilter] = useState<'all' | 'fixed' | 'auction'>('all');
  const [isTestDriveOpen, setIsTestDriveOpen] = useState(false);
  const [testDriveDate, setTestDriveDate] = useState('');
  const [testDriveSuccess, setTestDriveSuccess] = useState(false);

  const filteredDealerVehicles = dealerVehicles.filter(v => {
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      const matchesTitle = v.title?.toLowerCase().includes(q);
      const matchesMake = v.make?.toLowerCase().includes(q);
      const matchesVin = v.vin?.toLowerCase().includes(q);
      if (!matchesTitle && !matchesMake && !matchesVin) return false;
    }
    if (listingFilter === 'fixed' && v.listingType !== 'fixed') return false;
    if (listingFilter === 'auction' && v.listingType !== 'auction') return false;
    return true;
  });

  const handleTestDriveSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setTestDriveSuccess(true);
  };

  return (
    <div className="py-10 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto space-y-10 bg-[#F6FAF9]">
      {/* Dealer Hero Banner */}
      <div className="relative rounded-3xl overflow-hidden border border-[#176B87] bg-[#176B87] text-white shadow-xl">
        <img src={dealer.bannerImage} alt={dealer.name} className="w-full h-64 object-cover opacity-30" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#176B87] via-[#176B87]/70 to-transparent p-6 sm:p-8 flex flex-col justify-end">
          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6">
            <div className="flex items-center gap-4">
              <img src={dealer.logo} alt={dealer.name} className="w-20 h-20 rounded-2xl object-cover border-2 border-[#13B8A6] shadow-xl" />
              <div>
                <span className="px-2.5 py-1 text-[10px] font-extrabold bg-[#13B8A6] text-[#176B87] rounded-md uppercase tracking-wider">
                  {dealer.badge}
                </span>
                <h1 className="text-2xl sm:text-4xl font-extrabold text-white font-serif mt-1">{dealer.name}</h1>
                <p className="text-xs text-[#BDE5DE] flex items-center gap-1 mt-1 font-medium">
                  <MapPin className="w-3.5 h-3.5 text-[#13B8A6]" /> {dealer.address}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <Button variant="secondary" onClick={() => openChat()}>
                Chat with Concierge
              </Button>
              <Button variant="accent" onClick={() => setIsTestDriveOpen(true)}>
                Schedule Private Viewing
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Inventory Grid */}
      <div className="space-y-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 pb-2 border-b border-[#D7E7E4]">
          <div>
            <h2 className="text-2xl font-extrabold text-[#176B87] font-serif">
              Certified Dealership Inventory ({dealerVehicles.length})
            </h2>
            <p className="text-xs text-[#64748b] font-medium mt-0.5">
              Verified listings, documented vehicle details, and concierge pre-purchase inspection support.
            </p>
          </div>
        </div>

        {/* Standardized KAYAD Search Bar */}
        <SearchBar
          value={searchQuery}
          onChange={setSearchQuery}
          placeholder="Search inventory by title, make, or VIN..."
          resultCount={filteredDealerVehicles.length}
          badgeLabel={`DEALERSHIP STOCK · ${dealer.name}`}
          filterOptions={[
            { id: 'all', label: 'All Stock' },
            { id: 'fixed', label: 'Direct Buy' },
            { id: 'auction', label: 'Auctions' },
          ]}
          activeFilter={listingFilter}
          onFilterChange={f => setListingFilter(f as any)}
        />

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredDealerVehicles.map(v => (
            <VehicleCard key={v.id} vehicle={v} />
          ))}
        </div>
      </div>

      {/* Schedule Test Drive Modal */}
      <Modal
        isOpen={isTestDriveOpen}
        onClose={() => {
          setIsTestDriveOpen(false);
          setTestDriveSuccess(false);
        }}
        title={`Schedule Appointment with ${dealer.name}`}
        subtitle="Private viewing and VIP showroom tour with KAYAD escrow concierge"
      >
        {testDriveSuccess ? (
          <div className="p-6 text-center space-y-3">
            <CheckCircle2 className="w-12 h-12 text-[#13B8A6] mx-auto" />
            <h4 className="text-base font-bold text-[#176B87] font-serif">Appointment Requested</h4>
            <p className="text-xs text-[#176b87] font-medium">
              The concierge team at {dealer.name} will contact you shortly to confirm your private viewing.
            </p>
          </div>
        ) : (
          <form onSubmit={handleTestDriveSubmit} className="space-y-4">
            <Input label="Preferred Date & Time" type="datetime-local" value={testDriveDate} onChange={e => setTestDriveDate(e.target.value)} required />
            <Button type="submit" variant="primary" className="w-full">
              Confirm Viewing Request
            </Button>
          </form>
        )}
      </Modal>
    </div>
  );
};

