import { useState, useEffect } from 'react';
import { Gavel, Clock, ExternalLink, X } from 'lucide-react';
import { formatKES } from '../../../../utils/helpers';

interface AuctionAnnouncementProps {
  car: any;
  onClose?: () => void;
}

export default function AuctionAnnouncement({ car, onClose }: AuctionAnnouncementProps) {
  const [timeLeft, setTimeLeft] = useState('');

  useEffect(() => {
    if (!car?.auctionEnd) return;

    const updateTimer = () => {
      const end = new Date(car.auctionEnd).getTime();
      const now = Date.now();
      const diff = end - now;

      if (diff <= 0) {
        setTimeLeft('Auction ended');
        return;
      }

      const hours = Math.floor(diff / (1000 * 60 * 60));
      const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((diff % (1000 * 60)) / 1000);

      if (hours > 24) {
        const days = Math.floor(hours / 24);
        setTimeLeft(`${days}d ${hours % 24}h`);
      } else if (hours > 0) {
        setTimeLeft(`${hours}h ${minutes}m`);
      } else {
        setTimeLeft(`${minutes}m ${seconds}s`);
      }
    };

    updateTimer();
    const interval = setInterval(updateTimer, 1000);
    return () => clearInterval(interval);
  }, [car?.auctionEnd]);

  if (!car?.auctionStatus) return null;

  const isLive = car.auctionStatus === 'live';
  const isEnded = car.auctionStatus === 'ended';
  const isUpcoming = !isLive && !isEnded;

  const getStatusInfo = () => {
    if (isLive) {
      return {
        bg: 'bg-red-500/10 border-red-500/20',
        text: 'text-red-600',
        icon: Gavel,
        title: 'Live Auction',
        sub: `${car.bidsCount || 0} bid${(car.bidsCount || 0) !== 1 ? 's' : ''} · Ends in ${timeLeft}`,
      };
    }
    if (isEnded) {
      return {
        bg: 'bg-[#5AAFA4]/10 border-[#5AAFA4]/20',
        text: 'text-[#64748B]',
        icon: Clock,
        title: 'Auction Ended',
        sub: car.winner ? `Won by ${car.winner.user?.name || 'Winner'}` : 'No winner',
      };
    }
    return {
      bg: 'bg-[#13B8A6]/10 border-[#5AAFA4]/20',
      text: 'text-[#176B87]',
      icon: Clock,
      title: 'Upcoming Auction',
      sub: 'Auction starts soon',
    };
  };

  const info = getStatusInfo();
  const Icon = info.icon;

  return (
    <div className={`rounded-xl p-4 border ${info.bg}`}>
      <div className="flex items-start gap-3">
        <div className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center ${info.bg}`}>
          <Icon size={18} className={info.text} />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className={`font-sans text-sm font-bold ${info.text}`}>{info.title}</span>
            {isLive && (
              <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
            )}
          </div>
          <p className="font-sans text-xs text-warm-500 mt-0.5">{info.sub}</p>

          {isLive && car.currentBid && (
            <p className="font-sans text-sm font-bold text-[#0A3340] mt-2">
              Current: {formatKES(car.currentBid)}
            </p>
          )}

          {isEnded && car.winner && (
            <p className="font-sans text-sm font-bold text-emerald-600 mt-2">
              Final Price: {formatKES(car.winner.amount || car.currentBid)}
            </p>
          )}
        </div>

        {isLive && (
          <a
            href={`/auction/${car._id}`}
            className="flex-shrink-0 flex items-center gap-1 px-3 py-1.5 bg-red-500 text-white text-xs font-bold rounded-full hover:bg-red-600 transition-colors"
          >
            <ExternalLink size={12} />
            Enter
          </a>
        )}

        {onClose && (
          <button
            onClick={onClose}
            className="flex-shrink-0 p-1 text-warm-400 hover:text-warm-600 transition-colors"
          >
            <X size={16} />
          </button>
        )}
      </div>
    </div>
  );
}

import { useState, useCallback, useRef, type TouchEvent, type ComponentType } from 'react';
import { ChevronLeft, ChevronRight, Star, BarChart3 } from 'lucide-react';
import { useCompare } from '../../../../context/CompareContext';

export function firstImage(car: any, idx = 0): string | null {
  const imgs = car?.images || [];
  const img = imgs[idx];
  if (!img) return null;
  return typeof img === 'string' ? img : img?.url || null;
}

interface GalleryImageProps {
  car: any;
  idx: number;
  onPrev: () => void;
  onNext: () => void;
  total: number;
  onOpenGallery?: () => void;
}

export function GalleryImage({ car, idx, onPrev, onNext, total, onOpenGallery }: GalleryImageProps) {
  const [err, setErr] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const touchX = useRef<number | null>(null);

  const src = (!err && firstImage(car, idx)) ||
    'https://images.unsplash.com/photo-1503376780353-7e8f0e4b39f4?q=80&w=1600&fit=crop';

  const handleTouchStart = useCallback((e: TouchEvent) => {
    touchX.current = e.touches[0].clientX;
  }, []);

  const handleTouchEnd = useCallback((e: TouchEvent) => {
    if (touchX.current === null) return;
    const dx = e.changedTouches[0].clientX - touchX.current;
    if (dx > 50) onPrev();
    else if (dx < -50) onNext();
    touchX.current = null;
  }, [onPrev, onNext]);

  return (
    <div
      className="relative w-full aspect-video bg-[#12576D] rounded-2xl overflow-hidden cursor-pointer"
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onClick={onOpenGallery}
    >
      {!loaded && (
        <div className="absolute inset-0 bg-[#12576D] animate-pulse" />
      )}
      <img
        src={src}
        onError={() => setErr(true)}
        onLoad={() => setLoaded(true)}
        alt={car?.title || 'Vehicle'}
        width={800}
        height={450}
        loading="lazy"
        decoding="async"
        className="w-full h-full object-cover transition-opacity duration-500"
        style={{ opacity: loaded ? 1 : 0.3 }}
      />

      {/* Gradient overlay */}
      <div className="absolute inset-0 bg-gradient-to-t from-[#0A3340]/30 via-transparent to-[#0A3340]/20 pointer-events-none" />

      {/* Navigation arrows */}
      {total > 1 && (
        <>
          <button
            onClick={(e) => { e.stopPropagation(); onPrev(); }}
            className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm text-white rounded-full flex items-center justify-center transition-all z-10"
          >
            <ChevronLeft size={18} />
          </button>
          <button
            onClick={(e) => { e.stopPropagation(); onNext(); }}
            className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm text-white rounded-full flex items-center justify-center transition-all z-10"
          >
            <ChevronRight size={18} />
          </button>
          <div className="absolute bottom-4 right-4 px-3 py-1.5 bg-[#0A3340]/60 text-white text-xs font-semibold rounded-full backdrop-blur-sm z-10">
            {idx + 1} / {total}
          </div>
        </>
      )}

      {/* Featured badge */}
      {car?.isPromoted && (
        <div className="absolute top-4 left-4 flex items-center gap-1.5 px-3 py-1.5 bg-[#13B8A6]/90 text-[#0A3340] text-xs font-bold rounded-full z-10">
          <Star size={12} />
          FEATURED
        </div>
      )}

      {/* Demo badge */}

      {/* Live auction badge */}
      {car?.auctionStatus === 'live' && (
        <div className="absolute top-4 left-4 flex items-center gap-2 px-3 py-1.5 bg-red-500/90 text-white text-xs font-bold rounded-full z-10">
          <span className="w-2 h-2 bg-white rounded-full animate-pulse" />
          LIVE AUCTION
        </div>
      )}
    </div>
  );
}

interface GalleryThumbnailsProps {
  car: any;
  selectedIdx: number;
  onSelect: (idx: number) => void;
}

export function GalleryThumbnails({ car, selectedIdx, onSelect }: GalleryThumbnailsProps) {
