import { useState } from 'react';
import { Gavel, Clock, Users, AlertCircle, CheckCircle, Loader } from 'lucide-react';
import { formatKES } from '../../../../utils/helpers';

interface InlineBiddingProps {
  car: any;
  onBidPlaced?: (amount: number) => void;
}

export default function InlineBidding({ car, onBidPlaced }: InlineBiddingProps) {
  const [bidAmount, setBidAmount] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const currentBid = car?.currentBid || 0;
  const startingBid = car?.startingBid || currentBid || car?.price || 0;
  const minBid = currentBid > 0 ? currentBid + 5000 : startingBid;
  const bidsCount = car?.bidsCount || 0;

  // Calculate time remaining
  const auctionEnd = car?.auctionEnd ? new Date(car.auctionEnd).getTime() : 0;
  const now = Date.now();
  const timeLeft = auctionEnd > now ? auctionEnd - now : 0;

  const hours = Math.floor(timeLeft / (1000 * 60 * 60));
  const minutes = Math.floor((timeLeft % (1000 * 60 * 60)) / (1000 * 60));
  const isLive = car?.auctionStatus === 'live' && timeLeft > 0;

  const quickBidOptions = [
    minBid,
    minBid + 10000,
    minBid + 25000,
    minBid + 50000,
  ].filter((val, idx, arr) => arr.indexOf(val) === idx && val > 0);

  const handleQuickBid = (amount: number) => {
    setBidAmount(amount.toString());
  };

  const handleSubmit = async () => {
    const amount = parseInt(bidAmount);
    if (!amount || amount < minBid) {
      setError(`Minimum bid is ${formatKES(minBid)}`);
      return;
    }

    setSubmitting(true);
    setError('');

    try {
      // API call would go here
      // await bidsAPI.place(car._id, { amount });

      // Simulate success
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess(true);
      onBidPlaced?.(amount);
    } catch (err) {
      setError('Failed to place bid. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  if (!isLive) {
    return (
      <div className="bg-[#EEF7F5] rounded-xl p-5 border border-[#D7E7E4]">
        <div className="flex items-center gap-3 text-warm-500">
          <Gavel size={20} />
          <div>
            <p className="font-sans text-sm font-semibold">Auction Not Active</p>
            <p className="font-sans text-xs opacity-70">
              {car?.auctionStatus === 'ended'
                ? 'This auction has ended'
                : 'Auction has not started yet'
              }
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-xl p-5 border border-[#D7E7E4] shadow-sm">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
          <span className="text-xs font-bold text-red-600 uppercase tracking-wider">Live Auction</span>
        </div>
        <div className="flex items-center gap-1 text-xs text-warm-500">
          <Clock size={12} />
          <span>{hours}h {minutes}m remaining</span>
        </div>
      </div>

      {/* Current bid */}
      <div className="text-center mb-4">
        <p className="text-[10px] text-warm-400 uppercase tracking-wider font-bold mb-1">
          {bidsCount > 0 ? 'Current Bid' : 'Starting Bid'}
        </p>
        <p className="font-serif text-3xl text-[#0A3340] font-bold">
          {formatKES(currentBid || startingBid)}
        </p>
        <p className="text-xs text-warm-400 mt-1">
          {bidsCount} bid{bidsCount !== 1 ? 's' : ''} placed
        </p>
      </div>

      {/* Quick bid buttons */}
      <div className="flex gap-2 mb-4">
        {quickBidOptions.slice(0, 3).map((amount) => (
          <button
            key={amount}
            onClick={() => handleQuickBid(amount)}
            className={`flex-1 py-2 px-2 rounded-lg font-sans text-xs font-semibold transition-all ${
              parseInt(bidAmount) === amount
                ? 'bg-[#13B8A6] text-white'
                : 'bg-[#EEF7F5] text-[#0A3340] hover:bg-[#DDF4F0]'
            }`}
          >
            {formatKES(amount)}
          </button>
        ))}
      </div>

      {/* Custom bid input */}
      <div className="flex gap-2 mb-3">
        <div className="flex-1 relative">
          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-warm-400 text-sm">KES</span>
          <input
            type="number"
            value={bidAmount}
            onChange={(e) => {
              setBidAmount(e.target.value);
              setError('');
            }}
            placeholder={minBid.toLocaleString()}
            min={minBid}
            className="w-full pl-12 pr-3 py-3 bg-[#F6FAF9] border border-[#D7E7E4] rounded-xl font-sans text-sm text-[#0A3340] outline-none focus:border-[#5AAFA4] focus:ring-1 focus:ring-[#5AAFA4]/30"
          />
        </div>
      </div>

      {/* Minimum bid hint */}
      <p className="text-xs text-warm-400 mb-3">
        Minimum bid: {formatKES(minBid)}
      </p>

      {/* Error message */}
      {error && (
        <div className="flex items-center gap-2 text-red-600 text-xs mb-3">
          <AlertCircle size={14} />
          <span>{error}</span>
        </div>
      )}

      {/* Success message */}
      {success && (
        <div className="flex items-center gap-2 text-emerald-600 text-xs mb-3">
          <CheckCircle size={14} />
          <span>Bid placed successfully!</span>
        </div>
      )}

      {/* Submit button */}
      <button
        onClick={handleSubmit}
        disabled={submitting || !bidAmount}
        className={`w-full py-3 px-4 rounded-xl font-sans text-sm font-bold flex items-center justify-center gap-2 transition-all ${
          submitting || !bidAmount
            ? 'bg-[#DDF4F0] text-warm-400 cursor-not-allowed'
            : 'bg-[#13B8A6] text-white hover:bg-[#176B87]'
        }`}
      >
        {submitting ? (
          <>
            <Loader size={16} className="animate-spin" />
            Placing Bid...
          </>
        ) : (
          <>
            <Gavel size={16} />
            Place Bid
          </>
        )}
      </button>

      {/* Terms */}
      <p className="text-[10px] text-warm-300 text-center mt-3">
        By placing a bid, you agree to our auction terms. A 5% commitment fee may apply.
      </p>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef, type TouchEvent } from 'react';
import { X, ChevronLeft, ChevronRight, Star } from 'lucide-react';
import LazyImage from '../common/LazyImage';

interface CarImage {
  url?: string;
  thumb?: string;
}

interface Car {
  images?: (string | CarImage)[];
  title?: string;
  isPromoted?: boolean;
}

interface GalleryModalProps {
  car: Car | null;
  initialIdx?: number;
  onClose: () => void;
}

function firstImage(car: Car | null, idx = 0): string | null {
  const imgs = car?.images || [];
  const img = imgs[idx];
  if (!img) return null;
  return typeof img === 'string' ? img : img?.url || null;
}

export default function GalleryModal({ car, initialIdx = 0, onClose }: GalleryModalProps) {
  const [idx, setIdx] = useState(initialIdx);
  const touchX = useRef<number | null>(null);

  const images = car?.images || [];
  const total = images.length;

  const prev = useCallback(() => setIdx(i => (i > 0 ? i - 1 : total - 1)), [total]);
  const next = useCallback(() => setIdx(i => (i < total - 1 ? i + 1 : 0)), [total]);

  useEffect(() => {
    const h = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowLeft') prev();
      if (e.key === 'ArrowRight') next();
    };
    window.addEventListener('keydown', h);
    return () => window.removeEventListener('keydown', h);
  }, [onClose, prev, next]);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = ''; };
  }, []);

  const handleTouchStart = useCallback((e: TouchEvent) => { touchX.current = e.touches[0].clientX; }, []);
  const handleTouchEnd = useCallback((e: TouchEvent) => {
    if (touchX.current === null) return;
    const dx = e.changedTouches[0].clientX - touchX.current;
    if (dx > 50) prev();
    else if (dx < -50) next();
    touchX.current = null;
  }, [prev, next]);

  if (!car || total === 0) return null;

  const src = firstImage(car, idx);

  return (
    <div
      onClick={onClose}
      onKeyDown={(e) => e.key === 'Escape' && onClose()}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      role="button"
      tabIndex={0}
      aria-label="Close gallery"
      style={{
        position: 'fixed', inset: 0, zIndex: 1000,
        background: 'rgba(10, 51, 64, 0.92)',
        display: 'flex', flexDirection: 'column',
        alignItems: 'center', justifyContent: 'center',
        cursor: 'zoom-out',
        animation: 'fadeIn 0.2s ease',
      }}
    >
      <button onClick={onClose} style={{
        position: 'absolute', top: 16, right: 16, zIndex: 10,
        background: 'rgba(10, 51, 64, 0.5)', border: '1px solid rgba(255,255,255,0.15)',
        borderRadius: '50%', width: 40, height: 40,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        color: '#fff', cursor: 'pointer', transition: 'all 0.2s',
      }}
        onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.15)'; }}
        onMouseLeave={e => { e.currentTarget.style.background = 'rgba(10, 51, 64, 0.5)'; }}
      >
        <X size={18} />
      </button>

      {total > 1 && (
        <>
          <button onClick={e => { e.stopPropagation(); prev(); }} style={{
            position: 'absolute', left: 16, top: '50%', transform: 'translateY(-50%)', zIndex: 10,
            background: 'rgba(10, 51, 64, 0.5)', border: '1px solid rgba(255,255,255,0.15)',
            borderRadius: '50%', width: 48, height: 48,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: '#fff', cursor: 'pointer', transition: 'all 0.2s',
          }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.15)'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'rgba(10, 51, 64, 0.5)'; }}
          >
            <ChevronLeft size={22} />
          </button>
          <button onClick={e => { e.stopPropagation(); next(); }} style={{
            position: 'absolute', right: 16, top: '50%', transform: 'translateY(-50%)', zIndex: 10,
            background: 'rgba(10, 51, 64, 0.5)', border: '1px solid rgba(255,255,255,0.15)',
            borderRadius: '50%', width: 48, height: 48,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            color: '#fff', cursor: 'pointer', transition: 'all 0.2s',
          }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.15)'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'rgba(10, 51, 64, 0.5)'; }}
          >
            <ChevronRight size={22} />
          </button>
        </>
      )}

      <div onClick={e => e.stopPropagation()} className="gallery-modal-image" style={{
        flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
        padding: '60px 80px', width: '100%', maxHeight: 'calc(100vh - 120px)',
        cursor: 'default',
      }}>
        <div style={{
          position: 'relative', maxWidth: '100%', maxHeight: '100%',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <LazyImage
            src={src}
            alt={car?.title || 'Vehicle'}
            style={{
              maxWidth: '100%', maxHeight: 'calc(100vh - 120px)',
              width: 'auto', height: 'auto',
              borderRadius: 4,
              objectFit: 'contain',
            }}
          />
          {car?.isPromoted && (
            <div style={{
              position: 'absolute', top: 12, right: 12,
              display: 'inline-flex', alignItems: 'center', gap: 4,
              background: 'rgba(19, 184, 166, 0.92)', backdropFilter: 'blur(8px)',
              borderRadius: 8, padding: '5px 10px',
            }}>
              <Star size={10} style={{ color: '#0a3340' }} />
              <span style={{ fontSize: 10, color: '#0a3340', fontWeight: 800, letterSpacing: '0.08em' }}>FEATURED</span>
            </div>
          )}
        </div>
      </div>

      <div onClick={e => e.stopPropagation()} style={{
        height: 80, display: 'flex', alignItems: 'center', justifyContent: 'center',
        gap: 8, padding: '0 16px', width: '100%',
        background: 'rgba(10, 51, 64, 0.4)',
      }}>
        <span style={{ fontSize: 11, color: 'rgba(255,255,255,0.3)', fontWeight: 600, letterSpacing: '0.05em' }}>
          {idx + 1} / {total}
        </span>
        <div style={{ display: 'flex', gap: 6, alignItems: 'center', overflow: 'auto', padding: '0 12px', flex: 1, justifyContent: 'center' }}>
          {images.map((img, i) => {
            const thumbSrc = typeof img === 'string' ? img : (img?.thumb || img?.url);
            return (
              <button key={i} onClick={() => setIdx(i)} style={{
                width: 48, height: 36, flexShrink: 0,
                border: i === idx ? '2px solid var(--brand)' : '2px solid rgba(255,255,255,0.1)',
                borderRadius: 4, overflow: 'hidden', cursor: 'pointer',
                padding: 0, background: '#0a3340', transition: 'border 0.2s',
                opacity: i === idx ? 1 : 0.5,
              }}>
                <img src={thumbSrc} alt="" loading="lazy" decoding="async" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

