import { useState, useEffect, type FC } from 'react';
import { ledgerAPI, escrowAPI, formatKES } from '../../../api/api.exports';

interface SecureEscrowHubProps {
  className?: string;
  compact?: boolean;
}

export const SecureEscrowHub: FC<SecureEscrowHubProps> = ({
  className = '',
  compact = false,
}) => {
  const [loading, setLoading] = useState(true);
  const [summary, setSummary] = useState<any>(null);
  const [transactions, setTransactions] = useState<any[]>([]);
  const [escrow, setEscrow] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      const [ledgerSummary, myEscrow] = await Promise.all([
        ledgerAPI.getSummary(),
        escrowAPI.mine().catch(() => null),
      ]);
      setSummary(ledgerSummary);
      setEscrow(myEscrow);

      const txns = await ledgerAPI.getMyTransactions({ page: 1, limit: compact ? 5 : 10 });
      setTransactions(txns.data || txns || []);
    } catch (err: any) {
      setError(err.message || 'Failed to load escrow data');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className={`bg-white dark:bg-[#12576D] rounded-xl p-6 ${className}`}>
        <div className="animate-pulse space-y-4">
          <div className="h-8 bg-[#DDF4F0] dark:bg-[#12576D] rounded w-1/3" />
          <div className="grid grid-cols-3 gap-4">
            <div className="h-24 bg-[#DDF4F0] dark:bg-[#12576D] rounded" />
            <div className="h-24 bg-[#DDF4F0] dark:bg-[#12576D] rounded" />
            <div className="h-24 bg-[#DDF4F0] dark:bg-[#12576D] rounded" />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`bg-white dark:bg-[#12576D] rounded-xl shadow-sm ${className}`}>
      {/* Header */}
      <div className="p-6 border-b border-[#D7E7E4] dark:border-[#12576D]">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center">
              <svg className="w-5 h-5 text-emerald-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
              </svg>
            </div>
            <div>
              <h2 className="text-lg font-bold text-[#0A3340] dark:text-[#64748B]">
                Secure Escrow Hub
              </h2>
              <p className="text-sm text-[#64748B] dark:text-[#5AAFA4]">
                Immutable transaction ledger
              </p>
            </div>
          </div>
          {summary && (
            <div className="text-right">
              <p className="text-sm text-[#64748B] dark:text-[#5AAFA4]">Net Balance</p>
              <p className="text-xl font-bold text-emerald-600">
                {formatKES(summary.netBalance)}
              </p>
            </div>
          )}
        </div>
      </div>

      {error && (
        <div className="p-4 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400">
          {error}
        </div>
      )}

      {/* Summary Cards */}
      {!compact && (
        <div className="p-6 grid grid-cols-3 gap-4">
          <div className="p-4 rounded-xl bg-emerald-50 dark:bg-emerald-900/20">
            <p className="text-sm text-[#64748B] dark:text-[#5AAFA4]">Total In</p>
            <p className="text-lg font-bold text-emerald-600">
              {formatKES(summary?.totalIn || 0)}
            </p>
          </div>
          <div className="p-4 rounded-xl bg-[#F3FAF9] dark:bg-[#0A3340]/20">
            <p className="text-sm text-[#64748B] dark:text-[#5AAFA4]">Total Out</p>
            <p className="text-lg font-bold text-[#176B87]">
              {formatKES(summary?.totalOut || 0)}
            </p>
          </div>
          <div className="p-4 rounded-xl bg-brand-50 dark:bg-brand-900/20">
            <p className="text-sm text-[#64748B] dark:text-[#5AAFA4]">Transactions</p>
            <p className="text-lg font-bold text-brand-600">
              {(Object.values(summary?.byType || {}) as any[]).reduce((sum: number, t: any) => sum + t.count, 0)}
            </p>
          </div>
        </div>
      )}

      {/* Escrow Balance */}
      {escrow && !compact && (
        <div className="px-6 pb-4">
          <div className="p-4 rounded-xl bg-gradient-to-r from-brand-500 to-brand-600 text-white">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm opacity-80">Available Escrow Balance</p>
                <p className="text-2xl font-bold">{formatKES(escrow.balance || 0)}</p>
              </div>
              <div className="text-right">
                <p className="text-sm opacity-80">Status</p>
                <p className="font-semibold capitalize">{escrow.status || 'active'}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Transaction List */}
      <div className="border-t border-[#D7E7E4] dark:border-[#12576D]">
        <div className="px-6 py-4 flex items-center justify-between">
          <h3 className="font-semibold text-[#12576D] dark:text-[#64748B]">
            Recent Transactions
          </h3>
          <span className="text-sm text-[#64748B] dark:text-[#5AAFA4]">
            Chain verified ✓
          </span>
        </div>

        {transactions.length === 0 ? (
          <div className="px-6 py-8 text-center">
            <p className="text-[#64748B] dark:text-[#5AAFA4]">No transactions yet</p>
          </div>
        ) : (
          <div className="divide-y divide-[#DDF4F0] dark:divide-[#12576D]">
            {transactions.slice(0, compact ? 5 : 10).map((txn) => (
              <div
                key={txn.ledgerId || txn._id}
                className="px-6 py-3 flex items-center justify-between hover:bg-[#F6FAF9] dark:hover:bg-[#12576D]/50"
              >
                <div className="flex items-center gap-3">
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                    txn.direction === 'in' || txn.type === 'deposit'
                      ? 'bg-emerald-100 text-emerald-600'
                      : 'bg-[#DDF4F0] text-[#176B87]'
                  }`}>
                    {txn.direction === 'in' || txn.type === 'deposit' ? (
                      <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
                      </svg>
                    ) : (
                      <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 14l-7 7m0 0l-7-7m7 7V3" />
                      </svg>
                    )}
                  </div>
                  <div>
                    <p className="font-medium text-[#12576D] dark:text-[#64748B] capitalize">
                      {txn.type?.replace(/_/g, ' ') || 'Transaction'}
                    </p>
                    <p className="text-xs text-[#64748B] dark:text-[#5AAFA4]">
                      {txn.ledgerId} • {new Date(txn.createdAt).toLocaleDateString()}
                    </p>
                  </div>
                </div>
                <div className="text-right">
                  <p className={`font-semibold ${
                    txn.direction === 'in' || txn.type === 'deposit'
                      ? 'text-emerald-600'
                      : 'text-[#12576D] dark:text-[#64748B]'
                  }`}>
                    {txn.direction === 'in' ? '+' : '-'}{formatKES(txn.amount)}
                  </p>
                  <p className="text-xs text-[#64748B] dark:text-[#5AAFA4] capitalize">
                    {txn.status}
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}

        {!compact && transactions.length > 0 && (
          <div className="p-4 border-t border-[#D7E7E4] dark:border-[#12576D]">
            <button className="w-full py-2 text-brand-500 hover:text-brand-600 font-medium">
              View All Transactions
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default SecureEscrowHub;

import { useState } from 'react';
import { Filter, RotateCcw, Check, Search, ShieldCheck, Tag, Car, Zap, ChevronDown, MapPin, Sparkles } from 'lucide-react';
import { useMarketplace, FilterState } from '../../context/MarketplaceContext';
import { TransmissionType, FuelType, BodyStyle } from '../../types';
import type { FC } from 'react';

export const FilterSidebar: FC = () => {
  const { vehicles, filters, setFilters, resetFilters } = useMarketplace();

  // Collapsible accordion states
  const [openSection, setOpenSection] = useState<{ [key: string]: boolean }>({
    brand: true,
    body: true,
    transmission: true,
    fuel: false,
    city: false,
    price: true,
  });

  const toggleSection = (key: string) => {
    setOpenSection(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const availableMakes = [
    'Toyota',
    'Mercedes-Benz',
    'Honda',
    'Mazda',
    'Subaru',
    'Land Rover',
    'Porsche',
    'BMW',
    'Ferrari',
    'Lexus',
    'Audi',
    'Ford'
  ];

  const bodyStyles: BodyStyle[] = ['SUV', 'Sedan', 'Coupe', 'Truck', 'Convertible', 'Hatchback'];
  const transmissions: TransmissionType[] = ['Automatic', 'Manual', 'Dual-Clutch', 'CVT'];
  const cities = ['Nairobi', 'Mombasa', 'Nakuru', 'Eldoret', 'Kisumu'];

  const fuelTypes: { id: FuelType; label: string }[] = [
    { id: 'Gasoline', label: 'Petrol' },
    { id: 'Diesel', label: 'Diesel' },
    { id: 'Hybrid', label: 'Hybrid' },
    { id: 'Electric', label: 'EV Electric' },
  ];

  // Category counts
  const totalCount = vehicles.length;

  const handleMakeToggle = (m: string) => {
    setFilters(prev => {
      const exists = prev.makes.includes(m);
      return {
        ...prev,
        makes: exists ? prev.makes.filter(item => item !== m) : [...prev.makes, m]
      };
    });
  };

  const handleBodyStyleToggle = (style: BodyStyle) => {
    setFilters(prev => {
      const exists = prev.bodyStyles.includes(style);
      return {
        ...prev,
        bodyStyles: exists ? prev.bodyStyles.filter(item => item !== style) : [...prev.bodyStyles, style]
      };
    });
  };

  const handleTransmissionToggle = (trans: TransmissionType) => {
    setFilters(prev => {
      const current = prev.transmission || [];
      const exists = current.includes(trans);
      return {
        ...prev,
        transmission: exists ? current.filter(t => t !== trans) : [...current, trans]
      };
    });
  };

  const handleFuelToggle = (fuel: FuelType) => {
    setFilters(prev => {
      const exists = prev.fuelType?.includes(fuel);
      const current = prev.fuelType || [];
      return {
        ...prev,
        fuelType: exists ? current.filter(f => f !== fuel) : [...current, fuel]
      };
    });
  };

  return (
    <aside className="w-full lg:w-72 bg-white border border-[#D7E7E4] rounded-2xl p-4 sm:p-5 space-y-5 shrink-0 h-fit shadow-xs text-[#176B87]">
      {/* Sidebar Header */}
      <div className="flex items-center justify-between pb-3 border-b border-[#DDF4F0]">
        <div className="flex items-center gap-2 font-bold text-[#176B87] font-serif text-sm uppercase tracking-wide">
          <Filter className="w-4 h-4 text-[#13B8A6]" />
          <span>MARKET FILTERS</span>
        </div>
        <button
          onClick={resetFilters}
          className="text-xs text-[#13B8A6] hover:underline font-bold flex items-center gap-1 transition-colors cursor-pointer"
        >
          <RotateCcw className="w-3 h-3" />
          <span>Reset</span>
        </button>
      </div>

      {/* FULL MARKET CATALOG SUMMARY BOX */}
      <div className="space-y-1.5 bg-[#176B87]/5 p-3.5 rounded-2xl border border-[#176B87]/10">
        <div className="flex items-center justify-between text-xs font-bold text-[#176B87]">
          <span className="flex items-center gap-1.5 font-serif text-sm">
            <Sparkles className="w-3.5 h-3.5 text-[#13B8A6]" />
            Full Market Catalog
          </span>
          <span className="text-[11px] font-mono font-bold bg-[#176B87] text-white px-2 py-0.5 rounded-lg">
            {totalCount} Cars
          </span>
        </div>
        <p className="text-[11px] text-[#64748B] font-medium leading-relaxed">
          Filter by Make, Model, Transmission, Fuel, Body & Budget.
        </p>
      </div>

      {/* FILTERS SECTION ACCORDIONS */}
      <div className="space-y-3 pt-1">
        <span className="text-[11px] font-mono font-bold uppercase tracking-wider text-[#64748b] block">
          SPECIFICATIONS
        </span>

        {/* Brand Accordion */}
        <div className="border border-[#D7E7E4] rounded-xl overflow-hidden bg-[#EEF7F5]/40 shadow-2xs">
          <button
            onClick={() => toggleSection('brand')}
            className="w-full p-3 flex items-center justify-between text-xs sm:text-sm font-bold text-[#176B87] bg-[#EEF7F5]/70 hover:bg-[#EEF7F5] transition-colors cursor-pointer"
          >
            <span className="font-serif">Brand / Manufacturer</span>
            <ChevronDown className={`w-4 h-4 text-[#64748B] transition-transform ${openSection.brand ? 'rotate-180' : ''}`} />
          </button>
          {openSection.brand && (
            <div className="p-2 space-y-1 max-h-48 overflow-y-auto no-scrollbar border-t border-[#D7E7E4]/60 bg-white">
              {availableMakes.map(make => {
                const isChecked = filters.makes.includes(make);
                return (
                  <button
                    key={make}
                    onClick={() => handleMakeToggle(make)}
                    className={`w-full flex items-center justify-between p-2 rounded-lg text-xs sm:text-sm font-semibold transition-all text-left cursor-pointer ${
                      isChecked ? 'bg-[#176B87] text-white shadow-2xs' : 'text-[#176B87] hover:bg-[#EEF7F5]'
                    }`}
                  >
                    <span>{make}</span>
                    {isChecked && <Check className="w-3.5 h-3.5 text-[#13B8A6]" />}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Transmission Accordion */}
        <div className="border border-[#D7E7E4] rounded-xl overflow-hidden bg-[#EEF7F5]/40 shadow-2xs">
          <button
            onClick={() => toggleSection('transmission')}
            className="w-full p-3 flex items-center justify-between text-xs sm:text-sm font-bold text-[#176B87] bg-[#EEF7F5]/70 hover:bg-[#EEF7F5] transition-colors cursor-pointer"
          >
            <span className="flex items-center gap-1.5 font-serif">
              <span>Transmission</span>
              {filters.transmission && filters.transmission.length > 0 && (
                <span className="px-1.5 py-0.5 bg-[#13B8A6] text-[#176B87] rounded-full text-[10px] font-mono font-bold">
                  {filters.transmission.length}
                </span>
              )}
            </span>
            <ChevronDown className={`w-4 h-4 text-[#64748B] transition-transform ${openSection.transmission ? 'rotate-180' : ''}`} />
          </button>
          {openSection.transmission && (
            <div className="p-2 space-y-1 border-t border-[#D7E7E4]/60 bg-white">
              {transmissions.map(trans => {
                const isSelected = filters.transmission?.includes(trans);
                return (
                  <button
                    key={trans}
                    onClick={() => handleTransmissionToggle(trans)}
                    className={`w-full flex items-center justify-between p-2 rounded-lg text-xs sm:text-sm font-semibold transition-all cursor-pointer ${
                      isSelected ? 'bg-[#176B87] text-white shadow-2xs' : 'text-[#176B87] hover:bg-[#EEF7F5]'
                    }`}
                  >
                    <span>{trans}</span>
                    {isSelected && <Check className="w-3.5 h-3.5 text-[#13B8A6]" />}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Body Type Accordion */}
        <div className="border border-[#D7E7E4] rounded-xl overflow-hidden bg-[#EEF7F5]/40 shadow-2xs">
          <button
            onClick={() => toggleSection('body')}
            className="w-full p-3 flex items-center justify-between text-xs sm:text-sm font-bold text-[#176B87] bg-[#EEF7F5]/70 hover:bg-[#EEF7F5] transition-colors cursor-pointer"
          >
            <span className="font-serif">Body Configuration</span>
            <ChevronDown className={`w-4 h-4 text-[#64748B] transition-transform ${openSection.body ? 'rotate-180' : ''}`} />
          </button>
          {openSection.body && (
            <div className="p-2.5 flex flex-wrap gap-1.5 border-t border-[#D7E7E4]/60 bg-white">
              {bodyStyles.map(style => {
                const isSelected = filters.bodyStyles.includes(style);
                return (
                  <button
                    key={style}
                    onClick={() => handleBodyStyleToggle(style)}
                    className={`px-2.5 py-1 text-xs rounded-lg font-semibold transition-all cursor-pointer ${
                      isSelected
                        ? 'bg-[#176B87] text-white shadow-2xs'
                        : 'border border-[#D7E7E4] text-[#176B87] hover:bg-[#EEF7F5]'
                    }`}
                  >
                    {style}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Fuel Accordion */}
        <div className="border border-[#D7E7E4] rounded-xl overflow-hidden bg-[#EEF7F5]/40 shadow-2xs">
          <button
            onClick={() => toggleSection('fuel')}
            className="w-full p-3 flex items-center justify-between text-xs sm:text-sm font-bold text-[#176B87] bg-[#EEF7F5]/70 hover:bg-[#EEF7F5] transition-colors cursor-pointer"
          >
            <span className="font-serif">Fuel & Powertrain</span>
            <ChevronDown className={`w-4 h-4 text-[#64748B] transition-transform ${openSection.fuel ? 'rotate-180' : ''}`} />
          </button>
          {openSection.fuel && (
            <div className="p-2 space-y-1 border-t border-[#D7E7E4]/60 bg-white">
              {fuelTypes.map(f => {
                const isSelected = filters.fuelType?.includes(f.id);
                return (
                  <button
                    key={f.id}
                    onClick={() => handleFuelToggle(f.id)}
                    className={`w-full flex items-center justify-between p-2 rounded-lg text-xs sm:text-sm font-semibold transition-all cursor-pointer ${
                      isSelected ? 'bg-[#176B87] text-white shadow-2xs' : 'text-[#176B87] hover:bg-[#EEF7F5]'
                    }`}
                  >
                    <span>{f.label}</span>
                    {isSelected && <Check className="w-3.5 h-3.5 text-[#13B8A6]" />}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* City / Location Accordion */}
        <div className="border border-[#D7E7E4] rounded-xl overflow-hidden bg-[#EEF7F5]/40 shadow-2xs">
          <button
            onClick={() => toggleSection('city')}
            className="w-full p-3 flex items-center justify-between text-xs sm:text-sm font-bold text-[#176B87] bg-[#EEF7F5]/70 hover:bg-[#EEF7F5] transition-colors cursor-pointer"
          >
            <span className="font-serif">City / Hub</span>
            <ChevronDown className={`w-4 h-4 text-[#64748B] transition-transform ${openSection.city ? 'rotate-180' : ''}`} />
          </button>
          {openSection.city && (
            <div className="p-2 space-y-1 border-t border-[#D7E7E4]/60 bg-white">
              {cities.map(city => {
                const isSelected = filters.searchQuery.toLowerCase() === city.toLowerCase();
                return (
                  <button
                    key={city}
                    onClick={() => setFilters(prev => ({ ...prev, searchQuery: isSelected ? '' : city }))}
                    className={`w-full flex items-center justify-between p-2 rounded-lg text-xs sm:text-sm font-semibold transition-all cursor-pointer ${
                      isSelected ? 'bg-[#176B87] text-white shadow-2xs' : 'text-[#176B87] hover:bg-[#EEF7F5]'
                    }`}
                  >
                    <span className="flex items-center gap-2">
                      <MapPin className="w-3.5 h-3.5 text-[#13B8A6]" />
                      {city}
                    </span>
                    {isSelected && <Check className="w-3.5 h-3.5 text-[#13B8A6]" />}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Max Price Slider */}
        <div className="border border-[#D7E7E4] rounded-xl p-3.5 bg-[#EEF7F5]/60 space-y-2.5 shadow-2xs">
          <div className="flex items-center justify-between">
            <span className="text-xs sm:text-sm font-bold text-[#176B87] font-serif">Max Budget</span>
            <span className="font-mono font-bold text-xs text-[#176B87] bg-[#13B8A6]/20 border border-[#13B8A6]/40 px-2 py-0.5 rounded-lg">
              {filters.maxPrice < 1000000
                ? `KES ${(filters.maxPrice / 1000).toLocaleString()}K`
                : `KES ${(filters.maxPrice / 1000000).toFixed(1)}M`}
            </span>
          </div>
          <input
            type="range"
            min="450000"
            max="60000000"
            step="500000"
            value={filters.maxPrice}
            onChange={e => setFilters(prev => ({ ...prev, maxPrice: parseFloat(e.target.value) }))}
            className="w-full accent-[#176B87] cursor-pointer h-2 bg-[#D7E7E4] rounded-lg"
          />
        </div>

        {/* Ghost Check Verification Toggle */}
        <label className="flex items-center justify-between text-xs sm:text-sm font-bold text-[#176B87] cursor-pointer p-3 rounded-xl bg-[#EEF7F5] border border-[#D7E7E4] shadow-2xs hover:border-[#176B87] transition-all">
          <span className="flex items-center gap-2">
            <ShieldCheck className="w-4 h-4 text-emerald-600 shrink-0" />
            150-Pt Inspected Vehicles
          </span>
          <input
            type="checkbox"
            checked={filters.certifiedOnly}
            onChange={e => setFilters(prev => ({ ...prev, certifiedOnly: e.target.checked }))}
            className="w-4 h-4 accent-[#176B87] rounded cursor-pointer"
          />
        </label>
      </div>
    </aside>
  );
};

import { useState, useMemo } from 'react';
import {
  LayoutGrid,
  List,
  SlidersHorizontal,
  ArrowUpDown,
  ShieldCheck,
  Search,
  Sparkles,
  X,
  CheckCircle2,
  Lock,
  Car,
  ChevronDown
} from 'lucide-react';
import { useMarketplace } from '../../context/MarketplaceContext';
import { FilterSidebar } from './FilterSidebar';
import { VehicleCard } from './VehicleCard';
import { SearchBar } from '../ui/SearchBar';
import type { FC } from 'react';

export const GalleryPage: FC = () => {
  const { vehicles, filters, setFilters, resetFilters } = useMarketplace();
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [isMobileFilterOpen, setIsMobileFilterOpen] = useState(false);

  // Filter & Sort Logic
  const filteredVehicles = useMemo(() => {
    return vehicles.filter(vehicle => {
      // Search Query
      if (filters.searchQuery) {
        const q = filters.searchQuery.toLowerCase().trim();
        const matchesTitle = vehicle.title?.toLowerCase().includes(q);
        const matchesMake = vehicle.make?.toLowerCase().includes(q);
        const matchesModel = vehicle.model?.toLowerCase().includes(q);
        const matchesVin = vehicle.vin?.toLowerCase().includes(q);
        const matchesLocation = vehicle.location?.toLowerCase().includes(q);
        const matchesSeller = vehicle.sellerName?.toLowerCase().includes(q);
        const matchesBody = vehicle.bodyStyle?.toLowerCase().includes(q);
        const matchesEngine = vehicle.engine?.toLowerCase().includes(q);
        const matchesFuel = vehicle.fuelType?.toLowerCase().includes(q);
        const matchesTrans = vehicle.transmission?.toLowerCase().includes(q);

        if (
          !matchesTitle &&
          !matchesMake &&
          !matchesModel &&
          !matchesVin &&
          !matchesLocation &&
          !matchesSeller &&
          !matchesBody &&
          !matchesEngine &&
          !matchesFuel &&
          !matchesTrans
        ) {
          return false;
        }
      }

      // Makes / Brands
      if (filters.makes.length > 0 && !filters.makes.includes(vehicle.make)) {
        return false;
      }

      // Body Styles
      if (filters.bodyStyles.length > 0 && !filters.bodyStyles.includes(vehicle.bodyStyle)) {
        return false;
      }

      // Price Filter
      const vehiclePrice = vehicle.currentBid || vehicle.price;
      if (vehiclePrice > filters.maxPrice) {
        return false;
      }

      // Fuel Type Filter
      if (filters.fuelType && filters.fuelType.length > 0) {
        if (!filters.fuelType.includes(vehicle.fuelType)) {
          return false;
        }
      }

      // Transmission Filter
      if (filters.transmission && filters.transmission.length > 0) {
        if (!filters.transmission.includes(vehicle.transmission)) {
          return false;
        }
      }

      // Listing Format
      if (filters.listingType === 'auction' && vehicle.listingType === 'fixed') return false;
      if (filters.listingType === 'fixed' && vehicle.listingType === 'auction') return false;

      // Certified Only
      if (filters.certifiedOnly && (!vehicle.inspection || vehicle.inspection.score < 80)) return false;

      return true;
    }).sort((a, b) => {
      const priceA = a.currentBid || a.price;
      const priceB = b.currentBid || b.price;

      if (filters.sortBy === 'newest') {
        return new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime();
      }
      if (filters.sortBy === 'price_desc') return priceB - priceA;
      if (filters.sortBy === 'price_asc') return priceA - priceB;
      if (filters.sortBy === 'year_desc') return b.year - a.year;
      if (filters.sortBy === 'mileage_asc') return a.mileage - b.mileage;
      return 0;
    });
  }, [vehicles, filters]);

  const activeFiltersCount =
    (filters.searchQuery ? 1 : 0) +
    filters.makes.length +
    filters.bodyStyles.length +
    (filters.certifiedOnly ? 1 : 0) +
    (filters.listingType !== 'all' ? 1 : 0) +
    (filters.fuelType?.length || 0);

  return (
    <div className="pt-3 sm:pt-5 pb-10 sm:pb-16 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto space-y-5 sm:space-y-6 bg-[#F6FAF9] text-[#176B87] font-sans min-h-screen">

      {/* KAYAD Premium Showroom Hero Card */}
      <div className="p-4 sm:p-5 rounded-2xl bg-[#176B87] text-white border border-white/10 shadow-lg relative overflow-hidden flex flex-col md:flex-row items-center justify-between gap-4">
        {/* Subtle background glow */}
        <div className="absolute top-0 right-0 w-80 h-80 bg-[#13B8A6]/15 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute bottom-0 left-0 w-48 h-48 bg-white/5 rounded-full blur-2xl pointer-events-none" />

        <div className="relative z-10 space-y-1.5 max-w-2xl text-center md:text-left">
          <div className="inline-flex items-center gap-1.5 px-3 py-0.5 rounded-full bg-[#13B8A6]/20 text-[#13B8A6] text-[10px] font-mono font-black uppercase tracking-[0.2em] border border-[#13B8A6]/30">
            <Sparkles className="w-3 h-3 text-[#13B8A6]" />
            <span>KENYA'S EXCLUSIVE AUTOMOTIVE MARKETPLACE</span>
          </div>

          <h1 className="text-xl sm:text-2xl font-serif font-black text-white tracking-tight uppercase leading-snug">
            KAYAD Premium Showroom
          </h1>

          <p className="text-xs sm:text-sm text-[#DDF4F0] font-sans font-medium max-w-xl leading-relaxed">
            Browse available vehicles, compare listed prices and review the transaction options shown for each listing.
          </p>
        </div>

        {/* Right side trust badges */}
        <div className="relative z-10 flex sm:flex-row md:flex-col gap-2 shrink-0 w-full md:w-auto">
          <div className="flex-1 md:flex-none px-3.5 py-2 rounded-xl bg-white/10 backdrop-blur-md border border-white/15 flex items-center gap-2.5 text-xs text-white">
            <ShieldCheck className="w-4 h-4 text-[#13B8A6] shrink-0" />
            <div>
              <p className="font-mono font-black text-[9px] uppercase text-[#13B8A6] leading-none">Escrow options</p>
              <p className="text-[11px] font-medium text-[#DDF4F0]">Check availability</p>
            </div>
          </div>

          <div className="flex-1 md:flex-none px-3.5 py-2 rounded-xl bg-white/10 backdrop-blur-md border border-white/15 flex items-center gap-2.5 text-xs text-white">
            <Car className="w-4 h-4 text-[#13B8A6] shrink-0" />
            <div>
              <p className="font-mono font-black text-[9px] uppercase text-[#13B8A6] leading-none">Inspection status</p>
              <p className="text-[11px] font-medium text-[#DDF4F0]">See listing details</p>
            </div>
          </div>
        </div>
      </div>

      {/* Main Search & Control Toolbar */}
      <SearchBar
        value={filters.searchQuery}
        onChange={q => setFilters(prev => ({ ...prev, searchQuery: q }))}
        placeholder="Search make, model, VIN, or city..."
        resultCount={filteredVehicles.length}
        badgeLabel="KAYAD SHOWROOM INVENTORY"
        filterOptions={[
          { id: 'all', label: 'All Stock' },
          { id: 'fixed', label: 'Direct Buy' },
          { id: 'auction', label: 'Live Auctions' },
        ]}
        activeFilter={filters.listingType}
        onFilterChange={type => setFilters(prev => ({ ...prev, listingType: type as any }))}
        sortOptions={[
          { id: 'newest', label: 'Newest Arrivals' },
          { id: 'price_desc', label: 'Price: High to Low' },
          { id: 'price_asc', label: 'Price: Low to High' },
          { id: 'year_desc', label: 'Newest Model Year' },
          { id: 'mileage_asc', label: 'Lowest Mileage' },
        ]}
        activeSort={filters.sortBy === 'featured' ? 'newest' : filters.sortBy}
        onSortChange={sort => setFilters(prev => ({ ...prev, sortBy: sort as any }))}
        viewMode={viewMode}
        onViewModeChange={mode => setViewMode(mode)}
        onMobileFilterToggle={() => setIsMobileFilterOpen(!isMobileFilterOpen)}
      />

      {/* Main Showroom Content Layout */}
      <div className="flex flex-col lg:flex-row gap-8">

        {/* Left Sidebar ("REFINE") */}
        <div className="hidden lg:block shrink-0">
          <FilterSidebar />
        </div>

        {/* Mobile Filter Drawer */}
        {isMobileFilterOpen && (
          <div className="lg:hidden mb-6">
            <FilterSidebar />
          </div>
        )}

        {/* Showroom Vehicle Grid */}
        <div className="flex-1 min-w-0 space-y-5">

          {/* Results Count Header */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 px-1 pb-2 border-b border-[#D7E7E4]/70">
            <div className="flex items-center gap-3">
              <span className="text-base sm:text-lg font-serif font-black text-[#176B87]">
                {filteredVehicles.length} {filteredVehicles.length === 1 ? 'vehicle' : 'vehicles'} available
              </span>
              {activeFiltersCount > 0 && (
                <button
                  onClick={resetFilters}
                  className="text-xs font-bold text-[#13B8A6] hover:underline flex items-center gap-1 transition-colors cursor-pointer"
                >
                  Clear filters ({activeFiltersCount})
                </button>
              )}
            </div>

            <div className="flex items-center gap-2 text-xs text-[#64748b] font-bold">
              <span className="flex items-center gap-1.5 text-[#176B87] bg-white px-3 py-1 rounded-full border border-[#D7E7E4] shadow-2xs">
                <ShieldCheck className="w-3.5 h-3.5 text-[#13B8A6]" />
                Escrow availability varies by listing
              </span>
            </div>
          </div>

          {/* Grid Layout */}
          {filteredVehicles.length === 0 ? (
            <div className="p-12 text-center bg-white border border-[#D7E7E4] rounded-3xl space-y-4 shadow-sm my-6">
              <div className="w-16 h-16 mx-auto rounded-full bg-[#176B87]/10 flex items-center justify-center text-[#176B87]">
                <Car className="w-8 h-8 text-[#13B8A6]" />
              </div>
              <h3 className="text-xl font-black text-[#176B87] font-serif">
                No matching vehicles were found. Adjust your filters or clear them to view more listings.
              </h3>
              <p className="text-sm text-[#64748B] max-w-md mx-auto">
                Try clearing active filters or adjusting your budget to view more available listings.
              </p>
              <button
                onClick={resetFilters}
                className="mt-2 inline-flex items-center gap-2 px-6 py-2.5 rounded-full bg-[#176B87] text-white font-extrabold text-xs shadow-md hover:bg-[#0A3340] transition-all cursor-pointer"
              >
                Reset All Filters
              </button>
            </div>
          ) : (
            <div
              className={
                viewMode === 'grid'
                  ? 'grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 gap-6 sm:gap-7 items-stretch'
                  : 'space-y-4'
              }
            >
              {filteredVehicles.map(vehicle => (
                <VehicleCard key={vehicle.id} vehicle={vehicle} viewMode={viewMode} />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import { useState } from 'react';
