import {
  Heart,
  ShieldCheck,
  Tag,
  ChevronLeft,
  ChevronRight,
  Calendar,
  Gauge,
  Fuel,
  Sparkles,
  ArrowRight,
  CheckCircle2,
  Lock,
  MapPin,
  Eye
} from 'lucide-react';
import { Vehicle } from '../../types';
