        </form>

        {/* Expanded Filters Section */}
        {isExpandedFilters && (
          <div className="pt-3 border-t border-white/15 grid grid-cols-2 sm:grid-cols-4 gap-3 animate-fadeIn">

            <div>
              <label className="text-[10px] font-mono font-bold uppercase tracking-wider text-[#BDE5DE] block mb-1">
                Location
              </label>
              <select
                value={selectedLocation}
                onChange={(e) => setSelectedLocation(e.target.value)}
                className="w-full px-3 py-2 bg-[#12576D] dark:bg-[#0A3340] text-white rounded-xl text-xs font-mono font-bold border border-white/15 focus:outline-none"
              >
                <option value="all">All Kenya</option>
                {locations.map((loc) => (
                  <option key={loc} value={loc}>{loc}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="text-[10px] font-mono font-bold uppercase tracking-wider text-[#BDE5DE] block mb-1">
