const VERIFICATION_BADGE_COLORS: Record<string, { bg: string; text: string; border: string }> = {
  verified: { bg: 'bg-emerald-100', text: 'text-emerald-800', border: 'border-emerald-300' },
  premium: { bg: 'bg-[#DDF4F0]', text: 'text-[#0A3340]', border: 'border-[#BDE5DE]' },
  government: { bg: 'bg-[#DDF4F0]', text: 'text-[#0E4655]', border: 'border-[#BDE5DE]' },
  bank: { bg: 'bg-[#DDF4F0]', text: 'text-[#0E4655]', border: 'border-[#BDE5DE]' },
