    return (
      <Card className="p-6 bg-white border-[#D7E7E4] space-y-6">
        {/* Header */}
        <div className="flex items-start gap-4">
          <div className="w-16 h-16 rounded-2xl bg-[#176B87] flex items-center justify-center text-white font-bold text-2xl overflow-hidden shadow-md flex-shrink-0">
            {organizer.logo ? (
              <img src={organizer.logo} alt={organizer.name} className="w-full h-full object-cover" />
            ) : (
              organizer.name.charAt(0).toUpperCase()
            )}
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <h3 className="font-black text-lg text-[#176B87]">{organizer.name}</h3>
              {organizer.isVerified && (
                <Badge variant="success" size="sm" className="bg-emerald-100 text-emerald-800 border-emerald-200">
                  <ShieldCheck className="w-3 h-3 mr-0.5" />
                  Verified Organizer
                </Badge>
              )}
            </div>
            <div className="flex items-center gap-2 text-sm text-[#64748B] mt-1">
              <span className="flex items-center gap-1">
                {TYPE_ICONS[organizer.type]}
                {typeDisplay}
              </span>
            </div>
            {organizer.rating && (
              <div className="flex items-center gap-1 mt-1">
                {[...Array(5)].map((_, i) => (
                  <Star
                    key={i}
                    className={`w-4 h-4 ${i < Math.round(organizer.rating!) ? 'text-[#176B87] fill-[#176B87]' : 'text-[#BDE5DE]'}`}
                  />
                ))}
                <span className="text-sm text-[#64748B] ml-1">{organizer.rating.toFixed(1)}</span>
              </div>
            )}
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-3 gap-3">
          {organizer.yearsOnPlatform && (
