        ) : (
          <Circle className="w-4 h-4" />
        )}
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className={`text-sm font-medium ${check.isComplete ? 'text-[#12576D] line-through' : 'text-[#0A3340]'}`}>
            {check.label}
          </span>
          {isRequired && !check.isComplete && (
            <Badge variant="danger" size="sm" className="text-[10px] bg-red-100 text-red-700 border-red-200">
              Required
            </Badge>
          )}
          {!isRequired && (
