      {editable && (
        <button
          onClick={() => onToggle?.(check.id, !check.isComplete)}
          className={`px-3 py-1 rounded-lg text-xs font-bold transition-colors ${
            check.isComplete
              ? 'bg-[#DDF4F0] text-[#12576D] hover:bg-[#BDE5DE]'
              : 'bg-emerald-600 text-white hover:bg-emerald-700'
          }`}
        >
