import { useState, useRef, useEffect } from 'react';

export interface TooltipProps {
  content: React.ReactNode;
  children: React.ReactElement;
  position?: 'top' | 'bottom' | 'left' | 'right';
  delay?: number;
  disabled?: boolean;
  className?: string;
}

const positionStyles = {
  top: 'bottom-full left-1/2 -translate-x-1/2 mb-2',
  bottom: 'top-full left-1/2 -translate-x-1/2 mt-2',
  left: 'right-full top-1/2 -translate-y-1/2 mr-2',
  right: 'left-full top-1/2 -translate-y-1/2 ml-2',
};

const arrowStyles = {
  top: 'top-full left-1/2 -translate-x-1/2 border-t-[var(--tooltip-bg)] border-l-transparent border-r-transparent border-b-transparent',
  bottom: 'bottom-full left-1/2 -translate-x-1/2 border-b-[var(--tooltip-bg)] border-l-transparent border-r-transparent border-t-transparent',
  left: 'left-full top-1/2 -translate-y-1/2 border-l-[var(--tooltip-bg)] border-t-transparent border-b-transparent border-r-transparent',
  right: 'right-full top-1/2 -translate-y-1/2 border-r-[var(--tooltip-bg)] border-t-transparent border-b-transparent border-l-transparent',
};

export function Tooltip({
  content,
  children,
  position = 'top',
  delay = 200,
  disabled = false,
  className = '',
}: TooltipProps) {
  const [isVisible, setIsVisible] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout | undefined>(undefined);
  const triggerRef = useRef<HTMLDivElement>(null);

  const showTooltip = () => {
    if (disabled) return;
    timeoutRef.current = setTimeout(() => {
      setIsVisible(true);
    }, delay);
  };

  const hideTooltip = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setIsVisible(false);
  };

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  return (
    <div
      ref={triggerRef}
      className="relative inline-flex"
      onMouseEnter={showTooltip}
      onMouseLeave={hideTooltip}
      onFocus={showTooltip}
      onBlur={hideTooltip}
    >
      {children}

      {isVisible && (
        <div
          role="tooltip"
          className={`
            absolute z-[var(--z-tooltip)]
            ${positionStyles[position]}
            px-3 py-2
            text-sm text-white
            bg-[var(--tooltip-bg,#12576d)]
            rounded-lg
            shadow-lg
            whitespace-nowrap
            pointer-events-none
            animate-in fade-in zoom-in-95 duration-150
            ${className}
          `}
        >
          {content}
          <span
            className={`
              absolute w-0 h-0
              border-4
              ${arrowStyles[position]}
            `}
          />
        </div>
      )}
    </div>
  );
}

// Popover Component (click-triggered)
export interface PopoverProps {
  trigger: React.ReactElement;
  children: React.ReactNode;
  position?: 'top' | 'bottom' | 'left' | 'right';
  className?: string;
}

export function Popover({
  trigger,
  children,
  position = 'bottom',
  className = '',
}: PopoverProps) {
  const [isOpen, setIsOpen] = useState(false);
  const popoverRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        popoverRef.current &&
        !popoverRef.current.contains(event.target as Node) &&
        triggerRef.current &&
        !triggerRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen]);

  const positionStyles = {
    top: 'bottom-full left-1/2 -translate-x-1/2 mb-2',
    bottom: 'top-full left-1/2 -translate-x-1/2 mt-2',
    left: 'right-full top-1/2 -translate-y-1/2 mr-2',
    right: 'left-full top-1/2 -translate-y-1/2 ml-2',
  };

  return (
    <div className="relative inline-flex">
      <div ref={triggerRef} onClick={() => setIsOpen(!isOpen)}>
        {trigger}
      </div>

      {isOpen && (
        <div
          ref={popoverRef}
          className={`
            absolute z-[var(--z-dropdown)]
            ${positionStyles[position]}
            ${className}
          `}
        >
          {children}
        </div>
      )}
    </div>
  );
}

export default Tooltip;

import { useRef, useState } from 'react';
import { Upload, X, Image as ImageIcon, Loader2, FolderOpen } from 'lucide-react';
import { MediaLibraryModal } from '@/components/admin/MediaLibraryModal';
import { uploadImageToStorage } from '@/lib/upload';

interface ImageUploadProps {
  value: string;
  onChange: (url: string) => void;
  label?: string;
  folder?: string;
  className?: string;
}

export function ImageUpload({
  value,
  onChange,
  label = 'Image',
  folder = 'general',
  className = '',
}: ImageUploadProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [warning, setWarning] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [libraryOpen, setLibraryOpen] = useState(false);

  async function uploadFile(file: File) {
    setError(null);
    setWarning(null);

    setUploading(true);

    try {
      const { url } = await uploadImageToStorage(file, folder);
      onChange(url);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  }

  function handleFileSelect(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (file) uploadFile(file);
    e.target.value = '';
  }

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files?.[0];
    if (file) uploadFile(file);
  }

  function handleRemove() {
    onChange('');
  }

  return (
    <div className={className}>
      {label && (
        <label className="block text-sm font-medium text-[#12576D] mb-1.5">
          {label}
        </label>
      )}

      {value ? (
        <div className="relative group">
          <div className="w-full h-40 rounded-lg overflow-hidden border border-[#D7E7E4] bg-[#F6FAF9]">
            <img
              src={value}
              alt="Preview"
              className="w-full h-full object-cover"
            />
          </div>
          <button
            type="button"
            onClick={handleRemove}
            className="absolute top-2 right-2 p-1.5 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors shadow-lg opacity-0 group-hover:opacity-100"
          >
            <X className="w-4 h-4" />
          </button>
          <div className="mt-2 flex items-center gap-3">
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              disabled={uploading}
              className="text-xs text-primary-600 hover:text-primary-700 font-medium disabled:opacity-50"
            >
              {uploading ? 'Uploading...' : 'Replace image'}
            </button>
            <button
              type="button"
              onClick={() => setLibraryOpen(true)}
              className="text-xs text-[#64748B] hover:text-[#12576D] font-medium flex items-center gap-1"
            >
              <FolderOpen className="w-3.5 h-3.5" /> Browse Library
            </button>
          </div>
        </div>
      ) : (
        <div
          onDragOver={(e) => {
            e.preventDefault();
            setDragOver(true);
          }}
          onDragLeave={() => setDragOver(false)}
          onDrop={handleDrop}
          className={`w-full rounded-lg border-2 border-dashed transition-colors ${
            dragOver
              ? 'border-primary-500 bg-primary-50'
              : 'border-[#BDE5DE] hover:border-primary-400 hover:bg-[#F6FAF9]'
          } ${uploading ? 'pointer-events-none' : ''}`}
        >
          <div
            onClick={() => !uploading && fileInputRef.current?.click()}
            className="h-32 flex flex-col items-center justify-center cursor-pointer"
          >
            {uploading ? (
              <>
                <Loader2 className="w-7 h-7 text-primary-500 animate-spin mb-2" />
                <p className="text-sm text-[#64748B]">Uploading...</p>
              </>
            ) : (
              <>
                <div className="w-10 h-10 rounded-full bg-[#EEF7F5] flex items-center justify-center mb-2">
                  <Upload className="w-5 h-5 text-[#94A3B8]" />
                </div>
                <p className="text-sm font-medium text-[#64748B]">
                  Click to upload or drag & drop
                </p>
                <p className="text-xs text-[#94A3B8] mt-1">
                  PNG, JPG, WebP, GIF, AVIF up to 5MB
                </p>
              </>
            )}
          </div>
          <button
            type="button"
            onClick={() => setLibraryOpen(true)}
            className="w-full py-2 text-xs text-[#64748B] hover:text-primary-600 font-medium border-t border-[#D7E7E4] flex items-center justify-center gap-1.5"
          >
            <FolderOpen className="w-3.5 h-3.5" /> Or browse Media Library
          </button>
        </div>
      )}

      {error && (
        <p className="mt-1.5 text-xs text-red-600">{error}</p>
      )}
      {warning && (
        <p className="mt-1.5 text-xs text-[#176B87]">{warning}</p>
      )}

      <input
        ref={fileInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp,image/gif,image/avif"
        onChange={handleFileSelect}
        className="hidden"
      />

      {libraryOpen && (
        <MediaLibraryModal
          currentValue={value}
          onSelect={(url) => { onChange(url); setLibraryOpen(false); }}
          onClose={() => setLibraryOpen(false)}
        />
      )}
    </div>
  );
}

interface MultiImageUploadProps {
  value: string[];
  onChange: (urls: string[]) => void;
  label?: string;
  folder?: string;
  className?: string;
}

export function MultiImageUpload({
  value,
  onChange,
  label = 'Images',
  folder = 'gallery',
  className = '',
}: MultiImageUploadProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [warning, setWarning] = useState<string | null>(null);

  async function uploadFiles(files: FileList) {
    setError(null);
    setWarning(null);
    setUploading(true);

    try {
      const urls: string[] = [];
      const failures: string[] = [];
      for (const file of Array.from(files)) {
        try {
          const { url } = await uploadImageToStorage(file, folder);
          urls.push(url);
        } catch (err) {
          failures.push(`${file.name}: ${err instanceof Error ? err.message : 'Upload failed'}`);
        }
      }
      if (urls.length > 0) onChange([...value, ...urls]);
      if (failures.length > 0) setError(failures.join(' | '));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  }

  function handleRemove(index: number) {
    onChange(value.filter((_, i) => i !== index));
  }

  return (
    <div className={className}>
      {label && (
        <label className="block text-sm font-medium text-[#12576D] mb-1.5">
          {label}
        </label>
      )}

      <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
        {value.map((url, i) => (
          <div key={i} className="relative group">
            <div className="aspect-square rounded-lg overflow-hidden border border-[#D7E7E4] bg-[#F6FAF9]">
              <img src={url} alt="" className="w-full h-full object-cover" />
            </div>
            <button
              type="button"
              onClick={() => handleRemove(i)}
              className="absolute top-1 right-1 p-1 bg-red-500 text-white rounded hover:bg-red-600 transition-colors shadow opacity-0 group-hover:opacity-100"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        ))}

        <div
          onClick={() => !uploading && fileInputRef.current?.click()}
          className="aspect-square rounded-lg border-2 border-dashed border-[#BDE5DE] hover:border-primary-400 hover:bg-[#F6FAF9] flex flex-col items-center justify-center cursor-pointer transition-colors"
        >
          {uploading ? (
            <Loader2 className="w-6 h-6 text-primary-500 animate-spin" />
          ) : (
            <>
              <ImageIcon className="w-6 h-6 text-[#94A3B8] mb-1" />
              <span className="text-xs text-[#64748B]">Add</span>
            </>
          )}
        </div>
      </div>

      {error && <p className="mt-1.5 text-xs text-red-600">{error}</p>}
      {warning && <p className="mt-1.5 text-xs text-[#176B87]">{warning}</p>}

      <input
        ref={fileInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp,image/gif,image/avif"
        multiple
        onChange={(e) => {
          if (e.target.files?.length) uploadFiles(e.target.files);
          e.target.value = '';
        }}
        className="hidden"
      />
    </div>
  );
}

