import React, { useState, useEffect, useRef } from 'react';
import { X } from 'lucide-react';

/* ==========================================================================
   KAYAD AUTOMOTIVE DESIGN SYSTEM TOKENS & REUSABLE COMPONENTS
   ========================================================================== */

// --- BUTTON COMPONENT ---
export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'accent' | 'outline' | 'ghost' | 'danger' | 'coral' | 'success';
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
  fullWidth?: boolean;
  full?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({
  variant = 'primary',
  size = 'md',
  fullWidth = false,
  full = false,
  icon,
  children,
  className = '',
  disabled,
  ...props
}) => {
  const baseStyles = 'inline-flex items-center justify-center font-bold transition-all focus:outline-none focus:ring-2 focus:ring-[#176B87]/50 disabled:opacity-50 disabled:cursor-not-allowed select-none active:scale-[0.98]';

  const variantStyles = {
    primary: 'bg-[#176B87] hover:bg-[#0A3340] text-white shadow-sm',
    secondary: 'bg-[#EEF7F5] hover:bg-[#DDF4F0] text-[#0A3340] border border-[#D7E7E4]/80',
    accent: 'bg-[#13B8A6] hover:bg-[#13B8A6] text-[#0A3340] shadow-sm',
    outline: 'border border-[#BDE5DE] hover:bg-[#F6FAF9] text-[#12576D]',
    ghost: 'text-[#64748B] hover:bg-[#EEF7F5] hover:text-[#0A3340]',
    danger: 'bg-rose-600 hover:bg-rose-700 text-white shadow-sm',
    coral: 'bg-[#176b87] hover:bg-[#12576D] text-white shadow-sm',
    success: 'bg-emerald-600 hover:bg-emerald-700 text-white shadow-sm'
  };

  const sizeStyles = {
    sm: 'text-[11px] px-3 py-1.5 rounded-lg gap-1.5',
    md: 'text-xs px-4 py-2.5 rounded-xl gap-2',
    lg: 'text-sm px-5 py-3 rounded-xl gap-2.5'
  };

  const widthStyle = fullWidth || full ? 'w-full' : '';

  return (
    <button
      className={`${baseStyles} ${variantStyles[variant]} ${sizeStyles[size]} ${widthStyle} ${className}`}
      disabled={disabled}
      {...props}
    >
      {icon && <span aria-hidden="true">{icon}</span>}
      {children}
    </button>
  );
};

// --- BADGE COMPONENT ---
export interface BadgeProps {
  variant?: 'verified' | 'inspected' | 'escrow' | 'live' | 'accent' | 'neutral' | 'success' | 'warning' | 'danger' | 'outline' | 'secondary' | 'blue' | 'green' | 'orange' | 'premium' | 'info' | 'amber';
  size?: 'sm' | 'md';
  children: React.ReactNode;
  className?: string;
}

export const Badge: React.FC<BadgeProps> = ({
  variant = 'neutral',
  size = 'sm',
  children,
  className = ''
}) => {
  const baseStyles = 'inline-flex items-center font-bold rounded-md backdrop-blur-md select-none';

  const variantStyles = {
    verified: 'bg-[#176B87]/90 text-white border border-[#176B87]',
    inspected: 'bg-emerald-600/95 text-white',
    escrow: 'bg-[#13B8A6]/95 text-[#0A3340]',
    live: 'bg-rose-600 text-white animate-pulse',
    accent: 'bg-[#13B8A6] text-[#0A3340]',
    neutral: 'bg-[#EEF7F5] text-[#12576D] border border-[#D7E7E4]',
    success: 'bg-emerald-50 text-emerald-700 border border-emerald-200',
    warning: 'bg-[#F3FAF9] text-[#0A3340] border border-[#BDE5DE]',
    danger: 'bg-rose-50 text-rose-700 border border-rose-200',
    outline: 'bg-transparent text-[#64748B] border border-[#BDE5DE]',
    secondary: 'bg-[#DDF4F0] text-[#0A3340] border border-[#BDE5DE]',
    blue: 'bg-[#F3FAF9] text-[#12576D] border border-[#D7E7E4]',
    green: 'bg-emerald-50 text-emerald-700 border border-emerald-200',
    orange: 'bg-[#F3FAF9] text-[#12576D] border border-[#D7E7E4]',
    premium: 'bg-[#F3FAF9] text-[#0A3340] border border-[#BDE5DE]',
    info: 'bg-[#F3FAF9] text-[#12576D] border border-[#D7E7E4]',
    amber: 'bg-[#F3FAF9] text-[#0A3340] border border-[#BDE5DE]'
  };

  const sizeStyles = {
    sm: 'text-[10px] px-2 py-0.5 gap-1',
    md: 'text-xs px-2.5 py-1 gap-1.5'
  };

  return (
    <span className={`${baseStyles} ${variantStyles[variant]} ${sizeStyles[size]} ${className}`}>
      {children}
    </span>
  );
};

// --- CARD COMPONENTS ---
export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  hoverable?: boolean;
}

export const Card: React.FC<CardProps> = ({ children, hoverable = false, className = '', ...props }) => {
  const hoverStyle = hoverable ? 'hover:shadow-card-hover hover:border-[#BDE5DE]' : '';
  return (
    <div
      className={`bg-white rounded-2xl border border-[#D7E7E4] shadow-card transition-all duration-300 overflow-hidden ${hoverStyle} ${className}`}
      {...props}
    >
      {children}
    </div>
  );
};

export const CardHeader: React.FC<React.HTMLAttributes<HTMLDivElement>> = ({ children, className = '', ...props }) => (
  <div className={`p-5 pb-3 border-b border-[#D7E7E4] ${className}`} {...props}>
    {children}
  </div>
