// --- INTERSECTION OBSERVER LAZY IMAGE ---
export interface LazyImageProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  src: string;
  alt: string;
  className?: string;
  wrapperClassName?: string;
}

export const Image: React.FC<LazyImageProps> = ({
  src,
  alt,
  className = '',
  wrapperClassName = '',
  ...props
}) => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isInView, setIsInView] = useState(false);
  const [hasError, setHasError] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    if (!('IntersectionObserver' in window)) {
      setIsInView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsInView(true);
          observer.disconnect();
        }
      },
      { rootMargin: '200px 0px' }
    );

    observer.observe(containerRef.current);

    return () => {
      observer.disconnect();
    };
  }, []);

  return (
    <div ref={containerRef} className={`relative overflow-hidden ${wrapperClassName}`}>
      {(!isLoaded || !isInView) && !hasError && (
        <div className="absolute inset-0 bg-[#DDF4F0]/80 animate-pulse flex items-center justify-center z-0">
          <div className="w-6 h-6 border-2 border-[#BDE5DE] border-t-[#13B8A6] rounded-full animate-spin opacity-50" />
        </div>
      )}

      {hasError && (
        <div className="absolute inset-0 bg-[#EEF7F5] flex flex-col items-center justify-center text-[#94A3B8] p-2 text-center text-xs font-semibold">
          <span>Image unavailable</span>
        </div>
      )}

      {isInView && (
        <img
          src={src}
          alt={alt}
          loading="lazy"
          referrerPolicy="no-referrer"
          onLoad={() => setIsLoaded(true)}
          onError={() => setHasError(true)}
          className={`transition-opacity duration-300 ${
            isLoaded ? 'opacity-100' : 'opacity-0'
          } ${className}`}
          {...props}
        />
      )}
    </div>
  );
};

// Export Image as LazyImage for backward compatibility
export const LazyImage = Image;

