import React, { useEffect, useState } from 'react';
import { X, Trash2, Plus, Eye, EyeOff, Loader2 } from 'lucide-react';
import { AdSlot, AdPlacement, AdDisplayMode, AdSlotInput, AdStat, getAllAdSlots, getAdStats, createAdSlot, updateAdSlot, deleteAdSlot, AdApiError } from '../../services/adApi';

interface AdManagerPanelProps {
  onClose: () => void;
}

const PLACEMENT_LABELS: Record<AdPlacement, string> = {
  top_ticker: 'Top Scrolling Strip',
  left_rail: 'Left Floating Rail',
  right_rail: 'Right Floating Rail',
  mid_grid: 'Mid-Grid Card',
  sidebar: 'Filter Sidebar',
};

const EMPTY_DRAFT: AdSlotInput = {
  placement: 'top_ticker',
  title: '',
  tagline: '',
  priceTag: '',
  buttonText: '',
  buttonUrl: '',
  backgroundColor: '#176B87',
  textColor: '#FFFFFF',
  opacity: 100,
  sortOrder: 0,
  displayMode: 'scroll',
  scrollDurationSeconds: 28,
  fadeDurationMs: 4500,
};

/**
 * Real, backend-connected Ad Manager - deliberately different from
 * HomePageAdminPanel (which is localStorage-only, presentation-only
 * page layout). Every real advertiser's ad needs to be visible to
 * every real visitor, so every action here (create/edit/color/hide/
 * remove) is a real call to the real backend, not local-only state -
 * confirmed end-to-end against a real database before this panel was
 * built (see the commit history for this feature). The admin writes
 * any text and picks any color for any advertiser here, entirely
 * through this UI - no code change is ever needed.
 */
export const AdManagerPanel: React.FC<AdManagerPanelProps> = ({ onClose }) => {
  const [slots, setSlots] = useState<AdSlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [savingId, setSavingId] = useState<string | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [draft, setDraft] = useState<AdSlotInput>(EMPTY_DRAFT);
  const [creating, setCreating] = useState(false);
  const [stats, setStats] = useState<AdStat[]>([]);

  const loadSlots = () => {
    setLoading(true);
    setError(null);
    Promise.all([getAllAdSlots(), getAdStats()])
      .then(([nextSlots, nextStats]) => { setSlots(nextSlots); setStats(nextStats); })
      .catch((err) => setError(err instanceof AdApiError ? err.message : 'Could not load ads.'))
      .finally(() => setLoading(false));
  };

  useEffect(() => { loadSlots(); }, []);

  const handleFieldChange = (id: string, field: keyof AdSlotInput | 'isVisible', value: string | number | boolean) => {
    setSlots((prev) => prev.map((s) => s.id === id ? { ...s, [field]: value } : s));
  };

  const handleSave = async (slot: AdSlot) => {
    setSavingId(slot.id);
    try {
      const updated = await updateAdSlot(slot.id, {
        placement: slot.placement,
        title: slot.title,
        tagline: slot.tagline,
        priceTag: slot.priceTag,
        buttonText: slot.buttonText,
        buttonUrl: slot.buttonUrl,
        backgroundColor: slot.backgroundColor,
        textColor: slot.textColor,
        opacity: slot.opacity,
        isVisible: slot.isVisible,
        sortOrder: slot.sortOrder,
        displayMode: slot.displayMode,
        scrollDurationSeconds: slot.scrollDurationSeconds,
        fadeDurationMs: slot.fadeDurationMs,
      });
      setSlots((prev) => prev.map((s) => s.id === updated.id ? updated : s));
    } catch (err) {
      setError(err instanceof AdApiError ? err.message : 'Could not save this ad.');
    } finally {
      setSavingId(null);
    }
  };

  const handleToggleVisible = async (slot: AdSlot) => {
    setSavingId(slot.id);
    try {
      const updated = await updateAdSlot(slot.id, { isVisible: !slot.isVisible });
      setSlots((prev) => prev.map((s) => s.id === updated.id ? updated : s));
    } catch (err) {
      setError(err instanceof AdApiError ? err.message : 'Could not update visibility.');
    } finally {
      setSavingId(null);
    }
  };

  const handleDelete = async (slot: AdSlot) => {
    if (!window.confirm(`Remove "${slot.title}" permanently? This cannot be undone.`)) return;
    setSavingId(slot.id);
    try {
      await deleteAdSlot(slot.id);
      setSlots((prev) => prev.filter((s) => s.id !== slot.id));
    } catch (err) {
      setError(err instanceof AdApiError ? err.message : 'Could not remove this ad.');
      setSavingId(null);
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!draft.title.trim()) return;
    setCreating(true);
    try {
      const created = await createAdSlot(draft);
      setSlots((prev) => [...prev, created]);
      setDraft(EMPTY_DRAFT);
      setShowAddForm(false);
    } catch (err) {
      setError(err instanceof AdApiError ? err.message : 'Could not create this ad.');
    } finally {
      setCreating(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-[#0A3340]/50 z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl w-full max-w-3xl max-h-[85vh] overflow-y-auto shadow-2xl">
        <div className="sticky top-0 bg-white border-b border-[#D7E7E4] px-5 py-4 flex items-center justify-between">
          <div>
            <h2 className="text-base font-bold text-[#176B87]">Ad Manager</h2>
            <p className="text-xs text-[#64748B] mt-0.5">Control every ad slot on the page — toggle visibility, adjust transparency, edit the pitch, or remove a placement.</p>
          </div>
          <button onClick={onClose} className="p-1.5 hover:bg-[#EEF7F5] rounded-lg">
            <X className="w-5 h-5 text-[#64748B]" />
          </button>
        </div>

        <div className="p-5 space-y-4">
          {error && (
            <div className="p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-800 font-semibold">
              {error}
            </div>
          )}

          {!loading && slots.length > 0 && (
            <div className="grid grid-cols-3 gap-2">
              <div className="rounded-xl bg-[#F6FAF9] p-3"><div className="text-[10px] uppercase tracking-wide text-[#64748B]">Impressions</div><div className="text-lg font-bold text-[#0A3340]">{stats.reduce((n, a) => n + a.impressions, 0).toLocaleString()}</div></div>
              <div className="rounded-xl bg-[#F6FAF9] p-3"><div className="text-[10px] uppercase tracking-wide text-[#64748B]">Clicks</div><div className="text-lg font-bold text-[#0A3340]">{stats.reduce((n, a) => n + a.clicks, 0).toLocaleString()}</div></div>
              <div className="rounded-xl bg-[#F6FAF9] p-3"><div className="text-[10px] uppercase tracking-wide text-[#64748B]">CTR</div><div className="text-lg font-bold text-[#0A3340]">{(() => { const i=stats.reduce((n,a)=>n+a.impressions,0); const c=stats.reduce((n,a)=>n+a.clicks,0); return i ? `${((c/i)*100).toFixed(2)}%` : '0.00%'; })()}</div></div>
            </div>
          )}

          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-5 h-5 text-[#94A3B8] animate-spin" />
            </div>
          ) : (
            <>
              {slots.map((slot) => (
                <div key={slot.id} className="border border-[#D7E7E4] rounded-xl p-4 space-y-3">
                  <div className="flex items-center justify-between">
                    <select
                      value={slot.placement}
                      onChange={(e) => handleFieldChange(slot.id, 'placement', e.target.value)}
                      className="text-xs font-bold text-[#176B87] border border-[#D7E7E4] rounded-lg px-2 py-1"
                    >
                      {Object.entries(PLACEMENT_LABELS).map(([val, label]) => (
                        <option key={val} value={val}>{label}</option>
                      ))}
                    </select>
                    <div className="flex items-center gap-2">
                      <button
                        onClick={() => handleToggleVisible(slot)}
                        disabled={savingId === slot.id}
                        className={`p-1.5 rounded-lg ${slot.isVisible ? 'text-emerald-600 bg-emerald-50' : 'text-[#94A3B8] bg-[#EEF7F5]'}`}
                        title={slot.isVisible ? 'Visible on page' : 'Hidden from page'}
                      >
                        {slot.isVisible ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                      </button>
                      <button
                        onClick={() => handleDelete(slot)}
                        disabled={savingId === slot.id}
                        className="p-1.5 rounded-lg text-rose-500 hover:bg-rose-50"
                        title="Remove Ad"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>

                  <input
                    value={slot.title}
                    onChange={(e) => handleFieldChange(slot.id, 'title', e.target.value)}
                    placeholder="Title"
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-sm font-semibold"
                  />
                  <input
                    value={slot.tagline || ''}
                    onChange={(e) => handleFieldChange(slot.id, 'tagline', e.target.value)}
                    placeholder="Tagline"
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                  />
                  <div className="grid grid-cols-2 gap-2">
                    <input
                      value={slot.priceTag || ''}
                      onChange={(e) => handleFieldChange(slot.id, 'priceTag', e.target.value)}
                      placeholder="Price Tag (e.g. From Ksh 15,000/mo)"
                      className="border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                    />
                    <input
                      value={slot.buttonText || ''}
                      onChange={(e) => handleFieldChange(slot.id, 'buttonText', e.target.value)}
                      placeholder="Button Text"
                      className="border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                    />
                  </div>
                  <input
                    value={slot.buttonUrl || ''}
                    onChange={(e) => handleFieldChange(slot.id, 'buttonUrl', e.target.value)}
                    placeholder="Button Link (https://...)"
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                  />

                  {slot.placement === 'top_ticker' && (
                    <div className="rounded-xl border border-[#D7E7E4] bg-[#F6FAF9] p-3 space-y-3">
                      <div>
                        <div className="text-[10px] font-bold uppercase tracking-wider text-[#64748B]">Top notice board behaviour</div>
                        <div className="text-[11px] text-[#64748B] mt-0.5">Choose the TV-style presentation used by the notice strip above the navbar.</div>
                      </div>
                      <div className="grid grid-cols-2 gap-2">
                        <label className="text-xs text-[#64748B]">
                          <span className="block mb-1 font-semibold">Animation</span>
                          <select
                            value={slot.displayMode || 'scroll'}
                            onChange={(e) => handleFieldChange(slot.id, 'displayMode', e.target.value as AdDisplayMode)}
                            className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs bg-white"
                          >
                            <option value="scroll">Scroll right → left</option>
                            <option value="fade">Fade between notices</option>
                          </select>
                        </label>
                        {(slot.displayMode || 'scroll') === 'scroll' ? (
                          <label className="text-xs text-[#64748B]">
                            <span className="block mb-1 font-semibold">Scroll duration</span>
                            <select
                              value={slot.scrollDurationSeconds || 28}
                              onChange={(e) => handleFieldChange(slot.id, 'scrollDurationSeconds', Number(e.target.value))}
                              className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs bg-white"
                            >
                              <option value={18}>Fast · 18s</option>
                              <option value={28}>Normal · 28s</option>
                              <option value={40}>Slow · 40s</option>
                              <option value={55}>Very slow · 55s</option>
                            </select>
                          </label>
                        ) : (
                          <label className="text-xs text-[#64748B]">
                            <span className="block mb-1 font-semibold">Fade duration</span>
                            <select
                              value={slot.fadeDurationMs || 4500}
                              onChange={(e) => handleFieldChange(slot.id, 'fadeDurationMs', Number(e.target.value))}
                              className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs bg-white"
                            >
                              <option value={2500}>Fast · 2.5s</option>
                              <option value={4500}>Normal · 4.5s</option>
                              <option value={6500}>Slow · 6.5s</option>
                              <option value={9000}>Very slow · 9s</option>
                            </select>
                          </label>
                        )}
                      </div>
                    </div>
                  )}

                  <div className="flex items-center gap-4 flex-wrap">
                    <label className="flex items-center gap-2 text-xs text-[#64748B]">
                      Background
                      <input
                        type="color"
                        value={slot.backgroundColor}
                        onChange={(e) => handleFieldChange(slot.id, 'backgroundColor', e.target.value)}
                        className="w-8 h-8 rounded border border-[#D7E7E4] cursor-pointer"
                      />
                    </label>
                    <label className="flex items-center gap-2 text-xs text-[#64748B]">
                      Text
                      <input
                        type="color"
                        value={slot.textColor}
                        onChange={(e) => handleFieldChange(slot.id, 'textColor', e.target.value)}
                        className="w-8 h-8 rounded border border-[#D7E7E4] cursor-pointer"
                      />
                    </label>
                    <label className="flex items-center gap-2 text-xs text-[#64748B] flex-1 min-w-[140px]">
                      Transparency
                      <input
                        type="range"
                        min={10}
                        max={100}
                        value={slot.opacity}
                        onChange={(e) => handleFieldChange(slot.id, 'opacity', Number(e.target.value))}
                        className="flex-1"
                      />
                      <span className="w-8 text-right">{slot.opacity}%</span>
                    </label>
                  </div>

                  {/* Live preview, using this slot's own real colors */}
                  <div
                    className="rounded-lg px-3 py-2 text-xs font-semibold"
                    style={{ backgroundColor: slot.backgroundColor, color: slot.textColor, opacity: slot.opacity / 100 }}
                  >
                    {slot.title || 'Preview'}{slot.tagline ? ` — ${slot.tagline}` : ''}
                  </div>

                  <button
                    onClick={() => handleSave(slot)}
                    disabled={savingId === slot.id}
                    className="bg-[#176B87] hover:bg-[#0A3340] text-white text-xs font-bold rounded-lg px-4 py-2 disabled:opacity-50"
                  >
                    {savingId === slot.id ? 'Saving…' : 'Save Changes'}
                  </button>
                </div>
              ))}

              {showAddForm ? (
                <form onSubmit={handleCreate} className="border-2 border-dashed border-[#176B87]/40 rounded-xl p-4 space-y-3">
                  <select
                    value={draft.placement}
                    onChange={(e) => setDraft((d) => ({ ...d, placement: e.target.value as AdPlacement }))}
                    className="text-xs font-bold text-[#176B87] border border-[#D7E7E4] rounded-lg px-2 py-1"
                  >
                    {Object.entries(PLACEMENT_LABELS).map(([val, label]) => (
                      <option key={val} value={val}>{label}</option>
                    ))}
                  </select>
                  <input
                    value={draft.title}
                    onChange={(e) => setDraft((d) => ({ ...d, title: e.target.value }))}
                    placeholder="Title"
                    required
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-sm"
                  />
                  <input
                    value={draft.tagline}
                    onChange={(e) => setDraft((d) => ({ ...d, tagline: e.target.value }))}
                    placeholder="Tagline"
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                  />
                  <div className="flex gap-2">
                    <button type="submit" disabled={creating} className="bg-[#176B87] hover:bg-[#12576D] text-white text-xs font-bold rounded-lg px-4 py-2 disabled:opacity-50">
                      {creating ? 'Creating…' : 'Create Ad'}
                    </button>
                    <button type="button" onClick={() => setShowAddForm(false)} className="text-xs font-semibold text-[#64748B] px-4 py-2">
                      Cancel
                    </button>
                  </div>
                </form>
              ) : (
                <button
                  onClick={() => setShowAddForm(true)}
                  className="w-full border-2 border-dashed border-[#D7E7E4] hover:border-[#176B87] rounded-xl py-3 text-xs font-bold text-[#64748B] hover:text-[#176B87] flex items-center justify-center gap-1.5"
                >
                  <Plus className="w-4 h-4" /> Add New Ad
                </button>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdManagerPanel;

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Bell, ChevronRight } from 'lucide-react';
import { adminAPI } from '../api/api.exports';
import { getAlertMessage } from '../utils/adminAlertMessage';

type AlertRow = { id: string; message: string; severity: string; at: string | null };
type PanelState =
  | { status: 'loading' }
  | { status: 'ready'; rows: AlertRow[] }
  | { status: 'restricted' }
  | { status: 'error' };

const text = (value: unknown): string => (typeof value === 'string' ? value.trim() : '');

// Reads only the existing alerts source. It never fabricates entries: a failed
// request is "unavailable", a 403 is an access boundary, and an empty list is "no alerts".
export default function AdminAlertsPanel() {
  const [state, setState] = useState<PanelState>({ status: 'loading' });

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const body: any = await (adminAPI as any).alerts({ limit: 4 });
        const list = Array.isArray(body?.alerts) ? body.alerts : Array.isArray(body?.data) ? body.data : Array.isArray(body) ? body : null;
        if (cancelled) return;
        if (!list) { setState({ status: 'error' }); return; }
        setState({
          status: 'ready',
          rows: list.slice(0, 4).map((a: any, index: number) => ({
            id: String(a?._id ?? a?.id ?? index),
            message: getAlertMessage(a),
            severity: text(a?.severity) || 'unspecified',
            at: text(a?.createdAt) || text(a?.timestamp) || null,
          })),
        });
      } catch (err: any) {
        if (cancelled) return;
        setState(err?.response?.status === 403 ? { status: 'restricted' } : { status: 'error' });
      }
    })();
    return () => { cancelled = true; };
  }, []);

  return (
    <section className="kayad-command-panel kayad-command-rail-panel" aria-labelledby="right-rail-alerts-heading">
      <header><h2 id="right-rail-alerts-heading">System Alerts</h2><Link to="/admin/control-room">View All</Link></header>
      <div aria-live="polite">
        {state.status === 'loading' && <p className="kayad-command-empty">Loading alerts…</p>}
        {state.status === 'error' && <p className="kayad-command-empty">Alerts are unavailable right now. This is not a confirmation that there are none.</p>}
        {state.status === 'restricted' && <p className="kayad-command-empty">Alerts are not included in your role. This is an access boundary, not an outage.</p>}
        {state.status === 'ready' && state.rows.length === 0 && <p className="kayad-command-empty">No alerts were returned.</p>}
        {state.status === 'ready' && state.rows.length > 0 && (
          <ul className="kayad-command-alert-list">
            {state.rows.map((row) => (
              <li key={row.id}>
                <Bell size={14} aria-hidden="true" />
                <span><strong>{row.message}</strong><small>{row.severity}{row.at && !Number.isNaN(Date.parse(row.at)) ? ` · ${new Date(row.at).toLocaleString('en-KE', { timeZone: 'Africa/Nairobi', dateStyle: 'medium', timeStyle: 'short' })}` : ''}</small></span>
              </li>
            ))}
          </ul>
        )}
      </div>
      <Link className="kayad-command-rail-primary" to="/admin/control-room">Operations control room <ChevronRight size={14} aria-hidden="true" /></Link>
    </section>
  );
}

