import React, { useEffect, useState } from 'react';
import { X, Trash2, Plus, Eye, EyeOff, Loader2 } from 'lucide-react';
import { HeroSlide, HeroSlideInput, getAllHeroSlides, createHeroSlide, updateHeroSlide, deleteHeroSlide, HeroApiError } from '../../services/heroApi';

interface HeroEditorPanelProps {
  onClose: () => void;
}

const EMPTY_DRAFT: HeroSlideInput = {
  eyebrowText: '',
  headline: 'Drive Your Dream Today',
  subheadline: 'Discover quality vehicles across East Africa. Find the right car, make your move, and drive with confidence.',
  ctaPrimaryText: '',
  ctaPrimaryLink: '',
  ctaSecondaryText: '',
  ctaSecondaryLink: '',
  backgroundType: 'image',
  backgroundValue: 'https://commons.wikimedia.org/wiki/Special:FilePath/Nairobi%20skyline%20from%20Uhuru%20Park.jpg?width=2400',
  overlayColor: '#176B87',
  overlayOpacity: 40,
  displayMode: 'boxed',
  layout: 'four-corner',
  mediaConfig: {},
  sortOrder: 0,
};

/**
 * Real, backend-connected Hero Editor - same deliberate pattern as
 * AdManagerPanel.tsx (real, backend-persisted, not the localStorage-
 * only pattern used for home-page section-visibility toggles
 * elsewhere), since every real visitor must see the admin's hero
 * edits. Supports everything asked for directly: full text editing,
 * adding more than one slide (a real slider - the marketplace page
 * auto-rotates between visible slides), a boxed-vs-fullscreen display
 * mode per slide ("windowed" vs "fit to screen"), and a real,
 * layered background (a base image/color/gradient layer plus a
 * separate overlay color+opacity layer on top of it) - all editable
 * here with no code change ever needed.
 */
export const HeroEditorPanel: React.FC<HeroEditorPanelProps> = ({ onClose }) => {
  const [slides, setSlides] = useState<HeroSlide[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [savingId, setSavingId] = useState<string | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [draft, setDraft] = useState<HeroSlideInput>(EMPTY_DRAFT);
  const [creating, setCreating] = useState(false);

  const loadSlides = () => {
    setLoading(true);
    setError(null);
    getAllHeroSlides()
      .then(setSlides)
      .catch((err) => setError(err instanceof HeroApiError ? err.message : 'Could not load the hero card.'))
      .finally(() => setLoading(false));
  };

  useEffect(() => { loadSlides(); }, []);

  const handleFieldChange = (id: string, field: keyof HeroSlideInput | 'isVisible', value: string | number | boolean) => {
    setSlides((prev) => prev.map((s) => s.id === id ? { ...s, [field]: value } : s));
  };

  const handleMediaChange = (id: string, field: string, value: string) => {
    setSlides((prev) => prev.map((s) => s.id === id ? { ...s, mediaConfig: { ...(s.mediaConfig || {}), [field]: value } } : s));
  };

  const handleSave = async (slide: HeroSlide) => {
    setSavingId(slide.id);
    try {
      const updated = await updateHeroSlide(slide.id, {
        eyebrowText: slide.eyebrowText,
        headline: slide.headline,
        subheadline: slide.subheadline,
        ctaPrimaryText: slide.ctaPrimaryText,
        ctaPrimaryLink: slide.ctaPrimaryLink,
        ctaSecondaryText: slide.ctaSecondaryText,
        ctaSecondaryLink: slide.ctaSecondaryLink,
        backgroundType: slide.backgroundType,
        backgroundValue: slide.backgroundValue,
        overlayColor: slide.overlayColor,
        overlayOpacity: slide.overlayOpacity,
        displayMode: slide.displayMode,
        layout: slide.layout,
        mediaConfig: slide.mediaConfig,
        isVisible: slide.isVisible,
        sortOrder: slide.sortOrder,
      });
      setSlides((prev) => prev.map((s) => s.id === updated.id ? updated : s));
    } catch (err) {
      setError(err instanceof HeroApiError ? err.message : 'Could not save this slide.');
    } finally {
      setSavingId(null);
    }
  };

  const handleToggleVisible = async (slide: HeroSlide) => {
    setSavingId(slide.id);
    try {
      const updated = await updateHeroSlide(slide.id, { isVisible: !slide.isVisible });
      setSlides((prev) => prev.map((s) => s.id === updated.id ? updated : s));
    } catch (err) {
      setError(err instanceof HeroApiError ? err.message : 'Could not update visibility.');
    } finally {
      setSavingId(null);
    }
  };

  const handleDelete = async (slide: HeroSlide) => {
    if (!window.confirm(`Remove "${slide.headline}" permanently? This cannot be undone.`)) return;
    setSavingId(slide.id);
    try {
      await deleteHeroSlide(slide.id);
      setSlides((prev) => prev.filter((s) => s.id !== slide.id));
    } catch (err) {
      setError(err instanceof HeroApiError ? err.message : 'Could not remove this slide.');
      setSavingId(null);
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!draft.headline.trim()) return;
    setCreating(true);
    try {
      const created = await createHeroSlide(draft);
      setSlides((prev) => [...prev, created]);
      setDraft(EMPTY_DRAFT);
      setShowAddForm(false);
    } catch (err) {
      setError(err instanceof HeroApiError ? err.message : 'Could not create this slide.');
    } finally {
      setCreating(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-[#0A3340]/50 z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl w-full max-w-3xl max-h-[85vh] overflow-y-auto shadow-2xl">
        <div className="sticky top-0 bg-white border-b border-[#D7E7E4] px-5 py-4 flex items-center justify-between">
          <div>
            <h2 className="text-base font-bold text-[#0A3340]">Hero Editor</h2>
            <p className="text-xs text-[#64748B] mt-0.5">Edit the existing hero content, vehicle imagery, promotion copy, and presentation layout. All changes are persisted for every visitor.</p>
          </div>
          <button onClick={onClose} className="p-1.5 hover:bg-[#EEF7F5] rounded-lg">
            <X className="w-5 h-5 text-[#64748B]" />
          </button>
        </div>

        <div className="p-5 space-y-4">
          {error && (
            <div className="p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-800 font-semibold">
              {error}
            </div>
          )}

          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-5 h-5 text-[#94A3B8] animate-spin" />
            </div>
          ) : (
            <>
              {slides.length === 0 && (
                <p className="text-xs text-[#64748B] text-center py-4">
                  No real slides yet - the page shows a default hero until you add one here.
                </p>
              )}

              {slides.map((slide) => (
                <div key={slide.id} className="border border-[#D7E7E4] rounded-xl p-4 space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold text-[#0A3340]">Slide</span>
                    <div className="flex items-center gap-2">
                      <button
                        onClick={() => handleToggleVisible(slide)}
                        disabled={savingId === slide.id}
                        className={`p-1.5 rounded-lg ${slide.isVisible ? 'text-emerald-600 bg-emerald-50' : 'text-[#94A3B8] bg-[#EEF7F5]'}`}
                        title={slide.isVisible ? 'Visible on page' : 'Hidden from page'}
                      >
                        {slide.isVisible ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                      </button>
                      <button
                        onClick={() => handleDelete(slide)}
                        disabled={savingId === slide.id}
                        className="p-1.5 rounded-lg text-rose-500 hover:bg-rose-50"
                        title="Remove slide"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>

                  <input
                    value={slide.eyebrowText || ''}
                    onChange={(e) => handleFieldChange(slide.id, 'eyebrowText', e.target.value)}
                    placeholder="Eyebrow text (small label above the headline)"
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                  />
                  <input
                    value={slide.headline}
                    onChange={(e) => handleFieldChange(slide.id, 'headline', e.target.value)}
                    placeholder="Headline"
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-sm font-semibold"
                  />
                  <textarea
                    value={slide.subheadline || ''}
                    onChange={(e) => handleFieldChange(slide.id, 'subheadline', e.target.value)}
                    placeholder="Subheadline"
                    rows={2}
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                  />
                  <div className="grid grid-cols-2 gap-2">
                    <input
                      value={slide.ctaPrimaryText || ''}
                      onChange={(e) => handleFieldChange(slide.id, 'ctaPrimaryText', e.target.value)}
                      placeholder="Primary button text"
                      className="border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                    />
                    <input
                      value={slide.ctaPrimaryLink || ''}
                      onChange={(e) => handleFieldChange(slide.id, 'ctaPrimaryLink', e.target.value)}
                      placeholder="Primary button page (e.g. marketplace)"
                      className="border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                    />
                    <input
                      value={slide.ctaSecondaryText || ''}
                      onChange={(e) => handleFieldChange(slide.id, 'ctaSecondaryText', e.target.value)}
                      placeholder="Secondary button text"
                      className="border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                    />
                    <input
                      value={slide.ctaSecondaryLink || ''}
                      onChange={(e) => handleFieldChange(slide.id, 'ctaSecondaryLink', e.target.value)}
                      placeholder="Secondary button page"
                      className="border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                    />
                  </div>

                  <div className="flex items-center gap-4 flex-wrap pt-2 border-t border-[#D7E7E4]">
                    <label className="flex items-center gap-2 text-xs text-[#64748B]">
                      Display
                      <select
                        value={slide.displayMode}
                        onChange={(e) => handleFieldChange(slide.id, 'displayMode', e.target.value)}
                        className="border border-[#D7E7E4] rounded-lg px-2 py-1"
                      >
                        <option value="boxed">Windowed (compact)</option>
                        <option value="fullscreen">Fit to screen</option>
                      </select>
                    </label>
                    <label className="flex items-center gap-2 text-xs text-[#64748B]">
                      Background
                      <select
                        value={slide.backgroundType}
                        onChange={(e) => handleFieldChange(slide.id, 'backgroundType', e.target.value)}
                        className="border border-[#D7E7E4] rounded-lg px-2 py-1"
                      >
                        <option value="gradient">Default gradient</option>
                        <option value="color">Solid color</option>
                        <option value="image">Image URL</option>
                      </select>
                    </label>
                  </div>

                  {slide.backgroundType === 'color' && (
                    <label className="flex items-center gap-2 text-xs text-[#64748B]">
                      Background color
                      <input
                        type="color"
                        value={slide.backgroundValue || '#0A3340'}
                        onChange={(e) => handleFieldChange(slide.id, 'backgroundValue', e.target.value)}
                        className="w-8 h-8 rounded border border-[#D7E7E4] cursor-pointer"
                      />
                    </label>
                  )}
                  {slide.backgroundType === 'image' && (
                    <input
                      value={slide.backgroundValue || ''}
                      onChange={(e) => handleFieldChange(slide.id, 'backgroundValue', e.target.value)}
                      placeholder="Background image URL"
                      className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                    />
                  )}

                  <div className="flex items-center gap-4 flex-wrap">
                    <label className="flex items-center gap-2 text-xs text-[#64748B]">
                      Overlay color
                      <input
                        type="color"
                        value={slide.overlayColor}
                        onChange={(e) => handleFieldChange(slide.id, 'overlayColor', e.target.value)}
                        className="w-8 h-8 rounded border border-[#D7E7E4] cursor-pointer"
                      />
                    </label>
                    <label className="flex items-center gap-2 text-xs text-[#64748B] flex-1 min-w-[160px]">
                      Overlay opacity (layer over the background)
                      <input
                        type="range"
                        min={0}
                        max={100}
                        value={slide.overlayOpacity}
                        onChange={(e) => handleFieldChange(slide.id, 'overlayOpacity', Number(e.target.value))}
                        className="flex-1"
                      />
                      <span className="w-8 text-right">{slide.overlayOpacity}%</span>
                    </label>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 border-t border-[#D7E7E4] pt-3">
                    <label className="flex flex-col gap-1 text-xs text-[#64748B]">
                      Hero layout
                      <select
                        value={slide.layout || 'four-corner'}
                        onChange={(e) => handleFieldChange(slide.id, 'layout', e.target.value)}
                        className="border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                      >
                        <option value="four-corner">Four-corner vehicle layout</option>
                        <option value="media-left">Vehicle media left</option>
                        <option value="media-right">Vehicle media right</option>
                        <option value="centered">Centered hero</option>
                      </select>
                    </label>
                    <div className="text-[11px] text-[#64748B] self-end">Use the same existing hero content fields for promotions, feature messages and calls to action; no new homepage modules are required.</div>
                  </div>

                  <div className="border-t border-[#D7E7E4] pt-3 space-y-2">
                    <div className="text-xs font-bold text-[#0A3340]">Vehicle imagery</div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                      {[
                        ['leftTopImage', 'leftTopLabel', 'Left top vehicle'],
                        ['leftBottomImage', 'leftBottomLabel', 'Left bottom vehicle'],
                        ['rightTopImage', 'rightTopLabel', 'Right top vehicle'],
                        ['rightBottomImage', 'rightBottomLabel', 'Right bottom vehicle'],
                      ].map(([imageKey, labelKey, label]) => (
                        <div key={imageKey} className="rounded-lg border border-[#D7E7E4] p-2 space-y-2">
                          <div className="text-[10px] font-bold uppercase tracking-wide text-[#94A3B8]">{label}</div>
                          <input
                            value={String((slide.mediaConfig as Record<string, string> | undefined)?.[imageKey] || '')}
                            onChange={(e) => handleMediaChange(slide.id, imageKey, e.target.value)}
                            placeholder="Image URL (https://...)"
                            className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                          />
                          <input
                            value={String((slide.mediaConfig as Record<string, string> | undefined)?.[labelKey] || '')}
                            onChange={(e) => handleMediaChange(slide.id, labelKey, e.target.value)}
                            placeholder="Vehicle label"
                            className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                          />
                        </div>
                      ))}
                    </div>
                  </div>

                  <button
                    onClick={() => handleSave(slide)}
                    disabled={savingId === slide.id}
                    className="bg-[#0A3340] hover:bg-[#12576D] text-white text-xs font-bold rounded-lg px-4 py-2 disabled:opacity-50"
                  >
                    {savingId === slide.id ? 'Saving…' : 'Save Changes'}
                  </button>
                </div>
              ))}

              {showAddForm ? (
                <form onSubmit={handleCreate} className="border-2 border-dashed border-[#176B87]/40 rounded-xl p-4 space-y-3">
                  <input
                    value={draft.headline}
                    onChange={(e) => setDraft((d) => ({ ...d, headline: e.target.value }))}
                    placeholder="Headline"
                    required
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-sm"
                  />
                  <input
                    value={draft.subheadline}
                    onChange={(e) => setDraft((d) => ({ ...d, subheadline: e.target.value }))}
                    placeholder="Subheadline"
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                  />
                  <div className="flex gap-2">
                    <button type="submit" disabled={creating} className="bg-[#176B87] hover:bg-[#12576D] text-white text-xs font-bold rounded-lg px-4 py-2 disabled:opacity-50">
                      {creating ? 'Creating…' : 'Add Slide'}
                    </button>
                    <button type="button" onClick={() => setShowAddForm(false)} className="text-xs font-semibold text-[#64748B] px-4 py-2">
                      Cancel
                    </button>
                  </div>
                </form>
              ) : (
                <button
                  onClick={() => setShowAddForm(true)}
                  className="w-full border-2 border-dashed border-[#D7E7E4] hover:border-[#176B87] rounded-xl py-3 text-xs font-bold text-[#64748B] hover:text-[#176B87] flex items-center justify-center gap-1.5"
                >
                  <Plus className="w-4 h-4" /> Add Slide
                </button>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default HeroEditorPanel;

import React, { useMemo, useState } from 'react';
import organizationApi, { type AccessRole, type Member, type OrgSummary, type TechTitle } from '../services/organizationApi';
import { ROLE_LABEL, ROLE_HELP, TITLE_LABEL, TITLES_FOR, invitableRoles, mayHaveBranch, needsBranch } from './orgAccess';
import { Loading, ErrorBox, Empty, Notice, Pill, field, btnPrimary, btnGhost, btnDanger, useLoader, useAction } from './orgUi';

const tone = (s: Member['status']) => (s === 'confirmed' ? 'ok' : s === 'pending' ? 'warn' : 'bad');
const RANK: Record<string, number> = { owner: 100, org_admin: 80, operations_manager: 60, branch_manager: 50, finance: 30, report_reviewer: 30, inspector: 20, technician: 20 };

export const TeamPanel: React.FC<{ org: OrgSummary }> = ({ org }) => {
  const me = org.you;
  const roles = invitableRoles(me.role);
  const members = useLoader(() => organizationApi.listMembers(org.id), [org.id]);
  const branches = useLoader(() => organizationApi.listBranches(org.id), [org.id]);
  const reloadAll = async () => { await Promise.all([members.reload(), branches.reload()]); };
  const { busy, msg, run } = useAction(reloadAll);
  const [inv, setInv] = useState<{ email: string; accessRole: AccessRole; title: TechTitle | ''; branchId: string }>({ email: '', accessRole: roles[roles.length > 3 ? 3 : 0] || 'inspector', title: '', branchId: me.role === 'branch_manager' ? me.branchId || '' : '' });
  const [act, setAct] = useState<{ id: string; kind: 'suspend' | 'revoke' | 'change' } | null>(null);
  const [why, setWhy] = useState('');
  const [chg, setChg] = useState<{ accessRole: AccessRole; branchId: string; title: TechTitle | '' }>({ accessRole: 'inspector', branchId: '', title: '' });
  const branchName = useMemo(() => new Map((branches.data?.branches ?? []).map((b) => [b.id, b.name])), [branches.data]);

  if (members.loading && !members.data) return <Loading label="Loading team…" />;
  if (members.error) return <ErrorBox error={members.error} what="the team" onRetry={members.reload} />;
  const list = members.data?.members ?? [];
  const activeBranches = (branches.data?.branches ?? []).filter((b) => b.status === 'active');
  const mayManage = (m: Member) => m.id !== me.staffId && (me.role === 'owner' || (me.role === 'org_admin' && RANK[m.accessRole] < 80) || (me.role === 'branch_manager' && ['inspector', 'technician'].includes(m.accessRole) && m.branchId === me.branchId));

  return (
    <section aria-labelledby="org-team" className="space-y-4">
      <div>
        <h2 id="org-team" className="text-lg font-bold text-[#0A3340]">Team</h2>
        <p className="text-sm text-[#64748B]">{me.role === 'branch_manager' ? 'People in your branch.' : 'Everyone who works for this organization. A person is only on the team after they accept an invitation.'}</p>
      </div>
      <Notice msg={msg} />
      {list.length === 0 ? <Empty title="No team members yet" hint={roles.length ? 'Invite a registered KAYAD user by email below.' : undefined} /> : (
        <ul className="space-y-2">
          {list.map((m) => (
            <li key={m.id} className="rounded-xl border border-[#D7E7E4] bg-white p-3 text-sm space-y-2">
              <div className="flex flex-wrap items-center gap-2">
                <strong className="break-words">{m.name || 'Team member'}</strong>
                <Pill>{ROLE_LABEL[m.accessRole]}</Pill>
                <Pill tone={tone(m.status)}>{m.status === 'pending' ? (m.awaiting === 'business' ? 'asked to join' : 'invited') : m.status}</Pill>
                <span className="text-xs text-[#64748B]">{m.branchId ? `Branch: ${branchName.get(m.branchId) || 'unknown'}` : 'All branches'}{m.accessRole === 'inspector' || m.accessRole === 'technician' ? ` · ${TITLE_LABEL[m.title] || m.title}` : ''}</span>
              </div>
              {m.status === 'pending' && m.invitationExpiresAt && <p className="text-xs text-[#64748B]">{new Date(m.invitationExpiresAt).getTime() < Date.now() ? 'Invitation expired.' : `Invitation expires ${new Date(m.invitationExpiresAt).toLocaleDateString()}.`}</p>}
              {m.reason && (m.status === 'suspended' || m.status === 'ended') && <p className="text-xs text-[#64748B]">Reason: {m.reason}</p>}
              {mayManage(m) && m.status !== 'ended' && act?.id !== m.id && (
                <div className="flex flex-wrap gap-2">
                  {m.status === 'pending' && m.awaiting === 'business' && <button type="button" className={btnPrimary} disabled={busy} onClick={() => void run(() => organizationApi.confirm(org.id, m.id), 'Team member confirmed.')}>Confirm</button>}
                  {m.status !== 'pending' && <button type="button" className={btnGhost} disabled={busy} onClick={() => { setAct({ id: m.id, kind: 'change' }); setChg({ accessRole: m.accessRole, branchId: m.branchId || '', title: m.title }); }}>Change role or branch</button>}
                  {m.status === 'confirmed' && <button type="button" className={btnGhost} disabled={busy} onClick={() => { setAct({ id: m.id, kind: 'suspend' }); setWhy(''); }}>Suspend</button>}
                  {m.status === 'suspended' && <button type="button" className={btnPrimary} disabled={busy} onClick={() => void run(() => organizationApi.setMemberStatus(org.id, m.id, 'reactivate'), 'Access restored.')}>Reactivate</button>}
                  <button type="button" className={btnDanger} disabled={busy} onClick={() => { setAct({ id: m.id, kind: 'revoke' }); setWhy(''); }}>{m.status === 'pending' ? 'Cancel invitation' : 'Remove from team'}</button>
                </div>
              )}
              {act?.id === m.id && act.kind !== 'change' && (
                <form className="space-y-2" onSubmit={(e) => { e.preventDefault(); void run(() => organizationApi.setMemberStatus(org.id, m.id, act.kind as 'suspend' | 'revoke', why), act.kind === 'suspend' ? 'Suspended. They lose access immediately.' : 'Removed. They lose access immediately and any pending assignments return to the queue.').then((ok) => ok && setAct(null)); }}>
                  <label className="text-xs font-bold" htmlFor={`tw-${m.id}`}>{act.kind === 'suspend' ? 'Reason for suspension' : 'Reason (kept in the audit log)'}</label>
                  <input id={`tw-${m.id}`} className={field} required={act.kind === 'suspend'} value={why} onChange={(e) => setWhy(e.target.value)} />
                  <div className="flex gap-2"><button type="submit" className={act.kind === 'revoke' ? btnDanger : btnPrimary} disabled={busy || (act.kind === 'suspend' && why.trim().length < 3)}>{act.kind === 'suspend' ? 'Suspend' : 'Remove'}</button><button type="button" className={btnGhost} onClick={() => setAct(null)}>Cancel</button></div>
                </form>
              )}
              {act?.id === m.id && act.kind === 'change' && (
                <form className="grid gap-2 sm:grid-cols-3" onSubmit={(e) => { e.preventDefault(); const body: Record<string, unknown> = {}; if (chg.accessRole !== m.accessRole) body.accessRole = chg.accessRole; if ((chg.branchId || null) !== (m.branchId || null)) body.branchId = chg.branchId || null; if (chg.title && chg.title !== m.title) body.title = chg.title; if (!Object.keys(body).length) { setAct(null); return; } void run(() => organizationApi.change(org.id, m.id, body), 'Updated. The change applies on their next request.').then((ok) => ok && setAct(null)); }}>
