// ============================================================
// KAYAD INSPECTION MARKETPLACE - BOOKING FLOW
// ============================================================

import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ArrowLeft,
  ArrowRight,
  Check,
  Calendar,
  Clock,
  MapPin,
  Car,
  User,
  CreditCard,
  FileText,
} from 'lucide-react';
import { inspectionApi } from '../services/api';
import { settleBookingPayment, InspectionPaymentError } from '../services/inspectionPayment';
import type {
  InspectionProvider,
  InspectionPackage,
  TimeSlot,
  InspectionType
} from '../types/inspection';
import { INSPECTION_TYPES } from '../types/inspection';

const KAYAD_COLORS = {
  lightNavy: '#12576D',
  warmBeige: '#EEF7F5',
  white: '#ffffff',
  emerald: '#13B8A6',
  mutedTerracotta: '#5AAFA4',
  softBlue: '#64748b',
};

interface BookingFlowProps {
  provider: InspectionProvider;
  /** Called only after the server reports the booking paid. `reference` is the server-issued booking reference. */
  onComplete?: (bookingId: string, reference?: string) => void;
  onCancel?: () => void;
}

const STEPS = [
  { id: 'vehicle', title: 'Vehicle Details', icon: Car },
  { id: 'package', title: 'Select Package', icon: FileText },
  { id: 'schedule', title: 'Schedule', icon: Calendar },
  { id: 'location', title: 'Location', icon: MapPin },
  { id: 'confirm', title: 'Confirm', icon: User },
  { id: 'payment', title: 'Payment', icon: CreditCard },
];

export default function BookingFlow({ provider, onComplete, onCancel }: BookingFlowProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [availableSlots, setAvailableSlots] = useState<TimeSlot[]>([]);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  // The booking created by the first submit. A payment retry must pay THIS booking:
  // creating another one collides with the slot the unpaid booking still holds.
  const createdBooking = useRef<{ id: string; reference?: string } | null>(null);
  const abortRef = useRef<AbortController | null>(null);
  useEffect(() => () => abortRef.current?.abort(), []);

  const [formData, setFormData] = useState({
    // Vehicle
    vehicleMake: '',
    vehicleModel: '',
    vehicleYear: new Date().getFullYear(),
    vehicleRegistration: '',
    vehicleVin: '',
    vehicleType: 'cars',

    // Package
    selectedPackage: null as InspectionPackage | null,
    inspectionType: '' as InspectionType | '',

    // Schedule
    selectedDate: '',
    selectedTime: '',
    selectedStaff: '',

    // Location
    isMobile: true,
    county: provider.location.county,
    town: provider.location.town,
    inspectionAddress: '',
    latitude: undefined as number | undefined,
    longitude: undefined as number | undefined,

    // Seller
    sellerName: '',
    sellerPhone: '',
    sellerIsDealer: false,

    // Customer
    customerName: '',
    customerEmail: '',
    customerPhone: '',
    notes: '',
  });

  // Fetch available slots when date changes
  useEffect(() => {
    if (formData.selectedDate && provider.id) {
      fetchSlots();
    }
  }, [formData.selectedDate, provider.id]);

  const fetchSlots = async () => {
    setLoading(true);
    try {
      const result = await inspectionApi.getAvailableSlots(provider.id, formData.selectedDate);
      setAvailableSlots(result.slots);
    } catch (error) {
      console.error('Failed to fetch slots:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleNext = () => {
    if (currentStep < STEPS.length - 1) {
      setCurrentStep(currentStep + 1);
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmit = async () => {
    if (loading) return;
    setErrorMessage(null);
    setLoading(true);
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    try {
      if (!createdBooking.current) {
        const booking = await inspectionApi.createBooking({
          packageId: formData.selectedPackage!.id,
          customerName: formData.customerName,
          customerEmail: formData.customerEmail,
          customerPhone: formData.customerPhone,
          vehicleMake: formData.vehicleMake,
          vehicleModel: formData.vehicleModel,
          vehicleYear: formData.vehicleYear,
          vehicleRegistration: formData.vehicleRegistration,
          vehicleVin: formData.vehicleVin,
          vehicleType: formData.vehicleType,
          county: formData.county,
          town: formData.town,
          inspectionAddress: formData.inspectionAddress,
          latitude: formData.latitude,
          longitude: formData.longitude,
          isMobile: formData.isMobile,
          sellerName: formData.sellerName,
          sellerPhone: formData.sellerPhone,
          sellerIsDealer: formData.sellerIsDealer,
          scheduledDate: formData.selectedDate,
          scheduledTime: formData.selectedTime,
          staffId: formData.selectedStaff,
          notes: formData.notes,
        });
        const raw = booking as unknown as { id: string; reference?: string; booking_reference?: string };
        createdBooking.current = { id: raw.id, reference: raw.reference || raw.booking_reference };
      }

      const { id, reference } = createdBooking.current;
      await settleBookingPayment(id, formData.customerPhone, { signal: controller.signal });
      onComplete?.(id, reference);
    } catch (error) {
      if (error instanceof InspectionPaymentError && error.kind === 'aborted') return;
      console.error('Booking failed:', error);
      const saved = createdBooking.current?.reference ? ` Reference ${createdBooking.current.reference}.` : '';
      setErrorMessage(
        error instanceof Error
          ? (error instanceof InspectionPaymentError && saved ? `${error.message}${saved} You can retry payment from this screen or from My inspections.` : error.message)
          : 'We could not complete the booking. Please try again.'
      );
    } finally {
      if (abortRef.current === controller) setLoading(false);
    }
  };

  const canProceed = () => {
    switch (currentStep) {
      case 0: // Vehicle
        return formData.vehicleMake && formData.vehicleModel && formData.vehicleYear;
      case 1: // Package
        return formData.selectedPackage;
      case 2: // Schedule
        return formData.selectedDate && formData.selectedTime;
      case 3: // Location
        return formData.inspectionAddress;
      case 4: // Confirm
        return formData.customerName && formData.customerEmail && formData.customerPhone;
      case 5: // Payment
        return Boolean(formData.customerPhone);
      default:
        return false;
    }
  };

  // This is a pre-booking estimate only. The server recomputes the canonical
  // package price + mobile fee when the booking is created.
  const totalPrice = formData.selectedPackage
    ? formData.selectedPackage.price + (formData.isMobile ? (provider.operatingModel.mobileFee || 0) : 0)
    : 0;

  return (
    <div className="min-h-screen" style={{ backgroundColor: KAYAD_COLORS.warmBeige }}>
      {/* Header */}
      <header
        className="sticky top-0 z-10 py-4 px-6 shadow-md"
        style={{ backgroundColor: KAYAD_COLORS.white }}
      >
        <div className="max-w-4xl mx-auto">
          <div className="flex items-center justify-between">
            <button
              onClick={onCancel}
              className="flex items-center gap-2"
              style={{ color: KAYAD_COLORS.softBlue }}
            >
              <ArrowLeft size={20} />
              Back
            </button>
            <h1
              className="text-lg font-semibold"
              style={{ color: KAYAD_COLORS.lightNavy }}
            >
              Book Inspection
            </h1>
            <div />
          </div>

          {/* Progress Steps */}
          <div className="flex items-center justify-between mt-4">
            {STEPS.map((step, index) => (
              <div key={step.id} className="flex items-center">
                <div
                  className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${
                    index < currentStep
                      ? 'text-white'
                      : index === currentStep
                        ? 'text-white'
                        : ''
                  }`}
                  style={{
                    backgroundColor:
                      index < currentStep
                        ? KAYAD_COLORS.emerald
                        : index === currentStep
                          ? KAYAD_COLORS.lightNavy
                          : KAYAD_COLORS.warmBeige,
                    color:
                      index < currentStep || index === currentStep
                        ? KAYAD_COLORS.white
                        : KAYAD_COLORS.softBlue,
                  }}
                >
                  {index < currentStep ? <Check size={16} /> : index + 1}
                </div>
                {index < STEPS.length - 1 && (
                  <div
                    className="w-8 h-0.5 mx-1"
                    style={{
                      backgroundColor:
                        index < currentStep
                          ? KAYAD_COLORS.emerald
                          : KAYAD_COLORS.warmBeige,
                    }}
                  />
                )}
              </div>
            ))}
          </div>
        </div>
      </header>

      {/* Content */}
      <main className="max-w-4xl mx-auto px-4 py-8">
        <AnimatePresence mode="wait">
          <motion.div
            key={currentStep}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            transition={{ duration: 0.2 }}
          >
            {/* Step Content */}
            {currentStep === 0 && (
              <VehicleStep
                formData={formData}
                onChange={setFormData}
              />
            )}
            {currentStep === 1 && (
              <PackageStep
                provider={provider}
                formData={formData}
                onChange={setFormData}
              />
            )}
            {currentStep === 2 && (
              <ScheduleStep
                availableSlots={availableSlots}
                loading={loading}
                formData={formData}
                onChange={setFormData}
              />
            )}
            {currentStep === 3 && (
              <LocationStep
                provider={provider}
                formData={formData}
                onChange={setFormData}
              />
            )}
            {currentStep === 4 && (
              <ConfirmStep
                provider={provider}
                formData={formData}
                totalPrice={totalPrice}
                onChange={setFormData}
              />
            )}
            {currentStep === 5 && (
              <PaymentStep
                totalPrice={totalPrice}
                loading={loading}
              />
            )}
          </motion.div>
        </AnimatePresence>

        {errorMessage && (
          <div role="alert" className="mt-6 rounded-xl border px-4 py-3 text-sm" style={{ borderColor: '#FECACA', backgroundColor: '#FEF2F2', color: '#991B1B' }}>
            {errorMessage}
          </div>
        )}

        {/* Footer */}
        <div className="flex justify-between mt-8 pt-6 border-t" style={{ borderColor: KAYAD_COLORS.warmBeige }}>
          <button
            onClick={handleBack}
            // Once the server has created the booking its details are fixed: a payment retry pays that
            // booking, so letting the customer edit earlier steps would show details that are not what is paid for.
            disabled={currentStep === 0 || loading || Boolean(createdBooking.current)}
            className="px-6 py-3 rounded-lg font-medium disabled:opacity-50 flex items-center gap-2"
            style={{
              backgroundColor: KAYAD_COLORS.white,
              color: KAYAD_COLORS.lightNavy
            }}
          >
            <ArrowLeft size={16} />
            Back
          </button>

          {currentStep < STEPS.length - 1 ? (
            <button
              onClick={handleNext}
              disabled={!canProceed()}
              className="px-6 py-3 rounded-lg font-medium disabled:opacity-50 flex items-center gap-2"
              style={{
                backgroundColor: canProceed() ? KAYAD_COLORS.emerald : KAYAD_COLORS.softBlue,
                color: KAYAD_COLORS.white
              }}
            >
              Continue
              <ArrowRight size={16} />
            </button>
          ) : (
            <button
              onClick={handleSubmit}
              disabled={loading}
              className="px-6 py-3 rounded-lg font-medium disabled:opacity-50 flex items-center gap-2"
              style={{
                backgroundColor: KAYAD_COLORS.emerald,
                color: KAYAD_COLORS.white
              }}
            >
              {loading ? 'Waiting for M-Pesa…' : createdBooking.current ? 'Retry payment' : `Pay KES ${totalPrice.toLocaleString()}`}
            </button>
          )}
        </div>
      </main>
    </div>
  );
}

// Step Components
function VehicleStep({ formData, onChange }: any) {
