import React, { useCallback, useEffect, useState } from 'react';
import { FileCheck, Loader2 } from 'lucide-react';
import { Button } from '../../components/ui';
import { Modal } from '../../components/ui/Modal';
import { inspectionApi } from '../InspectionMarketplace/services/api';
import type { InspectionReport } from '../InspectionMarketplace/types/inspection';
import { InspectionRecord, kayadReportView } from './inspectionJourney';

interface InspectionReportModalProps {
  record: InspectionRecord | null;
  onClose: () => void;
}

const humanise = (value: string) => value.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ').replace(/^\w/, (c) => c.toUpperCase());

const Fact: React.FC<{ label: string; value?: React.ReactNode }> = ({ label, value }) => (
  <div className="flex justify-between gap-4 text-sm">
    <dt className="text-[#64748B]">{label}</dt>
    <dd className="font-semibold text-[#0A3340] text-right">{value ?? <span className="text-[#94A3B8] font-medium">Not provided</span>}</dd>
  </div>
);

const ScoreBlock: React.FC<{ score?: number; condition?: string }> = ({ score, condition }) => (
  <div className="rounded-2xl bg-[#176B87] text-white p-5 flex items-center justify-between gap-4">
    <div>
      <p className="text-[10px] font-bold uppercase tracking-wider text-[#DDF4F0]">Overall score</p>
      <p className="text-3xl font-black font-mono text-[#B8EEE7]">{score !== undefined ? `${score}/100` : 'Not recorded'}</p>
    </div>
    <div className="text-right">
      <p className="text-[10px] font-bold uppercase tracking-wider text-[#DDF4F0]">Condition</p>
      <p className="text-base font-bold">{condition || 'Not recorded'}</p>
    </div>
  </div>
);

export const InspectionReportModal: React.FC<InspectionReportModalProps> = ({ record, onClose }) => {
  const [provider, setProvider] = useState<InspectionReport | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const providerReportId = record?.report?.kind === 'provider' ? record.report.reportId : null;

  const load = useCallback(async () => {
    if (!providerReportId) return;
    setLoading(true);
    setError(null);
    try {
      setProvider(await inspectionApi.getReport(providerReportId));
    } catch {
      setProvider(null);
      setError('This report could not be loaded. It is only available to the customer who booked the inspection.');
    } finally {
      setLoading(false);
    }
  }, [providerReportId]);

  useEffect(() => {
    setProvider(null);
    void load();
  }, [load]);

  if (!record || !record.report) return null;

  return (
    <Modal isOpen onClose={onClose} title={`Inspection report — ${record.vehicleTitle}`} size="xl">
      {record.report.kind === 'kayad' ? (
        <KayadReport record={record} />
      ) : loading ? (
        <p role="status" className="flex items-center gap-2 text-sm text-[#64748B] py-8 justify-center"><Loader2 className="w-4 h-4 animate-spin" aria-hidden="true" /> Loading your report…</p>
      ) : error ? (
        <div role="alert" className="space-y-3 py-4 text-center">
          <p className="text-sm text-rose-700">{error}</p>
          <Button variant="secondary" size="sm" onClick={() => void load()}>Try again</Button>
        </div>
      ) : provider ? (
        <ProviderReport report={provider} />
      ) : null}
      <div className="flex justify-end pt-5 mt-5 border-t border-[#D7E7E4]">
        <Button variant="secondary" onClick={onClose}>Close report</Button>
      </div>
    </Modal>
  );
};

const KayadReport: React.FC<{ record: InspectionRecord }> = ({ record }) => {
  if (record.report?.kind !== 'kayad') return null;
  const view = kayadReportView(record.report.order);
  return (
    <div className="space-y-5">
      <ScoreBlock score={view.score} condition={view.conditionRating} />
      <dl className="space-y-2 rounded-xl border border-[#D7E7E4] bg-[#F6FAF9] p-4">
        <Fact label="Order reference" value={<span className="font-mono break-all">{view.reference}</span>} />
        <Fact label="Inspector" value={view.inspectorName} />
        <Fact label="Carried out by" value={view.businessName} />
        <Fact label="Completed" value={view.completedOn} />
      </dl>
      <section aria-labelledby="kayad-report-notes" className="space-y-1.5">
        <h3 id="kayad-report-notes" className="text-xs font-bold uppercase tracking-wider text-[#176B87]">Inspector’s notes</h3>
        <p className="text-sm text-[#12576D] leading-relaxed rounded-xl border border-[#D7E7E4] bg-white p-4 whitespace-pre-line">{view.notes || 'The inspector did not leave notes on this report.'}</p>
      </section>
      {view.checklist.length > 0 && (
        <section aria-labelledby="kayad-report-checklist" className="space-y-1.5">
          <h3 id="kayad-report-checklist" className="text-xs font-bold uppercase tracking-wider text-[#176B87]">Checklist ({view.checklist.length})</h3>
          <ul className="divide-y divide-[#D7E7E4] rounded-xl border border-[#D7E7E4] bg-white text-sm">
            {view.checklist.map((item, i) => (
              <li key={`${item.label}-${i}`} className="flex justify-between gap-3 px-4 py-2.5"><span className="text-[#12576D]">{item.label}</span>{item.result && <span className="font-semibold text-[#0A3340]">{item.result}</span>}</li>
            ))}
          </ul>
        </section>
      )}
      {view.photos.length > 0 && (
        <section aria-labelledby="kayad-report-photos" className="space-y-1.5">
          <h3 id="kayad-report-photos" className="text-xs font-bold uppercase tracking-wider text-[#176B87]">Inspection photos ({view.photos.length})</h3>
          <ul className="grid grid-cols-2 sm:grid-cols-3 gap-2">
            {view.photos.map((url, i) => (
              <li key={url}><a href={url} target="_blank" rel="noopener noreferrer"><img src={url} loading="lazy" alt={`Inspection photo ${i + 1} of ${record.vehicleTitle}`} className="aspect-[4/3] w-full rounded-lg object-cover border border-[#D7E7E4]" /></a></li>
            ))}
          </ul>
        </section>
      )}
      <p className="text-xs text-[#64748B] flex items-start gap-1.5"><FileCheck className="w-3.5 h-3.5 shrink-0 mt-0.5" aria-hidden="true" />This report shows only what the inspector submitted to KAYAD. Items that were not recorded are not shown.</p>
    </div>
  );
};

const ProviderReport: React.FC<{ report: InspectionReport }> = ({ report }) => {
  const scores = Object.entries(report.categoryScores || {}).filter(([, v]) => typeof v === 'number' && Number.isFinite(v as number));
  const critical = Array.isArray(report.criticalIssues) ? report.criticalIssues : [];
  const recommendations = Array.isArray(report.recommendations) ? report.recommendations : [];
  return (
    <div className="space-y-5">
      <ScoreBlock score={typeof report.overallScore === 'number' ? Number(report.overallScore) : undefined} condition={report.overallCondition ? humanise(String(report.overallCondition)) : undefined} />
      <dl className="space-y-2 rounded-xl border border-[#D7E7E4] bg-[#F6FAF9] p-4">
        <Fact label="Report number" value={<span className="font-mono">{report.reportNumber}</span>} />
        <Fact label="Provider" value={report.provider?.name} />
        <Fact label="Inspector" value={report.inspector?.name} />
        <Fact label="Package" value={report.package?.name} />
        <Fact label="Inspection date" value={report.inspectionDate ? new Date(report.inspectionDate).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : undefined} />
      </dl>
      {report.executiveSummary && (
        <section aria-labelledby="provider-report-summary" className="space-y-1.5">
          <h3 id="provider-report-summary" className="text-xs font-bold uppercase tracking-wider text-[#176B87]">Summary</h3>
          <p className="text-sm text-[#12576D] leading-relaxed rounded-xl border border-[#D7E7E4] bg-white p-4 whitespace-pre-line">{report.executiveSummary}</p>
        </section>
      )}
      {critical.length > 0 && (
        <section aria-labelledby="provider-report-critical" className="space-y-1.5">
          <h3 id="provider-report-critical" className="text-xs font-bold uppercase tracking-wider text-rose-700">Critical issues ({critical.length})</h3>
          <ul className="space-y-2">
            {critical.map((issue, i) => (
              <li key={i} className="rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm text-rose-900"><strong>{issue.category}{issue.item ? ` — ${issue.item}` : ''}.</strong> {issue.description}</li>
            ))}
          </ul>
        </section>
      )}
      {scores.length > 0 && (
        <section aria-labelledby="provider-report-scores" className="space-y-1.5">
          <h3 id="provider-report-scores" className="text-xs font-bold uppercase tracking-wider text-[#176B87]">Scores by area</h3>
          <ul className="grid sm:grid-cols-2 gap-x-6 gap-y-1 rounded-xl border border-[#D7E7E4] bg-white p-4 text-sm">
            {scores.map(([area, value]) => (
              <li key={area} className="flex justify-between gap-3"><span className="text-[#64748B]">{humanise(area)}</span><span className="font-semibold text-[#0A3340]">{String(value)}/100</span></li>
            ))}
          </ul>
        </section>
      )}
      {recommendations.length > 0 && (
        <section aria-labelledby="provider-report-recs" className="space-y-1.5">
          <h3 id="provider-report-recs" className="text-xs font-bold uppercase tracking-wider text-[#176B87]">Recommendations</h3>
          <ul className="list-disc pl-5 text-sm text-[#12576D] space-y-1">{recommendations.map((r, i) => <li key={i}>{r}</li>)}</ul>
        </section>
      )}
      {report.pdfUrl && (
        <p><a className="text-sm font-bold text-[#12576d] underline underline-offset-2" href={`/api/inspection/reports/${encodeURIComponent(report.id)}/pdf`} target="_blank" rel="noopener noreferrer">Download PDF report</a></p>
      )}
    </div>
  );
};

export default InspectionReportModal;

import React, { useEffect, useId, useRef, useState } from 'react';
import { BriefcaseBusiness, CheckCircle2 } from 'lucide-react';
import { Button } from '../../components/ui';
import { Modal } from '../../components/ui/Modal';
import { inspectionApi, automotiveApi } from '../InspectionMarketplace/services/api';
import type { ServiceTaxonomy } from '../InspectionMarketplace/types/inspection';
import { isPlausiblePhone } from './inspectionJourney';

const APPLY_PATH = '/?nav=inspections&action=apply-provider';

interface Props {
  isOpen: boolean;
  signedIn: boolean;
  onClose: () => void;
  onOpenAuth?: () => void;
  onOpenRegister?: (intent: string, next: string) => void;
}

const fieldClass =
  'w-full px-3.5 py-3 bg-[#F6FAF9] text-[#0A3340] placeholder-[#91CEC5] border border-[#D7E7E4] rounded-xl text-sm font-medium focus:outline-none focus:ring-2 focus:ring-[#176B87] focus:bg-white';

/** Provider application: authenticated, reviewed by KAYAD, grants no access by itself. */
export const ProviderApplicationModal: React.FC<Props> = ({ isOpen, signedIn, onClose, onOpenAuth, onOpenRegister }) => {
  const uid = useId();
  const [form, setForm] = useState({ companyName: '', phone: '', county: '', town: '', address: '' });
  const [businessType, setBusinessType] = useState<'individual_inspector' | 'garage_business'>('individual_inspector');
  const [hasWorkshop, setHasWorkshop] = useState(false);
  const [offersMobile, setOffersMobile] = useState(false);
  const [chosen, setChosen] = useState<string[]>([]);
  const [taxonomy, setTaxonomy] = useState<ServiceTaxonomy | null>(null);
  const [taxonomyError, setTaxonomyError] = useState(false);
  const [partial, setPartial] = useState<string | null>(null);
  const [touched, setTouched] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);
  const inFlight = useRef(false);

  useEffect(() => {
    if (!isOpen || taxonomy) return;
    let alive = true;
    automotiveApi.getServiceTaxonomy().then((t) => { if (alive) setTaxonomy(t); }).catch(() => { if (alive) setTaxonomyError(true); });
    return () => { alive = false; };
  }, [isOpen, taxonomy]);

  const set = (key: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement>) => setForm((v) => ({ ...v, [key]: e.target.value }));
  const phoneInvalid = touched && !isPlausiblePhone(form.phone);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (inFlight.current) return;
    setTouched(true);
    if (businessType === 'garage_business' && !form.companyName.trim()) { setError('Enter the registered business or trading name for a garage application.'); return; }
    if (!isPlausiblePhone(form.phone)) return;
    inFlight.current = true;
    setSubmitting(true);
    setError(null);
    try {
      const result = (await inspectionApi.registerProvider({
        companyName: form.companyName.trim() || undefined,
        businessType,
        phone: form.phone.trim(),
        country: 'Kenya',
        county: form.county.trim() || undefined,
        town: form.town.trim() || undefined,
        address: form.address.trim() || undefined,
        hasWorkshop,
        offersMobile,
      })) as unknown;
      // The registration call returns the business id. Services are then declared against the canonical taxonomy.
      const providerId = typeof result === 'string' ? result : (result as { id?: string; providerId?: string } | null)?.id || (result as { providerId?: string } | null)?.providerId;
      const failed: string[] = [];
      if (providerId) {
        for (const code of chosen) {
          try { await automotiveApi.declareCapability(providerId, { category: code, allMakes: true, travelsToCustomer: offersMobile }); }
          catch { failed.push(taxonomy?.categories.find((c) => c.code === code)?.label || code); }
        }
      } else if (chosen.length) {
        failed.push(...chosen);
      }
      if (failed.length) setPartial(`Your application was submitted, but these services could not be recorded yet: ${failed.join(', ')}. You can add them again once you are signed in to your business.`);
      const serverMessage = result && typeof result === 'object' ? (result as { message?: unknown }).message : undefined;
      setDone(typeof serverMessage === 'string' && serverMessage ? serverMessage : 'Your provider application was submitted to KAYAD for review.');
    } catch (err) {
      setError('The application could not be submitted. Check your connection and try again. If the problem continues, contact KAYAD support.');
    } finally {
      inFlight.current = false;
      setSubmitting(false);
    }
  };

  const text = (key: keyof typeof form, label: string, extra: Partial<React.InputHTMLAttributes<HTMLInputElement>> = {}) => (
    <div className="space-y-1.5">
      <label htmlFor={`${uid}-${key}`} className="text-xs font-bold text-[#64748B] block">{label}</label>
      <input id={`${uid}-${key}`} className={fieldClass} value={form[key]} onChange={set(key)} disabled={submitting} {...extra} />
    </div>
  );

  return (
    <Modal isOpen={isOpen} onClose={() => { if (!submitting) onClose(); }} title="Apply as an inspection provider" size="lg">
      {!signedIn ? (
        <div className="kayad-provider-onboarding py-4 text-center space-y-4">
          <BriefcaseBusiness className="w-8 h-8 mx-auto text-[#176B87]" aria-hidden="true" />
          <p className="text-sm text-[#64748B] max-w-md mx-auto">Start with your KAYAD account, confirm your email, then return here to share your business details and services. KAYAD reviews your application before any provider access is granted.</p>
          <ol className="kayad-onboarding-steps max-w-md mx-auto grid grid-cols-3 gap-2 text-left" aria-label="Provider onboarding steps"><li><span>1</span><strong>Account</strong><small>Sign in or register</small></li><li><span>2</span><strong>Business</strong><small>Contact and services</small></li><li><span>3</span><strong>Review</strong><small>KAYAD checks details</small></li></ol>
          <div className="flex flex-wrap justify-center gap-2">
            <Button variant="primary" className="min-h-[44px]" onClick={onOpenAuth}>Sign in to apply</Button>
            {onOpenRegister && <Button variant="outline" className="min-h-[44px]" onClick={() => onOpenRegister('provider', APPLY_PATH)}>Create a business account</Button>}
          </div>
        </div>
      ) : done ? (
        <div role="status" className="py-4 text-center space-y-3">
          <CheckCircle2 className="w-10 h-10 mx-auto text-[#13B8A6]" aria-hidden="true" />
          <p className="text-sm text-[#12576D]">{done}</p>
          {chosen.length > 0 && !partial && <p className="text-xs text-[#64748B]">The services you chose are recorded as declared, not verified. KAYAD verifies each one separately.</p>}
          {partial && <p role="alert" className="text-xs text-[#0A3340]">{partial}</p>}
          <p className="text-xs text-[#64748B]">Submitting an application does not grant provider access. KAYAD decides the outcome.</p>
          <Button variant="primary" onClick={onClose}>Close</Button>
        </div>
      ) : (
        <form onSubmit={submit} noValidate className="kayad-provider-application-form space-y-4" aria-busy={submitting}>
          <ol className="kayad-onboarding-steps grid grid-cols-3 gap-2 text-left" aria-label="Application progress"><li className="is-current"><span>1</span><strong>Business details</strong><small>Contact and location</small></li><li><span>2</span><strong>Services</strong><small>What you offer</small></li><li><span>3</span><strong>Review</strong><small>Checked by KAYAD</small></li></ol>
          <p className="rounded-xl bg-[#F5F8F8] border border-[#D7E7E4] p-3.5 text-xs text-[#64748B]">Choose the provider account that fits how you operate. A garage application represents the business; branch and staff access must be configured through authorized business controls. Submitting an application does not grant provider access; KAYAD reviews it and decides.</p>
          <fieldset className="space-y-2" disabled={submitting}>
            <legend className="text-xs font-bold text-[#64748B]">Provider account type</legend>
            <div className="grid sm:grid-cols-2 gap-3">
              <label className={`flex cursor-pointer items-start gap-3 rounded-xl border p-4 transition-colors ${businessType === 'individual_inspector' ? 'border-[#176B87] bg-[#F3FAF9] ring-1 ring-[#176B87]' : 'border-[#D7E7E4] bg-white'}`}>
                <input type="radio" name="providerBusinessType" value="individual_inspector" className="mt-1 accent-[#176B87]" checked={businessType === 'individual_inspector'} onChange={() => setBusinessType('individual_inspector')} />
                <span><strong className="block text-sm text-[#0A3340]">Independent inspector</strong><span className="mt-1 block text-xs text-[#64748B]">For an individual inspector operating under their own provider profile.</span></span>
              </label>
              <label className={`flex cursor-pointer items-start gap-3 rounded-xl border p-4 transition-colors ${businessType === 'garage_business' ? 'border-[#176B87] bg-[#F3FAF9] ring-1 ring-[#176B87]' : 'border-[#D7E7E4] bg-white'}`}>
                <input type="radio" name="providerBusinessType" value="garage_business" className="mt-1 accent-[#176B87]" checked={businessType === 'garage_business'} onChange={() => setBusinessType('garage_business')} />
                <span><strong className="block text-sm text-[#0A3340]">Registered garage / workshop</strong><span className="mt-1 block text-xs text-[#64748B]">For a business that needs centralized ownership and may operate multiple locations.</span></span>
              </label>
            </div>
            {businessType === 'garage_business' && <p className="rounded-lg border border-[#B8E3DC] bg-[#F0FBF8] p-3 text-xs text-[#12576D]">Apply once for the business identity. Branches, staff memberships and branch-specific permissions require authorized setup; this application does not create extra accounts or grant staff access.</p>}
          </fieldset>
          <div className="grid sm:grid-cols-2 gap-3">
            {text('companyName', businessType === 'garage_business' ? 'Registered business / trading name' : 'Your name / trading name', { autoComplete: 'organization', required: businessType === 'garage_business' })}
            <div className="space-y-1.5">
              <label htmlFor={`${uid}-phone`} className="text-xs font-bold text-[#64748B] block">Contact phone</label>
              <input
                id={`${uid}-phone`} type="tel" inputMode="tel" autoComplete="tel" required className={`${fieldClass} ${phoneInvalid ? 'border-rose-400' : ''}`}
                value={form.phone} onChange={set('phone')} onBlur={() => setTouched(true)} disabled={submitting} aria-required="true"
                aria-invalid={phoneInvalid || undefined} aria-describedby={phoneInvalid ? `${uid}-phone-error` : undefined}
              />
              {phoneInvalid && <p id={`${uid}-phone-error`} className="text-xs font-semibold text-rose-600">Enter a valid phone number (9–15 digits).</p>}
            </div>
            {text('county', 'County')}
            {text('town', 'Town / city')}
          </div>
          {text('address', 'Business / workshop address', { autoComplete: 'street-address' })}
          <fieldset className="space-y-2" disabled={submitting}>
            <legend className="text-xs font-bold text-[#64748B]">Services you offer</legend>
            <p className="text-xs text-[#64748B]">These are your claims. KAYAD verifies each service separately from evidence you provide; until then it is shown as “declared”.</p>
            {taxonomyError && <p role="alert" className="text-xs text-rose-700">The service list could not be loaded. You can submit now and add services later.</p>}
            <div className="grid sm:grid-cols-2 gap-1">
              {(taxonomy?.categories || []).map((c) => (
                <label key={c.code} className="flex items-start gap-2 text-sm min-h-[44px] items-center">
                  <input type="checkbox" className="w-4 h-4 accent-[#176B87]" checked={chosen.includes(c.code)} onChange={(e) => setChosen((v) => (e.target.checked ? [...v, c.code] : v.filter((x) => x !== c.code)))} />
                  <span>{c.label}{c.highRisk ? ' (needs evidence)' : ''}</span>
                </label>
              ))}
            </div>
          </fieldset>
          <fieldset className="space-y-1" disabled={submitting}>
            <legend className="text-xs font-bold text-[#64748B]">How you work</legend>
            <label className="flex items-center gap-2 text-sm min-h-[44px]"><input type="checkbox" className="w-4 h-4 accent-[#176B87]" checked={hasWorkshop} onChange={(e) => setHasWorkshop(e.target.checked)} /> I have a workshop or premises customers can visit</label>
            <label className="flex items-center gap-2 text-sm min-h-[44px]"><input type="checkbox" className="w-4 h-4 accent-[#176B87]" checked={offersMobile} onChange={(e) => setOffersMobile(e.target.checked)} /> I travel to the vehicle</label>
            {businessType === 'individual_inspector' && !hasWorkshop && <p className="text-xs text-[#64748B]">No premises? That is fine. KAYAD has an evidence-based route for legitimate businesses without customer-facing premises; you will be asked for a registration or tax number and supporting documents.</p>}
          </fieldset>
          {error && <p role="alert" className="rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm text-rose-800">{error}</p>}
          <div className="flex flex-col-reverse sm:flex-row sm:justify-end gap-3 pt-2 border-t border-[#D7E7E4]">
            <Button type="button" variant="secondary" onClick={onClose} disabled={submitting}>Cancel</Button>
            <Button type="submit" variant="primary" disabled={submitting}>{submitting ? 'Submitting…' : 'Submit application'}</Button>
          </div>
        </form>
      )}
    </Modal>
  );
};

export default ProviderApplicationModal;

