              viewMode="account"
              initialTab={initialInspectionTab}
              vehicles={[]}
              user={user}
              onOpenAuth={onOpenAuth}
              onOpenInspectionMarketplace={() => onNavigate?.('inspections')}
            />
          </section>
        </>
      )}
    </div>
  );
}

