                              <span className="inline-flex items-center gap-1 text-[9px] font-black uppercase tracking-wide px-2 py-1 rounded-full text-white shadow-sm bg-navy-900">
                                <Lock className="w-2.5 h-2.5" />Escrow
                              </span>
