                <label className="block text-[11px] font-bold uppercase tracking-wide text-[#94A3B8] mb-2">To year</label>
                <input type="number" value={maxYear === 2026 ? '' : maxYear} onChange={(e) => setMaxYear(Number(e.target.value) || 2026)} placeholder="2026" className="w-full border border-[#D7E7E4] rounded-xl px-3 py-2.5 text-sm bg-[#F6FAF9]" />
              </div>
            </div>
            <div>
              <label className="block text-[11px] font-bold uppercase tracking-wide text-[#94A3B8] mb-2">Body style</label>
              <select aria-label="Mobile body style filter" value={selectedBodyStyle} onChange={(e) => setSelectedBodyStyle(e.target.value)} className="w-full border border-[#D7E7E4] rounded-xl px-3 py-2.5 text-sm bg-[#F6FAF9]">
                {bodyStyles.map((b) => <option key={b} value={b}>{b === 'All' ? 'All Body Styles' : b}</option>)}
              </select>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[11px] font-bold uppercase tracking-wide text-[#94A3B8] mb-2">Fuel type</label>
                <select aria-label="Mobile fuel filter" value={selectedFuel} onChange={(e) => setSelectedFuel(e.target.value)} className="w-full border border-[#D7E7E4] rounded-xl px-3 py-2.5 text-sm bg-[#F6FAF9]">
                  {fuelTypes.map((f) => <option key={f} value={f}>{f === 'All' ? 'All Fuel Types' : f}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-[11px] font-bold uppercase tracking-wide text-[#94A3B8] mb-2">Transmission</label>
                <select aria-label="Mobile transmission filter" value={selectedTransmission} onChange={(e) => setSelectedTransmission(e.target.value)} className="w-full border border-[#D7E7E4] rounded-xl px-3 py-2.5 text-sm bg-[#F6FAF9]">
                  {transmissionOptions.map((t) => <option key={t} value={t}>{t === 'All' ? 'All Transmissions' : t}</option>)}
                </select>
              </div>
            </div>
            <div>
              <label className="block text-[11px] font-bold uppercase tracking-wide text-[#94A3B8] mb-2">Seller type</label>
              <select aria-label="Mobile seller type filter" value={selectedSellerType} onChange={(e) => setSelectedSellerType(e.target.value)} className="w-full border border-[#D7E7E4] rounded-xl px-3 py-2.5 text-sm bg-[#F6FAF9]">
                {sellerTypeOptions.map((s) => <option key={s} value={s}>{s === 'All' ? 'All Sellers' : s}</option>)}
              </select>
            </div>
            <label className="flex items-center gap-3 rounded-xl border border-[#D7E7E4] bg-[#F6FAF9] px-3 py-3 text-sm font-semibold text-[#12576D]">
              <input type="checkbox" checked={onlyAuction} onChange={(e) => setOnlyAuction(e.target.checked)} className="accent-navy-600 w-4 h-4" />
              <span><span className="block text-xs font-bold text-navy-900">Live auction listings</span><span className="block text-[10px] font-normal text-[#64748B] mt-0.5">Show vehicles currently available for bidding.</span></span>
            </label>
            <div className="flex gap-2 pt-2">
              <button onClick={resetFilters} className="flex-1 border border-[#D7E7E4] rounded-xl py-3 text-xs font-bold text-[#64748B] hover:bg-[#F6FAF9]">Reset all</button>
              <button onClick={() => setShowMobileFilterDrawer(false)} className="flex-1 bg-navy-900 hover:bg-navy-700 text-white rounded-xl py-3 text-xs font-bold">Show results</button>
            </div>
          </div>
        </div>
      )}

      {isAdmin && showAdminPanel && (
        <HomePageAdminPanel
          config={homeConfig}
          onUpdate={updateHomeConfig}
          onReset={resetHomeConfig}
          onClose={() => setShowAdminPanel(false)}
          adminUser={{ id: user!.id, name: user!.name }}
          featuredVehicles={featuredVehicles}
          heroFeaturedMode={heroFeaturedMode}
          heroFeaturedIds={heroFeaturedIds}
          heroPresentation={heroPresentation}
          heroCardContent={heroCardContent}
          onSaveHeroVehicleSelection={async (mode, ids) => {
            const currentResponse = await adminAPI.getConfig();
            const current = currentResponse?.config || currentResponse || {};
            await adminAPI.updateConfig({ ...current, heroFeaturedMode: mode, heroCarIds: ids });
            setHeroFeaturedMode(mode);
            setHeroFeaturedIds(ids);
          }}
          onSaveHeroPresentation={async (nextPresentation, nextCardContent) => {
            const currentResponse = await adminAPI.getConfig();
            const current = currentResponse?.config || currentResponse || {};
            await adminAPI.updateConfig({ ...current, heroPresentation: nextPresentation, heroCardContent: nextCardContent });
            setHeroPresentation(nextPresentation);
            setHeroCardContent(nextCardContent);
          }}
        />
      )}

      {isAdmin && showAdManager && (
        <AdManagerPanel onClose={() => setShowAdManager(false)} />
      )}

      {isAdmin && showHeroEditor && (
        <HeroEditorPanel onClose={() => { setShowHeroEditor(false); getVisibleHeroSlides().then((data) => { if (data.length > 0) setHeroSlides(data); }).catch(() => {}); }} />
      )}
    </div>
  );
};

export default VehicleMarketplace;

import { useState, useCallback } from 'react';

/**
 * Admin-editable configuration for the home/marketplace page. Deliberately
 * scoped, not a general page builder: lets an admin control the presentation
 * of the EXISTING marketplace sections, edit EXISTING trust-pillar text,
 * and choose from a small set of PRESET cool accent themes. Inventory
 * presentation controls below only change layout/density/sidebar defaults;
 * they never change vehicle data, filtering rules, or business logic.
 * A true "add/remove any component, any layout, any color" system would
 * be a genuinely different, much larger project (a real CMS/page-builder
 * with a component registry, a layout engine, and a full color-token
 * system) - this is an honest, working v1 within that broader direction,
 * not a stand-in that pretends to be the whole thing.
 *
 * Persisted to localStorage (not a backend call) - this frontend has no
 * connected backend to persist to yet (confirmed throughout this
 * project's history: all data is local mock state), and the explicit
 * requirement was "without breaking backend" - a purely client-side,
 * presentation-only config that never touches vehicle data, filtering,
 * or any business logic satisfies that regardless of whether backend
 * persistence exists later. When a real backend is connected, swapping
 * this hook's storage from localStorage to an API call is a contained,
 * one-file change - nothing that reads HomePageConfig elsewhere needs to
 * change.
 */
export interface HomePageConfig {
  sectionVisibility: {
    searchTrustCard: boolean;
    featuredPicks: boolean;
    savedSearchesAndInventoryHeader: boolean;
    sponsorCardsInGrid: boolean;
    recentlyViewed: boolean;
  };
  trustPillars: {
    escrow: { heading: string; subtext: string };
    inspection: { heading: string; subtext: string };
    auctions: { heading: string; subtext: string };
  };
  /** A small, fixed set of preset accent colors (not a free-form color
   * picker) - each maps to real, already-used Tailwind color tokens, so
   * every accent usage across the page (badges, buttons, highlights)
   * stays internally consistent rather than admins picking an arbitrary
   * hex that only some elements would pick up. */
  accentTheme: 'blue' | 'cyan' | 'slate';
  heroFallbackVehicles: Array<{
    id: string;
    make: string;
    model: string;
    year: number;
    fuelType: string;
    transmission: string;
    tagline: string;
    image: string;
  }>;
  inventoryLayout: {
    viewMode: 'grid' | 'list';
    columns: 3 | 4 | 5;
    showSidebar: boolean;
    cardDensity: 'compact' | 'standard' | 'comfortable';
  };
}

export const ACCENT_THEME_OPTIONS: { id: HomePageConfig['accentTheme']; label: string; swatch: string }[] = [
  { id: 'blue', label: 'Electric Blue', swatch: '#176B87' },
  { id: 'cyan', label: 'Cyan', swatch: '#13B8A6' },
  { id: 'slate', label: 'Slate Teal', swatch: '#176B87' },
];

/** Tailwind class fragments for each accent theme, keyed by the same
 * semantic roles used throughout the page (400/500/600 weight, text vs
 * background). Centralizing this mapping here means a page component
 * asks for `accentClasses.text400` etc. instead of hardcoding
 * the old warm accent token directly, so the whole page's accent actually changes
 * together when the admin picks a different theme. */
export const ACCENT_THEME_CLASSES: Record<HomePageConfig['accentTheme'], {
  text400: string; text500: string; text600: string;
  bg400: string; bg400Hover: string; border400: string; bg400Subtle: string;
}> = {
  blue: { text400: 'text-[#176B87]', text500: 'text-[#176B87]', text600: 'text-[#0A3340]', bg400: 'bg-[#176B87]', bg400Hover: 'hover:bg-[#0A3340]', border400: 'border-[#176B87]/25', bg400Subtle: 'bg-[#176B87]/10' },
  cyan: { text400: 'text-[#13B8A6]', text500: 'text-[#13B8A6]', text600: 'text-[#176B87]', bg400: 'bg-[#13B8A6]', bg400Hover: 'hover:bg-[#176B87]', border400: 'border-[#13B8A6]/25', bg400Subtle: 'bg-[#13B8A6]/10' },
  slate: { text400: 'text-[#176B87]', text500: 'text-[#176B87]', text600: 'text-[#12576D]', bg400: 'bg-[#176B87]', bg400Hover: 'hover:bg-[#12576D]', border400: 'border-[#176B87]/25', bg400Subtle: 'bg-[#176B87]/10' },
};

