              </p>
            </div>
            <button
              onClick={clearAll}
              className="flex items-center gap-2 px-4 py-2 bg-white/10 text-white text-sm font-medium rounded-lg hover:bg-white/20 transition-colors"
            >
              <Trash2 size={14} /> Clear All
            </button>
          </div>
        </div>
      </div>

      {/* Comparison Table */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl border border-[#D7E7E4] overflow-hidden">
          {/* Car Headers */}
          <div className="grid gap-4 p-4 border-b border-[#D7E7E4]"
