            <div className="flex items-center gap-2 font-sans text-sm font-semibold text-warm-500 uppercase tracking-wider">
              Body Type
            </div>
            {compareCars.map(car => car && (
              <div key={car.id} className="font-sans text-sm text-[#0A3340]">
                <span className="inline-flex px-3 py-1 bg-[#DDF4F0] rounded-full text-xs font-medium">
                  {car.type}
                </span>
              </div>
            ))}
            {Array.from({ length: 4 - compareCount }).map((_, idx) => (
              <div key={`empty-type-${idx}`} />
            ))}
          </div>

          {/* Badges Row */}
          <div className="grid gap-4 p-4 bg-[#F6FAF9]"
            style={{ gridTemplateColumns: `200px repeat(${compareCount}, 1fr)` }}>
            <div className="flex items-center gap-2 font-sans text-sm font-semibold text-warm-500 uppercase tracking-wider">
              Features
            </div>
            {compareCars.map(car => car && (
              <div key={car.id} className="flex flex-wrap gap-1">
                {car.badges.includes('escrow') && (
                  <span className="inline-flex px-2 py-0.5 bg-emerald-100 text-emerald-700 text-xs rounded-full">
                    Escrow
                  </span>
                )}
                {car.badges.includes('auction') && (
                  <span className="inline-flex px-2 py-0.5 bg-[#DDF4F0] text-[#12576D] text-xs rounded-full">
                    Auction
                  </span>
                )}
              </div>
            ))}
            {Array.from({ length: 4 - compareCount }).map((_, idx) => (
              <div key={`empty-badges-${idx}`} />
            ))}
          </div>
        </div>

        {/* Actions */}
        <div className="flex justify-between items-center mt-8">
          <button
            onClick={() => setPage('gallery')}
            className="flex items-center gap-2 text-warm-500 hover:text-[#0A3340] transition-colors"
          >
            <ArrowLeft size={16} /> Back to Gallery
          </button>
          <Link
            to="/gallery"
            className="btn-gold"
          >
            View All Vehicles <ArrowRight size={16} />
          </Link>
        </div>
      </div>
    </div>
  );
}

import { Link, useNavigate } from 'react-router-dom';
import { useEffect, useState } from 'react';

export default function NotFoundPage() {
  const navigate = useNavigate();
  const [count, setCount] = useState(5);

  useEffect(() => {
    const id = setInterval(() => {
      setCount(c => {
        if (c <= 1) { clearInterval(id); navigate('/'); }
        return c - 1;
      });
    }, 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <div className="page flex-center" style={{ flexDirection: 'column', textAlign: 'center', padding: 24 }}>
      <div className="gradient-text-404">404</div>
      <div style={{ fontSize: 48, marginBottom: 16 }}>🚗💨</div>
      <h2 style={{ marginBottom: 12 }}>This page drove off</h2>
      <p className="text-muted" style={{ maxWidth: 400, marginBottom: 8, fontSize: 15 }}>
        The page you're looking for doesn't exist, was removed, or took a wrong turn.
      </p>
      <p style={{ color: 'var(--text-dim)', fontSize: 13, marginBottom: 32 }}>
        Redirecting to home in {count}s...
      </p>
      <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', justifyContent: 'center' }}>
        <Link to="/" className="btn btn-gold">← Go Home</Link>
        <Link to="/" className="btn btn-outline">Browse Cars</Link>
        <button className="btn btn-ghost" onClick={() => navigate(-1)}>Go Back</button>
      </div>
    </div>
  );
}

