import '../styles/dashboard.css';
import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { carsAPI, escrowAPI } from '../api/api';
import { timeAgo } from '../utils/helpers';
import { EnterpriseCard, EnterpriseKPI, EnterpriseTimeline, EnterpriseQuickActions, EnterpriseTable, EnterpriseMetricRow, EnterpriseStatus, DashboardHeader } from '../components/enterprise/EnterpriseDashboard';

export default function PrivateSellerDashboard() {
  const { user } = useAuth();
  const { toast } = useToast();

  const [listings, setListings] = useState([]);
  const [escrows, setEscrows] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [listingsRes, escrowsRes] = await Promise.all([
        carsAPI.list({ seller: user?._id, limit: 20 }),
        escrowAPI.mine(),
      ]);
      const carList = listingsRes.cars || listingsRes.data || [];
      const escrowList = escrowsRes.escrows || [];
      setListings(carList);
      setEscrows(escrowList);

      const activeListings = carList.filter(l => l.status === 'active' || !l.status).length;
      const soldListings = carList.filter(l => l.status === 'sold').length;
      const totalViews = carList.reduce((sum, l) => sum + (l.views || 0), 0);
      const totalInquiries = carList.reduce((sum, l) => sum + (l.inquiries || 0), 0);

      setStats({
        activeListings,
        soldListings,
        totalViews,
        totalInquiries,
        pendingEscrows: escrowList.filter(e => e.status === 'pending').length,
        completedEscrows: escrowList.filter(e => e.status === 'completed').length,
      });
    } catch (err) {
      let errorMessage = 'Could not load dashboard data';
      if (err.code === 'ERR_NETWORK' || err.message?.includes('Network Error')) errorMessage = 'Network error. Please check your connection.';
      else if (err.response?.status >= 500) errorMessage = 'Server error. Please try again later.';
      toast(errorMessage, 'error');
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <div className="page loading-center"><div className="spinner" /></div>;

  const totalRevenue = escrows.reduce((sum, e) => sum + (e.amount || 0), 0);
  const statusColor = (status) => status === 'sold' ? '#22c55e' : status === 'active' ? '#176B87' : 'rgba(255,255,255,0.3)';

  return (
    <div className="page dashboard-page">
      <DashboardHeader badge="Private Seller Hub" greeting="Welcome" name={user?.name?.split(' ')[0] || 'Seller'}
        subtitle="Manage your vehicle listings and track sales"
        actions={
          <Link to="/sell" style={{ padding: '10px 20px', borderRadius: 10, background: 'var(--brand)', color: '#0a3340', fontSize: 12, fontWeight: 700, textDecoration: 'none' }}>+ List a Vehicle</Link>
        }
      />

      <div className="dash-body">
        {/* KPI Row */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(170px, 1fr))', gap: 14, marginBottom: 28 }}>
          <EnterpriseKPI icon="🚗" label="Active Listings" value={stats?.activeListings || 0} trend={12} accent="var(--brand)" />
          <EnterpriseKPI icon="💰" label="Sold Vehicles" value={stats?.soldListings || 0} trend={8} accent="#22c55e" />
          <EnterpriseKPI icon="👁" label="Total Views" value={stats?.totalViews || 0} trend={15} accent="#176B87" />
          <EnterpriseKPI icon="📈" label="Total Revenue" value={`KES ${totalRevenue.toLocaleString()}`} trend={20} accent="var(--brand)" />
          <EnterpriseKPI icon="💬" label="Inquiries" value={stats?.totalInquiries || 0} accent="#5aafa4" />
        </div>

        {/* Quick Actions */}
        <div style={{ marginBottom: 28 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: 'rgba(255,255,255,0.35)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 12 }}>Quick Actions</div>
          <EnterpriseQuickActions actions={[
            { to: '/sell', icon: '➕', label: 'List a Vehicle', desc: 'Sell your car in minutes' },
            { to: '/seller', icon: '🚗', label: 'My Listings', desc: 'View and manage all listings' },
            { to: '/seller/analytics', icon: '📊', label: 'View Analytics', desc: 'Performance and insights' },
            { to: '/seller/support', icon: '💬', label: 'Support', desc: 'Get help with selling' },
          ]} />
        </div>

        {/* Main Grid */}
        <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 2fr) minmax(0, 1fr)', gap: 24, marginBottom: 28 }}>
          {/* Listings Performance */}
          <EnterpriseCard header="📊 Listings Performance" action={<Link to="/seller" style={{ color: 'var(--brand)', fontSize: 12, fontWeight: 600, textDecoration: 'none' }}>View All →</Link>}>
            <EnterpriseTable
              columns={[
                { key: 'title', label: 'Vehicle' },
                { key: 'status', label: 'Status', align: 'center' },
                { key: 'views', label: 'Views', align: 'center' },
                { key: 'inquiries', label: 'Inquiries', align: 'center' },
              ]}
              rows={listings.slice(0, 5).map(l => ({
                title: <span style={{ fontWeight: 600, color: '#fff', fontSize: 13 }}>{l.title || `${l.brand || ''} ${l.model || ''}`}</span>,
                status: <EnterpriseStatus label={l.status || 'active'} color={statusColor(l.status || 'active')} />,
                views: <span style={{ color: 'rgba(255,255,255,0.6)' }}>{(l.views || 0).toLocaleString()}</span>,
                inquiries: <span style={{ color: 'rgba(255,255,255,0.6)' }}>{l.inquiries || 0}</span>,
              }))}
              emptyMessage="No listings yet — list your first vehicle to get started"
            />
          </EnterpriseCard>

          {/* Activity Feed */}
          <EnterpriseCard header="⚡ Recent Activity">
            {listings.length > 0 ? (
              <EnterpriseTimeline items={listings.slice(0, 5).map(l => ({
                title: l.status === 'sold' ? 'Vehicle Sold' : 'Active Listing',
                description: l.title || `${l.brand || ''} ${l.model || ''}`,
                time: l.createdAt ? timeAgo(l.createdAt) : '',
                color: l.status === 'sold' ? '#22c55e' : 'var(--brand)',
              }))} />
            ) : (
              <EnterpriseTimeline items={[
                { title: 'Welcome to KAYAD', description: 'List your first vehicle to get started', color: 'var(--brand)' },
              ]} />
            )}
          </EnterpriseCard>
        </div>

        {/* Escrow & Stats Row */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 24, marginBottom: 28 }}>
          <EnterpriseCard header="🔒 Escrow Summary">
            <EnterpriseMetricRow items={[
              { icon: '🔒', value: stats?.pendingEscrows || 0, label: 'Pending' },
              { icon: '✅', value: stats?.completedEscrows || 0, label: 'Completed' },
              { icon: '💰', value: `KES ${totalRevenue.toLocaleString()}`, label: 'Total Value' },
            ]} />
            {escrows.length > 0 && (
              <div style={{ marginTop: 16 }}>
                <EnterpriseTimeline items={escrows.slice(0, 3).map(e => ({
                  title: `${e.car?.title || 'Vehicle'} — KES ${(e.amount || 0).toLocaleString()}`,
                  description: `Status: ${e.status}`,
                  time: e.createdAt ? timeAgo(e.createdAt) : '',
                  color: e.status === 'completed' ? '#22c55e' : e.status === 'pending' ? '#176b87' : '#176B87',
                }))} />
              </div>
            )}
          </EnterpriseCard>

          <EnterpriseCard header="📈 Performance Metrics">
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
              {[
                { icon: '👁', label: 'Avg Views/Listing', value: listings.length > 0 ? Math.round((stats?.totalViews || 0) / listings.length).toLocaleString() : '0' },
                { icon: '💬', label: 'Avg Inquiries/Listing', value: listings.length > 0 ? Math.round((stats?.totalInquiries || 0) / listings.length) : '0' },
                { icon: '💰', label: 'Avg Sale Price', value: stats?.soldListings > 0 ? `KES ${Math.round(totalRevenue / stats.soldListings).toLocaleString()}` : '—' },
                { icon: '✅', label: 'Sold Rate', value: listings.length > 0 ? `${Math.round(((stats?.soldListings || 0) / listings.length) * 100)}%` : '0%' },
              ].map((m, i) => (
                <div key={i} style={{ padding: 14, borderRadius: 10, background: 'var(--surface)', border: '1px solid var(--border)', textAlign: 'center' }}>
                  <div style={{ fontSize: 18, marginBottom: 4 }}>{m.icon}</div>
                  <div style={{ fontSize: 15, fontWeight: 900, fontFamily: 'var(--font-display)', fontStyle: 'italic', color: '#fff' }}>{m.value}</div>
                  <div style={{ fontSize: 9, color: 'rgba(255,255,255,0.35)', marginTop: 2, textTransform: 'uppercase', letterSpacing: '0.06em' }}>{m.label}</div>
                </div>
              ))}
            </div>
          </EnterpriseCard>
        </div>

        {/* Recent Listings */}
        {listings.length > 0 && (
          <EnterpriseCard header="🚗 Recent Listings" action={<Link to="/seller" style={{ color: 'var(--brand)', fontSize: 12, fontWeight: 600, textDecoration: 'none' }}>View All →</Link>}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: 16 }}>
              {listings.slice(0, 4).map(car => (
                <div key={car._id} style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 12, overflow: 'hidden' }}>
                  <div style={{ height: 120, background: 'var(--bg-elevated)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    {car.images?.[0]?.url || car.image
                      ? <img src={car.images?.[0]?.url || car.image} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} loading="lazy" />
                      : <span style={{ fontSize: 32 }}>🚗</span>
                    }
                  </div>
                  <div style={{ padding: 14 }}>
                    <div style={{ fontWeight: 600, fontSize: 13, color: '#fff', marginBottom: 4 }}>{car.title || `${car.brand || ''} ${car.model || ''}`}</div>
                    <div style={{ fontFamily: 'var(--font-display)', color: 'var(--brand-light)', fontWeight: 700, fontSize: '0.95rem' }}>KES {(car.price || 0).toLocaleString()}</div>
                    <div style={{ fontSize: 11, color: 'rgba(255,255,255,0.35)', marginTop: 4 }}>{(car.views || 0).toLocaleString()} views · {car.inquiries || 0} inquiries</div>
                  </div>
                </div>
              ))}
            </div>
          </EnterpriseCard>
        )}

        {listings.length === 0 && !loading && (
          <EnterpriseCard header="🚗 Your Listings">
            <div style={{ textAlign: 'center', padding: '32px 0' }}>
              <div style={{ fontSize: 48, marginBottom: 12, opacity: 0.3 }}>🚗</div>
              <div style={{ color: 'rgba(255,255,255,0.6)', fontSize: 15, fontWeight: 700, marginBottom: 8 }}>No Listings Yet</div>
              <div style={{ color: 'rgba(255,255,255,0.3)', fontSize: 13, marginBottom: 20 }}>Start selling by listing your first vehicle</div>
              <Link to="/sell" style={{ display: 'inline-block', padding: '10px 24px', borderRadius: 10, background: 'var(--brand)', color: '#0a3340', fontSize: 12, fontWeight: 700, textDecoration: 'none' }}>List Your First Vehicle</Link>
            </div>
          </EnterpriseCard>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { User, Mail, Phone, MapPin, Shield, Bell, Lock, LogOut, Star, Clock, ChevronRight, Camera, Loader2 } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import { formatKES } from '../utils/helpers';
import { AuctionExperienceRail, BidderIdentityCard } from '../components/auction/AuctionExperienceRail';
import { AuctionPremiumHeader, AuctionPremiumStats } from '../components/auction/AuctionPremiumSurface';

interface ProfileProps {
  setPage: (page: string) => void;
  authUser?: any;
}

export default function Profile({ setPage, authUser }: ProfileProps) {
  const { user: authUser2, logout, updateProfile } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('info');
  const [loading, setLoading] = useState(false);

  // Use auth context user or prop
  const user = authUser2 || authUser || {
    name: 'Guest User',
    email: '',
    phone: '',
    location: '',
    createdAt: new Date().toISOString(),
    avatar: null,
  };

  const [editingField, setEditingField] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  const stats = [
    { label: 'Listings', value: user.listingsCount || '0' },
    { label: 'Purchases', value: user.purchasesCount || '0' },
    { label: 'Escrows', value: user.escrowsCount || '0' },
  ];

  const menuItems = [
    { key: 'info', label: 'Personal Info', icon: User },
    { key: 'notifications', label: 'Notifications', icon: Bell },
    { key: 'security', label: 'Security', icon: Lock },
  ];

  const handleLogout = async () => {
    if (confirm('Are you sure you want to sign out?')) {
      await logout();
      navigate('/');
    }
  };

  const handleEdit = (field: string, currentValue: string) => {
    setEditingField(field);
    setEditValue(currentValue || '');
  };

  const handleSaveEdit = async () => {
    if (!editingField) return;
    setLoading(true);
    try {
      await updateProfile({ [editingField]: editValue });
      toast('Profile updated successfully', 'success');
      setEditingField(null);
    } catch (err) {
      toast('Failed to update profile', 'error');
    } finally {
      setLoading(false);
    }
  };

  const memberYear = user.createdAt ? new Date(user.createdAt).getFullYear() : new Date().getFullYear();

  return (
    <div className="min-h-screen bg-[#F6FAF9] pt-16 auction-profile-experience">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 pt-6"><AuctionExperienceRail current="profile" /><AuctionPremiumHeader kicker="BIDDER IDENTITY" title="Your auction profile, ready for the next room." description="Keep your identity, preferences and auction activity in one calm place so every return feels immediate." /><AuctionPremiumStats items={[{ label: 'Listings', value: user.listingsCount || 0 }, { label: 'Purchases', value: user.purchasesCount || 0 }, { label: 'Saved auctions', value: user.savedCount || 0 }, { label: 'Member since', value: memberYear }]} /><BidderIdentityCard user={user} auctionCount={user.auctionsCount || 0} savedCount={user.savedCount || 0} onPayments={() => navigate('/?nav=payments')} /></div>
      {/* Header */}
      <div className="bg-[#0A3340] py-12">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center gap-6">
            {/* Avatar */}
            <div className="relative">
              <div className="w-24 h-24 bg-[#13B8A6]/20 rounded-full flex items-center justify-center">
                {user.avatar ? (
                  <img src={user.avatar} alt={user.name} className="w-full h-full rounded-full object-cover" />
                ) : (
                  <span className="text-4xl font-bold text-[#13B8A6]">
                    {user.name?.charAt(0) || 'U'}
                  </span>
                )}
              </div>
              <button className="absolute bottom-0 right-0 w-8 h-8 bg-[#13B8A6] rounded-full flex items-center justify-center text-[#0A3340] hover:bg-[#176B87] transition-colors">
                <Camera size={14} />
              </button>
            </div>

            {/* Info */}
            <div>
              <h1 className="font-serif text-2xl text-white font-bold">{user.name}</h1>
              <p className="text-white/50 text-sm flex items-center gap-2 mt-1">
                <Clock size={12} />
                Member since {memberYear}
              </p>
              {user.rating && (
                <div className="flex items-center gap-1 mt-2">
                  {[1, 2, 3, 4, 5].map(i => (
                    <Star key={i} size={14} className={i <= (user.rating || 0) ? 'text-[#13B8A6] fill-current' : 'text-white/30'} />
                  ))}
                  <span className="text-white/50 text-xs ml-1">({user.reviewsCount || 0} reviews)</span>
                </div>
              )}
            </div>
          </div>

          {/* Stats */}
          <div className="grid grid-cols-3 gap-4 mt-8">
            {stats.map(({ label, value }) => (
              <div key={label} className="bg-white/5 rounded-xl p-4 text-center">
                <p className="font-serif text-2xl text-[#13B8A6] font-bold">{value}</p>
                <p className="text-white/50 text-xs mt-1">{label}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          {/* Sidebar */}
          <div className="md:col-span-1">
            <div className="bg-white rounded-2xl border border-[#D7E7E4] p-4 sticky top-24">
              {menuItems.map(({ key, label, icon: Icon }) => (
                <button
                  key={key}
                  onClick={() => setActiveTab(key)}
                  className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-colors ${
                    activeTab === key
                      ? 'bg-[#13B8A6] text-[#0A3340]'
                      : 'text-[#0A3340] hover:bg-[#F6FAF9]'
                  }`}
                >
                  <Icon size={18} />
                  <span className="font-sans text-sm font-semibold">{label}</span>
                </button>
              ))}
              <div className="mt-4 pt-4 border-t border-[#D7E7E4]">
                <button
                  onClick={handleLogout}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left text-red-500 hover:bg-red-50 transition-colors"
                >
                  <LogOut size={18} />
                  <span className="font-sans text-sm font-semibold">Sign Out</span>
                </button>
              </div>
            </div>
          </div>

          {/* Main content */}
          <div className="md:col-span-3">
            {activeTab === 'info' && (
              <div className="bg-white rounded-2xl border border-[#D7E7E4] p-6">
                <h2 className="font-serif text-xl text-[#0A3340] font-bold mb-6">Personal Information</h2>

                <div className="space-y-6">
                  <div className="flex items-center gap-4 p-4 bg-[#F6FAF9] rounded-xl">
                    <div className="w-10 h-10 bg-[#13B8A6]/10 rounded-lg flex items-center justify-center">
                      <User size={18} className="text-[#176B87]" />
                    </div>
                    <div className="flex-1">
                      <label className="block font-sans text-xs text-warm-400 font-semibold uppercase tracking-wider mb-1">
                        Full Name
                      </label>
                      {editingField === 'name' ? (
                        <div className="flex items-center gap-2">
                          <input
                            type="text"
                            value={editValue}
                            onChange={(e) => setEditValue(e.target.value)}
                            className="font-sans text-sm text-[#0A3340] border border-[#BDE5DE] rounded px-2 py-1"
                          />
                          <button onClick={handleSaveEdit} disabled={loading} className="text-[#176B87] text-sm font-semibold">
                            {loading ? <Loader2 size={14} className="animate-spin" /> : 'Save'}
                          </button>
                        </div>
                      ) : (
                        <p className="font-sans text-sm text-[#0A3340]">{user.name}</p>
                      )}
                    </div>
                    {!editingField && (
                      <button onClick={() => handleEdit('name', user.name || '')} className="text-[#176B87] text-sm font-semibold hover:text-[#12576D]">Edit</button>
                    )}
                  </div>

                  <div className="flex items-center gap-4 p-4 bg-[#F6FAF9] rounded-xl">
                    <div className="w-10 h-10 bg-[#13B8A6]/10 rounded-lg flex items-center justify-center">
                      <Mail size={18} className="text-[#176B87]" />
                    </div>
                    <div className="flex-1">
                      <label className="block font-sans text-xs text-warm-400 font-semibold uppercase tracking-wider mb-1">
                        Email Address
                      </label>
                      <p className="font-sans text-sm text-[#0A3340]">{user.email}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-4 p-4 bg-[#F6FAF9] rounded-xl">
                    <div className="w-10 h-10 bg-[#13B8A6]/10 rounded-lg flex items-center justify-center">
                      <Phone size={18} className="text-[#176B87]" />
                    </div>
                    <div className="flex-1">
                      <label className="block font-sans text-xs text-warm-400 font-semibold uppercase tracking-wider mb-1">
                        Phone Number
                      </label>
                      {editingField === 'phone' ? (
                        <div className="flex items-center gap-2">
                          <input
                            type="tel"
                            value={editValue}
                            onChange={(e) => setEditValue(e.target.value)}
                            className="font-sans text-sm text-[#0A3340] border border-[#BDE5DE] rounded px-2 py-1"
                          />
                          <button onClick={handleSaveEdit} disabled={loading} className="text-[#176B87] text-sm font-semibold">
                            {loading ? <Loader2 size={14} className="animate-spin" /> : 'Save'}
                          </button>
                        </div>
                      ) : (
                        <p className="font-sans text-sm text-[#0A3340]">{user.phone || 'Not set'}</p>
                      )}
                    </div>
                    {!editingField && (
                      <button onClick={() => handleEdit('phone', user.phone || '')} className="text-[#176B87] text-sm font-semibold hover:text-[#12576D]">Edit</button>
                    )}
                  </div>

                  <div className="flex items-center gap-4 p-4 bg-[#F6FAF9] rounded-xl">
                    <div className="w-10 h-10 bg-[#13B8A6]/10 rounded-lg flex items-center justify-center">
                      <MapPin size={18} className="text-[#176B87]" />
                    </div>
                    <div className="flex-1">
                      <label className="block font-sans text-xs text-warm-400 font-semibold uppercase tracking-wider mb-1">
                        Location
                      </label>
                      {editingField === 'location' ? (
                        <div className="flex items-center gap-2">
                          <input
                            type="text"
                            value={editValue}
                            onChange={(e) => setEditValue(e.target.value)}
                            className="font-sans text-sm text-[#0A3340] border border-[#BDE5DE] rounded px-2 py-1"
                          />
                          <button onClick={handleSaveEdit} disabled={loading} className="text-[#176B87] text-sm font-semibold">
                            {loading ? <Loader2 size={14} className="animate-spin" /> : 'Save'}
                          </button>
                        </div>
                      ) : (
                        <p className="font-sans text-sm text-[#0A3340]">{user.location || 'Not set'}</p>
                      )}
                    </div>
                    {!editingField && (
                      <button onClick={() => handleEdit('location', user.location || '')} className="text-[#176B87] text-sm font-semibold hover:text-[#12576D]">Edit</button>
                    )}
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'notifications' && (
              <div className="bg-white rounded-2xl border border-[#D7E7E4] p-6">
                <h2 className="font-serif text-xl text-[#0A3340] font-bold mb-6">Notification Preferences</h2>

                <div className="space-y-4">
                  {[
                    { label: 'New bids on my listings', desc: 'Get notified when someone places a bid', key: 'new_bids', enabled: user.notifications?.newBids ?? true },
                    { label: 'Escrow updates', desc: 'Payment and delivery notifications', key: 'escrow', enabled: user.notifications?.escrow ?? true },
                    { label: 'Messages', desc: 'New messages from buyers or sellers', key: 'messages', enabled: user.notifications?.messages ?? true },
                    { label: 'Price alerts', desc: 'Vehicles you saved dropped in price', key: 'price_alerts', enabled: user.notifications?.priceAlerts ?? false },
                    { label: 'Newsletter', desc: 'Weekly market updates and new listings', key: 'newsletter', enabled: user.notifications?.newsletter ?? false },
                  ].map(({ label, desc, key, enabled }) => (
                    <div key={key} className="flex items-center justify-between p-4 bg-[#F6FAF9] rounded-xl">
                      <div>
                        <p className="font-sans text-sm font-semibold text-[#0A3340]">{label}</p>
                        <p className="font-sans text-xs text-warm-400 mt-0.5">{desc}</p>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input type="checkbox" defaultChecked={enabled} className="sr-only peer" />
                        <div className="w-11 h-6 bg-[#BDE5DE] peer-focus:outline-none peer-focus:ring-2 peer-focus:ring-[#5AAFA4]/30 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#13B8A6]"></div>
                      </label>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'security' && (
              <div className="bg-white rounded-2xl border border-[#D7E7E4] p-6">
                <h2 className="font-serif text-xl text-[#0A3340] font-bold mb-6">Security</h2>

                <div className="space-y-4">
                  <button className="w-full flex items-center justify-between p-4 bg-[#F6FAF9] rounded-xl hover:bg-[#EEF7F5] transition-colors">
                    <div className="flex items-center gap-3">
                      <Lock size={18} className="text-[#176B87]" />
                      <span className="font-sans text-sm font-semibold text-[#0A3340]">Change Password</span>
                    </div>
                    <ChevronRight size={16} className="text-warm-400" />
                  </button>

                  <button className="w-full flex items-center justify-between p-4 bg-[#F6FAF9] rounded-xl hover:bg-[#EEF7F5] transition-colors">
                    <div className="flex items-center gap-3">
                      <Shield size={18} className="text-[#176B87]" />
                      <span className="font-sans text-sm font-semibold text-[#0A3340]">Two-Factor Authentication</span>
                    </div>
                    <span className="text-xs text-warm-400">{user.twoFactorEnabled ? 'Enabled' : 'Disabled'}</span>
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

