import React, { useCallback, useEffect, useState } from 'react';
import { getBusinessRules, createBusinessRule, updateBusinessRule, deleteBusinessRule } from '../../../../services/automationApi';
import { unwrap } from '../../../../api/httpClient';
import {
  Shield, Plus, Edit, Trash2, Play, Pause, Search, Filter,
  ChevronRight, CheckCircle, XCircle, AlertCircle, GripVertical,
  ArrowRight, Copy, Settings, X, Save, ChevronDown
} from 'lucide-react';

// Design System Colors
const colors = {
  navy: '#0A3340',
  beige: '#EEF7F5',
  white: '#FFFFFF',
  emerald: '#10B981',
  terracotta: '#5aafa4',
  softBlue: '#5AAFA4',
  mutedOrange: '#13b8a6',
  mutedCrimson: '#EF4444',
};

// Operators for conditions
const operators = [
  { value: 'equals', label: 'equals' },
  { value: 'not_equals', label: 'does not equal' },
  { value: 'greater_than', label: 'is greater than' },
  { value: 'less_than', label: 'is less than' },
  { value: 'greater_than_or_equal', label: 'is at least' },
  { value: 'less_than_or_equal', label: 'is at most' },
  { value: 'contains', label: 'contains' },
  { value: 'not_contains', label: 'does not contain' },
  { value: 'starts_with', label: 'starts with' },
  { value: 'ends_with', label: 'ends with' },
  { value: 'is_empty', label: 'is empty' },
  { value: 'is_not_empty', label: 'is not empty' },
  { value: 'in', label: 'is one of' },
];

// Available fields
const fields = [
  { category: 'Dealer', fields: [
    { value: 'dealer.rating', label: 'Dealer Rating' },
    { value: 'dealer.status', label: 'Dealer Status' },
    { value: 'dealer.verified', label: 'Is Verified' },
    { value: 'dealer.subscription', label: 'Subscription Status' },
    { value: 'dealer.listings', label: 'Active Listings' },
  ]},
  { category: 'Vehicle', fields: [
    { value: 'vehicle.price', label: 'Price' },
    { value: 'vehicle.year', label: 'Year' },
    { value: 'vehicle.mileage', label: 'Mileage' },
    { value: 'vehicle.status', label: 'Status' },
    { value: 'vehicle.inspectionScore', label: 'Inspection Score' },
  ]},
  { category: 'Auction', fields: [
    { value: 'auction.status', label: 'Auction Status' },
    { value: 'auction.bids', label: 'Number of Bids' },
    { value: 'auction.deposit', label: 'Deposit Status' },
    { value: 'auction.currentBid', label: 'Current Bid' },
  ]},
  { category: 'User', fields: [
    { value: 'user.role', label: 'User Role' },
    { value: 'user.verified', label: 'Is Verified' },
    { value: 'user.subscribed', label: 'Has Subscription' },
  ]},
  { category: 'Transaction', fields: [
    { value: 'transaction.amount', label: 'Amount' },
    { value: 'transaction.status', label: 'Payment Status' },
    { value: 'transaction.method', label: 'Payment Method' },
  ]},
];

// Available actions
const actions = [
  { value: 'notification.email', label: 'Send Email', icon: 'mail' },
  { value: 'notification.sms', label: 'Send SMS', icon: 'message-square' },
  { value: 'notification.push', label: 'Send Push Notification', icon: 'bell' },
  { value: 'task.create', label: 'Create Task', icon: 'clipboard' },
  { value: 'listing.hide', label: 'Hide Listing', icon: 'eye-off' },
  { value: 'listing.archive', label: 'Archive Listing', icon: 'archive' },
  { value: 'listing.featured', label: 'Feature Listing', icon: 'star' },
  { value: 'dealer.suspend', label: 'Suspend Dealer', icon: 'user-x' },
  { value: 'dealer.activate', label: 'Activate Dealer', icon: 'user-check' },
  { value: 'dealer.verify', label: 'Mark as Verified', icon: 'check-circle' },
  { value: 'subscription.disable', label: 'Disable Subscription', icon: 'x-circle' },
  { value: 'subscription.upgrade', label: 'Upgrade Subscription', icon: 'arrow-up' },
  { value: 'escalate', label: 'Escalate', icon: 'arrow-up-circle' },
  { value: 'webhook.call', label: 'Call Webhook', icon: 'webhook' },
];

const statusColors = {
  active: 'bg-emerald-100 text-emerald-700',
  paused: 'bg-[#DDF4F0] text-[#12576D]',
  draft: 'bg-[#EEF7F5] text-[#12576D]',
};

// Rules are backend-authoritative. Never seed fabricated rules, execution counts, or timestamps.
const initialRules = [];

export default function BusinessRulesManager() {
  const [rules, setRules] = useState(initialRules);
  const [selectedRule, setSelectedRule] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showBuilder, setShowBuilder] = useState(false);
  const [filterCategory, setFilterCategory] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  const [editingRule, setEditingRule] = useState({
    name: '',
    description: '',
    category: 'dealer',
    status: 'draft',
    priority: 1,
    conditions: [{ field: '', operator: 'equals', value: '' }],
    actions: [{ type: '', config: {} }],
  });

  const normalizeRule = (raw) => ({
    ...raw,
    conditions: Array.isArray(raw.conditions) ? raw.conditions : JSON.parse(raw.conditions || '[]'),
    actions: Array.isArray(raw.actions) ? raw.actions : JSON.parse(raw.actions || '[]'),
    executions: Number(raw.executions || 0),
    priority: Number(raw.priority || 0),
  });

  const loadRules = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const response = await getBusinessRules({ limit: 100 });
      const payload = unwrap(response);
      const rows = Array.isArray(payload?.data) ? payload.data : [];
      setRules(rows.map(normalizeRule));
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || 'Unable to load business rules.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void loadRules(); }, [loadRules]);

  const filteredRules = rules.filter(rule => {
    if (filterCategory !== 'all' && rule.category !== filterCategory) return false;
    if (searchQuery && !String(rule.name || '').toLowerCase().includes(searchQuery.toLowerCase())) return false;
    return true;
  });

  const addCondition = () => {
    setEditingRule(prev => ({
      ...prev,
      conditions: [...prev.conditions, { field: '', operator: 'equals', value: '' }]
    }));
  };

  const updateCondition = (index, key, value) => {
    setEditingRule(prev => ({
      ...prev,
      conditions: prev.conditions.map((c, i) => i === index ? { ...c, [key]: value } : c)
    }));
  };

  const removeCondition = (index) => {
    setEditingRule(prev => ({
      ...prev,
      conditions: prev.conditions.filter((_, i) => i !== index)
    }));
  };

  const addAction = () => {
    setEditingRule(prev => ({
      ...prev,
      actions: [...prev.actions, { type: '', config: {} }]
    }));
  };

  const updateAction = (index, key, value) => {
    setEditingRule(prev => ({
      ...prev,
      actions: prev.actions.map((a, i) => i === index ? { ...a, [key]: value } : a)
    }));
  };

  const removeAction = (index) => {
    setEditingRule(prev => ({
      ...prev,
      actions: prev.actions.filter((_, i) => i !== index)
    }));
  };

  const saveRule = async () => {
    const name = String(editingRule.name || '').trim();
    const conditions = editingRule.conditions.filter(c => c.field);
    const actions = editingRule.actions.filter(a => a.type);
    if (!name || !conditions.length || !actions.length) {
      setError('Rule name, at least one condition, and at least one action are required.');
      return;
    }
    setSaving(true);
    setError('');
    try {
      const payload = { ...editingRule, name, conditions, actions };
      const response = selectedRule?.id
        ? await updateBusinessRule(selectedRule.id, payload)
        : await createBusinessRule(payload);
      const saved = normalizeRule(unwrap(response)?.data || {});
      if (!saved.id) throw new Error('The server did not return a saved rule.');
      setRules(prev => selectedRule?.id
        ? prev.map(rule => rule.id === saved.id ? saved : rule)
        : [saved, ...prev]);
      setSelectedRule(saved);
      setEditingRule(saved);
      setShowBuilder(false);
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || 'Unable to save business rule.');
    } finally {
      setSaving(false);
    }
  };

  const toggleRuleStatus = async (id) => {
    const rule = rules.find(item => item.id === id);
    if (!rule) return;
    const status = rule.status === 'active' ? 'paused' : 'active';
    try {
      const response = await updateBusinessRule(id, { status });
      const saved = normalizeRule(unwrap(response)?.data || {});
      setRules(prev => prev.map(item => item.id === id ? saved : item));
      if (selectedRule?.id === id) setSelectedRule(saved);
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || 'Unable to change rule status.');
    }
  };

  const removeRule = async (id) => {
    try {
      await deleteBusinessRule(id);
      setRules(prev => prev.filter(rule => rule.id !== id));
      if (selectedRule?.id === id) { setSelectedRule(null); setShowBuilder(false); }
    } catch (err) {
      setError(err?.response?.data?.error || err?.message || 'Unable to delete business rule.');
    }
  };

  const editRule = (rule) => {
    setSelectedRule(rule);
    setEditingRule({ ...rule });
    setShowBuilder(true);
  };

  return (
    <div className="flex h-full bg-[#EEF7F5]">
      {/* Rules List */}
      <div className={`${showBuilder ? 'w-1/2' : 'w-full'} bg-white border-r border-[#D7E7E4] flex flex-col transition-all`}>
        <div className="p-4 border-b border-[#D7E7E4]">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold text-[#0A3340]">Business Rules</h2>
            <button
              onClick={() => {
                setEditingRule({
                  name: '',
                  description: '',
                  category: 'dealer',
                  status: 'draft',
                  priority: 1,
                  conditions: [{ field: '', operator: 'equals', value: '' }],
                  actions: [{ type: '', config: {} }],
                });
                setSelectedRule(null);
                setShowBuilder(true);
              }}
              className="flex items-center gap-2 px-4 py-2 bg-[#0A3340] text-white rounded-lg hover:bg-[#12576D]"
            >
              <Plus size={18} />
              Create Rule
            </button>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#94A3B8]" size={18} />
              <input
                type="text"
                placeholder="Search rules..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 rounded-lg border border-[#D7E7E4] focus:border-[#0A3340] focus:ring-2 focus:ring-[#0A3340]/20 outline-none"
              />
            </div>
            <select
              value={filterCategory}
              onChange={(e) => setFilterCategory(e.target.value)}
              className="px-4 py-2 rounded-lg border border-[#D7E7E4] focus:border-[#0A3340] outline-none"
            >
              <option value="all">All Categories</option>
              <option value="dealer">Dealer</option>
              <option value="vehicle">Vehicle</option>
              <option value="auction">Auction</option>
              <option value="payment">Payment</option>
              <option value="subscription">Subscription</option>
            </select>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {error && <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{error}</div>}
          {loading && <div className="rounded-lg border border-[#D7E7E4] bg-white px-4 py-6 text-sm text-[#64748B]">Loading business rules…</div>}
          {!loading && !filteredRules.length && !error && <div className="rounded-lg border border-dashed border-[#BDE5DE] bg-white px-4 py-8 text-center text-sm text-[#64748B]">No business rules found.</div>}
          {filteredRules.map((rule) => (
            <div
              key={rule.id}
              onClick={() => setSelectedRule(rule)}
              className={`bg-white rounded-xl border-2 p-4 cursor-pointer transition-all ${
                selectedRule?.id === rule.id ? 'border-[#0A3340]' : 'border-[#D7E7E4] hover:border-[#D7E7E4]'
              }`}
            >
              <div className="flex items-start justify-between mb-3">
                <div>
                  <h3 className="font-semibold text-[#0A3340]">{rule.name}</h3>
                  <p className="text-xs text-[#94A3B8] capitalize">{rule.category}</p>
                </div>
                <div className="flex items-center gap-2">
                  <span className={`px-2 py-1 rounded-full text-xs font-medium ${statusColors[rule.status]}`}>
                    {rule.status}
                  </span>
                  <button
                    onClick={(e) => { e.stopPropagation(); toggleRuleStatus(rule.id); }}
                    className="p-1.5 hover:bg-[#EEF7F5] rounded-lg"
                  >
                    {rule.status === 'active' ? <Pause size={16} className="text-[#64748B]" /> : <Play size={16} className="text-[#64748B]" />}
                  </button>
                  <button onClick={(e) => { e.stopPropagation(); editRule(rule); }} className="p-1.5 hover:bg-[#EEF7F5] rounded-lg" aria-label="Edit rule">
                    <Edit size={16} className="text-[#64748B]" />
                  </button>
                  <button onClick={(e) => { e.stopPropagation(); void removeRule(rule.id); }} className="p-1.5 hover:bg-red-50 rounded-lg" aria-label="Delete rule">
                    <Trash2 size={16} className="text-red-500" />
                  </button>
                </div>
              </div>

              <p className="text-sm text-[#64748B] mb-4">{rule.description}</p>

              <div className="flex items-center gap-4 text-xs">
                <div className="flex items-center gap-1">
                  <span className="text-[#94A3B8]">Priority:</span>
                  <span className="font-medium text-[#64748B]">{rule.priority}</span>
                </div>
                <div className="flex items-center gap-1">
                  <span className="text-[#94A3B8]">Conditions:</span>
                  <span className="font-medium text-[#64748B]">{rule.conditions.length}</span>
                </div>
                <div className="flex items-center gap-1">
                  <span className="text-[#94A3B8]">Actions:</span>
                  <span className="font-medium text-[#64748B]">{rule.actions.length}</span>
                </div>
                <div className="ml-auto text-[#94A3B8]">
                  {Number(rule.executions || 0).toLocaleString()} executions
                </div>
              </div>

              {/* Conditions Preview */}
              <div className="mt-4 pt-4 border-t border-[#D7E7E4]">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-xs font-medium text-[#64748B]">IF</span>
                  {rule.conditions.map((cond, i) => (
                    <React.Fragment key={i}>
                      <span className="px-2 py-0.5 bg-[#EEF7F5] rounded text-xs text-[#64748B]">
                        {cond.field.split('.')[1]} {cond.operator.replace('_', ' ')} {cond.value}
                      </span>
                      {i < rule.conditions.length - 1 && <span className="text-xs text-[#94A3B8]">AND</span>}
                    </React.Fragment>
                  ))}
                </div>
                <div className="flex items-center gap-2 mt-2 flex-wrap">
                  <span className="text-xs font-medium text-[#64748B]">THEN</span>
                  {rule.actions.map((action, i) => (
                    <span key={i} className="px-2 py-0.5 bg-emerald-50 text-emerald-700 rounded text-xs">
                      {action.type.split('.')[1]}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Rule Builder */}
      {showBuilder && (
        <div className="w-1/2 flex flex-col bg-[#EEF7F5]">
          <div className="p-4 bg-white border-b border-[#D7E7E4] flex items-center justify-between">
            <h2 className="text-lg font-bold text-[#0A3340]">
              {selectedRule ? 'Edit Rule' : 'Create New Rule'}
            </h2>
            <div className="flex items-center gap-2">
              <button
                onClick={() => setShowBuilder(false)}
                className="px-4 py-2 border border-[#D7E7E4] rounded-lg hover:bg-[#F6FAF9]"
              >
                Cancel
              </button>
              <button
                onClick={saveRule}
                className="flex items-center gap-2 px-4 py-2 bg-[#0A3340] text-white rounded-lg hover:bg-[#12576D]"
              >
                <Save size={18} />
                {saving ? 'Saving…' : 'Save Rule'}
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {/* Basic Info */}
            <div className="bg-white rounded-xl p-5 shadow-sm">
              <h3 className="font-semibold text-[#0A3340] mb-4">Basic Information</h3>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-[#64748B] mb-1">Rule Name</label>
                  <input
                    type="text"
                    value={editingRule.name}
                    onChange={(e) => setEditingRule(prev => ({ ...prev, name: e.target.value }))}
                    className="w-full px-4 py-2 rounded-lg border border-[#D7E7E4] focus:border-[#0A3340] focus:ring-2 focus:ring-[#0A3340]/20 outline-none"
                    placeholder="Enter rule name"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[#64748B] mb-1">Description</label>
                  <textarea
                    value={editingRule.description}
                    onChange={(e) => setEditingRule(prev => ({ ...prev, description: e.target.value }))}
                    className="w-full px-4 py-2 rounded-lg border border-[#D7E7E4] focus:border-[#0A3340] focus:ring-2 focus:ring-[#0A3340]/20 outline-none resize-none"
                    rows={2}
                    placeholder="Describe what this rule does"
                  />
                </div>
                <div className="grid grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-[#64748B] mb-1">Category</label>
                    <select
                      value={editingRule.category}
                      onChange={(e) => setEditingRule(prev => ({ ...prev, category: e.target.value }))}
                      className="w-full px-4 py-2 rounded-lg border border-[#D7E7E4] focus:border-[#0A3340] outline-none"
                    >
                      <option value="dealer">Dealer</option>
                      <option value="vehicle">Vehicle</option>
                      <option value="auction">Auction</option>
                      <option value="payment">Payment</option>
                      <option value="subscription">Subscription</option>
                      <option value="user">User</option>
                      <option value="support">Support</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[#64748B] mb-1">Priority</label>
                    <select
                      value={editingRule.priority}
                      onChange={(e) => setEditingRule(prev => ({ ...prev, priority: parseInt(e.target.value) }))}
                      className="w-full px-4 py-2 rounded-lg border border-[#D7E7E4] focus:border-[#0A3340] outline-none"
                    >
                      <option value="1">1 - Highest</option>
                      <option value="2">2 - High</option>
                      <option value="3">3 - Medium</option>
                      <option value="4">4 - Low</option>
                      <option value="5">5 - Lowest</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[#64748B] mb-1">Status</label>
                    <select
                      value={editingRule.status}
                      onChange={(e) => setEditingRule(prev => ({ ...prev, status: e.target.value }))}
                      className="w-full px-4 py-2 rounded-lg border border-[#D7E7E4] focus:border-[#0A3340] outline-none"
                    >
                      <option value="draft">Draft</option>
                      <option value="active">Active</option>
                      <option value="paused">Paused</option>
                    </select>
                  </div>
                </div>
              </div>
            </div>

            {/* Conditions */}
            <div className="bg-white rounded-xl p-5 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="font-semibold text-[#0A3340]">Conditions</h3>
                <button
                  onClick={addCondition}
                  className="flex items-center gap-1 px-3 py-1.5 text-sm text-[#0A3340] hover:bg-[#0A3340]/10 rounded-lg"
                >
                  <Plus size={16} />
                  Add Condition
                </button>
              </div>
              <p className="text-xs text-[#64748B] mb-4">All conditions must be met (AND logic)</p>

              <div className="space-y-3">
                {editingRule.conditions.map((condition, index) => (
                  <div key={index} className="flex items-center gap-2">
                    {index > 0 && (
                      <span className="px-2 py-1 bg-[#EEF7F5] rounded text-xs font-medium text-[#64748B]">AND</span>
                    )}
                    <select
                      value={condition.field}
                      onChange={(e) => updateCondition(index, 'field', e.target.value)}
                      className="flex-1 px-3 py-2 rounded-lg border border-[#D7E7E4] text-sm"
                    >
                      <option value="">Select field...</option>
                      {fields.map(cat => (
                        <optgroup key={cat.category} label={cat.category}>
                          {cat.fields.map(field => (
                            <option key={field.value} value={field.value}>{field.label}</option>
                          ))}
                        </optgroup>
                      ))}
                    </select>
                    <select
                      value={condition.operator}
                      onChange={(e) => updateCondition(index, 'operator', e.target.value)}
                      className="w-40 px-3 py-2 rounded-lg border border-[#D7E7E4] text-sm"
                    >
                      {operators.map(op => (
                        <option key={op.value} value={op.value}>{op.label}</option>
                      ))}
                    </select>
                    <input
                      type="text"
                      value={condition.value}
                      onChange={(e) => updateCondition(index, 'value', e.target.value)}
                      className="w-32 px-3 py-2 rounded-lg border border-[#D7E7E4] text-sm"
                      placeholder="Value"
                    />
                    {editingRule.conditions.length > 1 && (
                      <button
                        onClick={() => removeCondition(index)}
                        className="p-2 hover:bg-red-50 rounded-lg text-red-500"
                      >
                        <X size={16} />
                      </button>
                    )}
                  </div>
                ))}
              </div>
            </div>

            {/* Actions */}
            <div className="bg-white rounded-xl p-5 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="font-semibold text-[#0A3340]">Actions</h3>
                <button
                  onClick={addAction}
                  className="flex items-center gap-1 px-3 py-1.5 text-sm text-[#0A3340] hover:bg-[#0A3340]/10 rounded-lg"
                >
                  <Plus size={16} />
                  Add Action
                </button>
              </div>
              <p className="text-xs text-[#64748B] mb-4">All actions will be executed when conditions are met</p>

              <div className="space-y-3">
                {editingRule.actions.map((action, index) => (
                  <div key={index} className="p-3 bg-[#F6FAF9] rounded-lg">
                    <div className="flex items-center gap-2 mb-2">
                      <select
                        value={action.type}
                        onChange={(e) => updateAction(index, 'type', e.target.value)}
                        className="flex-1 px-3 py-2 rounded-lg border border-[#D7E7E4] text-sm bg-white"
                      >
                        <option value="">Select action...</option>
                        {actions.map(a => (
                          <option key={a.value} value={a.value}>{a.label}</option>
                        ))}
                      </select>
                      {editingRule.actions.length > 1 && (
                        <button
                          onClick={() => removeAction(index)}
                          className="p-2 hover:bg-red-50 rounded-lg text-red-500"
                        >
                          <X size={16} />
                        </button>
                      )}
                    </div>
                    {action.type && (
                      <div className="p-3 bg-white rounded border border-[#D7E7E4]">
                        <p className="text-xs text-[#64748B]">Configure action parameters...</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

