              <Icon size={24} style={{ color: module?.color }} />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-[#0A3340]">{module?.label}</h2>
              <p className="text-sm text-[#64748B]">Manage your {module?.label?.toLowerCase()} content</p>
