            <div className="bg-white rounded-xl border border-[#D7E7E4] overflow-hidden">
              <table className="w-full">
                <thead>
                  <tr className="bg-[#F6FAF9] border-b border-[#D7E7E4]">
                    <th className="px-4 py-3 text-left">
