                              <Eye size={14} />
                            </button>
                            <button className="p-1.5 rounded hover:bg-[#EEF7F5]" title="Edit" aria-label="Edit">
                              <Edit size={14} />
                            </button>
                            <button className="p-1.5 rounded hover:bg-[#EEF7F5]" title="Copy URL" aria-label="Copy URL">
                              <Copy size={14} />
