source:
import React, { useState, useEffect } from 'react';
import {
  Binary, Play, TrendingUp, BarChart3, DollarSign, Users, Target,
  Settings, Globe, Building, Zap, Calendar, Gavel, PieChart,
  LineChart, Activity, AlertTriangle, CheckCircle, X, Plus, Search,
  ChevronRight, RefreshCw, ArrowRight, Lightbulb, Clock, Filter,
  Download, Eye, Edit, Trash2, Save, History, BookOpen, Sparkles,
  Map, TrendingDown, Percent, ShoppingCart, Wallet, ArrowUpRight,
  	  ArrowDownRight, Layers, GitBranch, Server, Cpu, Gauge, Megaphone
} from 'lucide-react';
import * as dtApi from '../../../services/digitalTwinApi';
import { isUnavailable } from '../../../components/admin/adminStat';

// A missing or non-numeric figure is shown as Unavailable, never as 0.
const nv = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : 'Unavailable');

// Design System Colors
const colors = {
  navy: '#0A3340',
  beige: '#EEF7F5',
  white: '#FFFFFF',
  emerald: '#10B981',
  terracotta: '#5aafa4',
  softBlue: '#5AAFA4',
  mutedOrange: '#13b8a6',
  mutedCrimson: '#EF4444',
  purple: '#5aafa4',
  pink: '#13B8A6',
};

const modules = [
  { id: 'dashboard', label: 'Decision Dashboard', icon: BarChart3, color: colors.navy },
  { id: 'marketplace', label: 'Marketplace Simulator', icon: ShoppingCart, color: colors.emerald },
  { id: 'auction', label: 'Auction Simulator', icon: Gavel, color: colors.terracotta },
  { id: 'pricing', label: 'Pricing Simulator', icon: DollarSign, color: colors.softBlue },
  { id: 'marketing', label: 'Marketing Simulator', icon: Target, color: colors.mutedOrange },
  { id: 'growth', label: 'Growth Simulator', icon: TrendingUp, color: colors.purple },
  { id: 'scenarios', label: 'Scenario Library', icon: BookOpen, color: colors.pink },
  { id: 'whatif', label: 'What-If Analysis', icon: Lightbulb, color: '#13b8a6' },
  { id: 'predictions', label: 'AI Predictions', icon: Sparkles, color: colors.navy },
  { id: 'history', label: 'Simulation History', icon: History, color: colors.softBlue },
];

const simulatorTypes = [
  { id: 'marketplace', name: 'Marketplace Simulation', icon: ShoppingCart, description: 'Simulate user growth, dealer expansion, and traffic spikes', color: colors.emerald },
  { id: 'auction', name: 'Auction Simulation', icon: Gavel, description: 'Test bidder participation, revenue, and auction rules', color: colors.terracotta },
  { id: 'pricing', name: 'Pricing Simulation', icon: DollarSign, description: 'Model commission and subscription changes', color: colors.softBlue },
  { id: 'marketing', name: 'Marketing Simulation', icon: Target, description: 'Estimate campaign impact on traffic and conversions', color: colors.mutedOrange },
  { id: 'workflow', name: 'Workflow Simulation', icon: Zap, description: 'Validate automation and approval workflows', color: colors.purple },
  { id: 'growth', name: 'Growth Simulation', icon: TrendingUp, description: 'Project user acquisition and market expansion', color: colors.navy },
  { id: 'revenue', name: 'Revenue Simulation', icon: Wallet, description: 'Forecast revenue streams and growth', color: colors.emerald },
  { id: 'dealer', name: 'Dealer Simulation', icon: Building, description: 'Model dealer performance and retention', color: colors.terracotta },
];

export default function DigitalTwinCenter() {
  const [activeModule, setActiveModule] = useState('dashboard');
  const [dashboard, setDashboard] = useState(null);
  const [simulations, setSimulations] = useState([]);
  const [scenarios, setScenarios] = useState([]);
  const [templates, setTemplates] = useState([]);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState(false);
  const [whatIfQuestion, setWhatIfQuestion] = useState('');
  const [whatIfResult, setWhatIfResult] = useState(null);
  const [selectedSimulation, setSelectedSimulation] = useState(null);
  const [simulationResults, setSimulationResults] = useState(null);
  const [showNewSimulation, setShowNewSimulation] = useState(false);
  const [newSimulation, setNewSimulation] = useState({
    name: '',
    simulationType: 'marketplace',
    duration: 90,
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      setLoadError(false);
      const { data: dashData } = await dtApi.getDigitalTwinDashboard();
      setDashboard(dashData.data);

      const { data: simData } = await dtApi.getSimulations({ limit: 20 });
      setSimulations(simData.data);

      const { data: scenarioData } = await dtApi.getScenarios();
      setScenarios(scenarioData.data);

      const { data: templateData } = await dtApi.getScenarioTemplates();
      setTemplates(templateData.data);

      const { data: historyData } = await dtApi.getSimulationHistory({ limit: 10 });
      setHistory(historyData.data);
    } catch (error) {
      console.error('Failed to load Digital Twin data:', error);
      // No synthetic fallback: figures stay unavailable until the backend responds.
      setLoadError(true);
    } finally {
      setLoading(false);
    }
  };

  const handleRunSimulation = async (type) => {
    setLoading(true);
    try {
      const { data } = await dtApi.createSimulation({
        name: `${type} Simulation - ${new Date().toISOString().split('T')[0]}`,
        simulationType: type,
        duration: 90,
        parameters: {},
      });

      const result = await dtApi.runSimulation(data.data.id);
      setSimulationResults(result.data.results);
      setSelectedSimulation(data.data);
      setActiveModule('results');
    } catch (error) {
      console.error('Simulation failed:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleRunScenario = async (scenarioId) => {
    setLoading(true);
    try {
      const result = await dtApi.runScenario(scenarioId);
      setSimulationResults(result.data.results);
      setSelectedSimulation(result.data.simulation);
      setActiveModule('results');
    } catch (error) {
      console.error('Scenario run failed:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleWhatIf = async () => {
    if (!whatIfQuestion.trim()) return;

    setLoading(true);
    try {
      const { data } = await dtApi.whatIfAnalysis(whatIfQuestion);
      setWhatIfResult(data.data);
    } catch (error) {
      console.error('What-If analysis failed:', error);
    } finally {
      setLoading(false);
    }
  };

  // ============================================
  // DASHBOARD
  // ============================================

  const renderDashboard = () => (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-[#0A3340]">Executive Decision Dashboard</h2>
        <button
          onClick={() => setActiveModule('whatif')}
          className="flex items-center gap-2 px-4 py-2 bg-[#0A3340] text-white rounded-lg hover:bg-[#12576D]"
        >
          <Lightbulb size={18} />
          Ask What-If
        </button>
      </div>

      {/* Overview Stats */}
      <div className="grid grid-cols-4 gap-4">
        {[
          { label: 'Total Simulations', value: nv(dashboard?.overview?.totalSimulations), icon: Binary, color: colors.navy },
          { label: 'Completed', value: nv(dashboard?.overview?.completedSimulations), icon: CheckCircle, color: colors.emerald },
          { label: 'Saved Scenarios', value: nv(dashboard?.overview?.totalScenarios), icon: BookOpen, color: colors.purple },
          { label: 'Predictions', value: nv(dashboard?.overview?.totalPredictions), icon: Sparkles, color: colors.mutedOrange },
        ].map((stat, i) => (
          <div key={i} className="bg-white rounded-xl p-5 shadow-sm border border-[#D7E7E4]">
            <div className="flex items-center gap-2 mb-3">
              <stat.icon size={18} style={{ color: stat.color }} />
              <span className="text-sm text-[#64748B]">{stat.label}</span>
            </div>
            <p className={`${isUnavailable(stat.value) ? 'text-lg' : 'text-3xl'} font-bold text-[#0A3340]`}>{stat.value}</p>
          </div>
        ))}
      </div>

      {/* Quick Simulators */}
      <div className="bg-white rounded-xl p-5 shadow-sm border border-[#D7E7E4]">
        <h3 className="font-semibold text-[#0A3340] mb-4">Quick Simulations</h3>
        <div className="grid grid-cols-4 gap-4">
          {simulatorTypes.slice(0, 4).map((type) => (
            <button
              key={type.id}
              onClick={() => handleRunSimulation(type.id)}
              className="p-4 rounded-xl border border-[#D7E7E4] hover:border-[#0A3340] transition-colors text-left"
            >
              <div className="w-12 h-12 rounded-xl flex items-center justify-center mb-3" style={{ backgroundColor: `${type.color}20` }}>
                <type.icon size={24} style={{ color: type.color }} />
              </div>
              <h4 className="font-medium text-[#0A3340] text-sm">{type.name}</h4>
              <p className="text-xs text-[#64748B] mt-1">{type.description}</p>
            </button>
          ))}
        </div>
      </div>

      {/* Recent Simulations */}
      <div className="grid grid-cols-2 gap-6">
        <div className="bg-white rounded-xl p-5 shadow-sm border border-[#D7E7E4]">
          <h3 className="font-semibold text-[#0A3340] mb-4">Recent Simulations</h3>
          <div className="space-y-3">
            {(dashboard?.recentSimulations || []).map((sim) => (
              <div key={sim.id} className="flex items-center justify-between p-3 bg-[#F6FAF9] rounded-lg">
                <div>
                  <p className="font-medium text-[#0A3340]">{sim.name}</p>
                  <p className="text-xs text-[#64748B]">{sim.type} - {new Date(sim.createdAt).toLocaleDateString()}</p>
                </div>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                  sim.status === 'completed' ? 'bg-emerald-100 text-emerald-700' :
                  sim.status === 'running' ? 'bg-[#DDF4F0] text-[#12576D]' :
                  'bg-[#EEF7F5] text-[#12576D]'
                }`}>
                  {sim.status}
                </span>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white rounded-xl p-5 shadow-sm border border-[#D7E7E4]">
          <h3 className="font-semibold text-[#0A3340] mb-4">Popular Scenarios</h3>
          <div className="space-y-3">
            {(dashboard?.popularScenarios || []).map((scenario) => (
              <div key={scenario.id} className="flex items-center justify-between p-3 bg-[#F6FAF9] rounded-lg">
                <div>
                  <p className="font-medium text-[#0A3340]">{scenario.name}</p>
                  <p className="text-xs text-[#64748B]">{scenario.category}</p>
                </div>
                <span className="text-sm font-medium text-[#64748B]">{scenario.usageCount} runs</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* AI Recommendations */}
      <div className="bg-gradient-to-r from-[#0A3340] to-[#12576d] rounded-xl p-6 text-white">
        <div className="flex items-center gap-3 mb-4">
          <Sparkles size={24} />
          <h3 className="font-semibold text-lg">AI Decision Recommendations</h3>
        </div>
        <div className="grid grid-cols-3 gap-4">
          {[].map((rec, i) => (
            <div key={i} className="bg-white/10 backdrop-blur rounded-lg p-4">
              <div className="flex items-center gap-2 mb-2">
                <span className={`px-2 py-0.5 rounded text-xs font-medium ${
                  rec.impact === 'High' ? 'bg-emerald-400/30' : 'bg-[#13B8A6]/30'
                }`}>
                  {rec.impact} Impact
                </span>
                <span className="text-xs opacity-80">{rec.confidence}% confidence</span>
              </div>
              <h4 className="font-medium mb-1">{rec.title}</h4>
              <p className="text-sm opacity-80">{rec.description}</p>
            </div>
          ))}<p className="col-span-full text-sm text-white/90" role="status">No AI recommendations were returned.</p>
        </div>
      </div>
    </div>
  );

  // ============================================
  // SIMULATOR MODULES
  // ============================================

  const renderSimulator = (type, title, IconComponent, color) => (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 rounded-xl flex items-center justify-center" style={{ backgroundColor: `${color}20` }}>
            <IconComponent size={24} style={{ color }} />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-[#0A3340]">{title}</h2>
            <p className="text-sm text-[#64748B]">Run simulations before making changes</p>
          </div>
        </div>
        <button
          onClick={() => handleRunSimulation(type)}
          className="flex items-center gap-2 px-4 py-2 bg-[#0A3340] text-white rounded-lg hover:bg-[#12576D]"
        >
          <Play size={18} />
          Run Simulation
        </button>
      </div>

      {/* Simulator Types Grid */}
      <div className="grid grid-cols-2 gap-4">
        {simulatorTypes.filter(t => t.id === type || type === 'all').map((simType) => (
          <div key={simType.id} className="bg-white rounded-xl p-5 shadow-sm border border-[#D7E7E4]">
            <div className="flex items-center gap-3 mb-3">
              <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ backgroundColor: `${simType.color}20` }}>
                <simType.icon size={20} style={{ color: simType.color }} />
              </div>
              <h3 className="font-semibold text-[#0A3340]">{simType.name}</h3>
            </div>
            <p className="text-sm text-[#64748B] mb-4">{simType.description}</p>
            <div className="flex gap-2">
              <button
                onClick={() => handleRunSimulation(simType.id)}
                className="flex-1 px-3 py-2 border border-[#D7E7E4] rounded-lg text-sm hover:bg-[#F6FAF9]"
              >
                Quick Run
              </button>
              <button
                onClick={() => setActiveModule('scenarios')}
                className="px-3 py-2 border border-[#D7E7E4] rounded-lg text-sm hover:bg-[#F6FAF9]"
              >
                <BookOpen size={16} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  // ============================================
  // SCENARIO LIBRARY
  // ============================================

  const renderScenarios = () => (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-[#0A3340]">Scenario Library</h2>
        <button className="flex items-center gap-2 px-4 py-2 bg-[#0A3340] text-white rounded-lg hover:bg-[#12576D]">
          <Plus size={18} />
          New Scenario
        </button>
      </div>

      {/* Templates */}
      <div className="bg-white rounded-xl p-5 shadow-sm border border-[#D7E7E4]">
        <h3 className="font-semibold text-[#0A3340] mb-4">Ready-to-Run Templates</h3>
        <div className="grid grid-cols-3 gap-4">
          {templates.map((template) => (
            <div key={template.id} className="p-4 border border-[#D7E7E4] rounded-xl hover:border-[#0A3340] cursor-pointer transition-colors">
              <div className="flex items-center gap-2 mb-2">
                <div className="w-8 h-8 rounded-lg bg-[#0A3340]/10 flex items-center justify-center">
                  <BookOpen size={16} className="text-[#0A3340]" />
                </div>
                <h4 className="font-medium text-[#0A3340]">{template.name}</h4>
              </div>
              <p className="text-sm text-[#64748B] mb-3">{template.description}</p>
              <button
                onClick={() => handleRunScenario(template.id)}
                className="w-full px-3 py-2 bg-[#0A3340] text-white rounded-lg text-sm hover:bg-[#12576D]"
              >
                Run Scenario
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* Saved Scenarios */}
      <div className="bg-white rounded-xl p-5 shadow-sm border border-[#D7E7E4]">
        <h3 className="font-semibold text-[#0A3340] mb-4">Your Saved Scenarios</h3>
        <div className="space-y-3">
          {scenarios.map((scenario) => (
            <div key={scenario.id} className="flex items-center justify-between p-4 bg-[#F6FAF9] rounded-lg">
              <div>
                <p className="font-medium text-[#0A3340]">{scenario.name}</p>
                <p className="text-sm text-[#64748B]">{scenario.description}</p>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-sm text-[#64748B]">{scenario.usageCount || 0} runs</span>
                <button
                  onClick={() => handleRunScenario(scenario.id)}
                  className="px-3 py-1.5 bg-[#0A3340] text-white rounded-lg text-sm hover:bg-[#12576D]"
                >
                  Run
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  // ============================================
  // WHAT-IF ANALYSIS
  // ============================================

  const renderWhatIf = () => (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-[#0A3340]">What-If Analysis</h2>
      <p className="text-[#64748B]">Ask questions in natural language and get AI-powered predictions</p>

      {/* Question Input */}
      <div className="bg-white rounded-xl p-6 shadow-sm border border-[#D7E7E4]">
        <h3 className="font-semibold text-[#0A3340] mb-4">Ask a Question</h3>
        <div className="flex gap-3">
          <input
            type="text"
            value={whatIfQuestion}
            onChange={(e) => setWhatIfQuestion(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleWhatIf()}
            placeholder="e.g., What happens if we launch Uganda next month?"
            className="flex-1 px-4 py-3 border border-[#D7E7E4] rounded-xl focus:outline-none focus:ring-2 focus:ring-[#0A3340]"
          />
          <button
            onClick={handleWhatIf}
            disabled={loading || !whatIfQuestion.trim()}
            className="px-6 py-3 bg-[#0A3340] text-white rounded-xl hover:bg-[#12576D] disabled:opacity-50"
          >
            {loading ? 'Analyzing...' : 'Analyze'}
          </button>
        </div>

        {/* Example Questions */}
        <div className="mt-4">
          <p className="text-sm text-[#64748B] mb-2">Try these:</p>
          <div className="flex flex-wrap gap-2">
            {[
              'What if auction commission changes to a fixed fee?',
              'What if featured listings become free for one month?',
              'What happens if we expand to Uganda?',
              'What if we launch a Toyota Week campaign?',
            ].map((q, i) => (
              <button
                key={i}
                onClick={() => setWhatIfQuestion(q)}
                className="px-3 py-1.5 bg-[#EEF7F5] text-[#12576D] rounded-full text-sm hover:bg-[#DDF4F0]"
              >
                {q}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Results */}
      {whatIfResult && (
        <div className="bg-white rounded-xl p-6 shadow-sm border border-[#D7E7E4]">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-[#0A3340]">Analysis Results</h3>
            <div className="flex items-center gap-2">
              <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                whatIfResult.confidence > 0.8 ? 'bg-emerald-100 text-emerald-700' :
                whatIfResult.confidence > 0.7 ? 'bg-[#DDF4F0] text-[#12576D]' :
                'bg-red-100 text-red-700'
              }`}>
                {Math.round(whatIfResult.confidence * 100)}% Confidence
              </span>
            </div>
          </div>

          {/* Metrics */}
          <div className="grid grid-cols-3 gap-4 mb-6">
            {Object.entries(whatIfResult.results?.metrics || {}).map(([key, metric]) => (
              <div key={key} className="p-4 bg-[#F6FAF9] rounded-xl">
                <p className="text-sm text-[#64748B] capitalize">{key.replace(/([A-Z])/g, ' $1')}</p>
                {metric.projected !== undefined && (
                  <p className="text-2xl font-bold text-[#0A3340]">
                    {metric.projected?.toLocaleString?.() || metric.projected}
                    {metric.change && <span className="text-sm text-emerald-600 ml-2">{metric.change}</span>}
                  </p>
                )}
              </div>
            ))}
          </div>

          {/* Risks */}
          <div className="mb-6">
            <h4 className="font-medium text-[#0A3340] mb-2">Risks</h4>
            <div className="space-y-2">
              {(whatIfResult.results?.risks || []).map((risk, i) => (
                <div key={i} className="flex items-center gap-3 p-3 bg-[#F3FAF9] rounded-lg">
                  <AlertTriangle size={16} className="text-[#176B87]" />
                  <div className="flex-1">
                    <p className="text-sm text-[#12576D]">{risk.description}</p>
                    <p className="text-xs text-[#64748B]">Probability: {Math.round(risk.probability * 100)}%</p>
                  </div>
                  <span className={`px-2 py-0.5 rounded text-xs font-medium ${
                    risk.level === 'high' ? 'bg-red-100 text-red-700' :
                    risk.level === 'medium' ? 'bg-[#DDF4F0] text-[#12576D]' :
                    'bg-[#EEF7F5] text-[#12576D]'
                  }`}>
                    {risk.level}
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* Recommendations */}
          <div>
            <h4 className="font-medium text-[#0A3340] mb-2">Recommendations</h4>
            <div className="space-y-2">
              {(whatIfResult.results?.recommendations || []).map((rec, i) => (
                <div key={i} className="flex items-center gap-3 p-3 bg-emerald-50 rounded-lg">
                  <CheckCircle size={16} className="text-emerald-600" />
                  <p className="text-sm text-[#12576D]">{rec}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );

  // ============================================
  // SIMULATION HISTORY
  // ============================================

  const renderHistory = () => (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-[#0A3340]">Simulation History</h2>

      <div className="bg-white rounded-xl shadow-sm border border-[#D7E7E4] overflow-hidden">
        <table className="w-full">
          <thead className="bg-[#F6FAF9]">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#64748B] uppercase">Simulation</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#64748B] uppercase">Type</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#64748B] uppercase">Duration</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#64748B] uppercase">Status</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#64748B] uppercase">Date</th>
              <th className="px-6 py-3 text-right text-xs font-medium text-[#64748B] uppercase">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#D7E7E4]">
            {history.map((item) => (
              <tr key={item.id} className="hover:bg-[#F6FAF9]">
                <td className="px-6 py-4 font-medium text-[#0A3340]">{item.name}</td>
                <td className="px-6 py-4 capitalize">
                  <span className="px-2 py-1 bg-[#EEF7F5] rounded text-xs">{item.simulationType}</span>
                </td>
                <td className="px-6 py-4 text-sm text-[#64748B]">{item.duration || 90} days</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                    item.status === 'completed' ? 'bg-emerald-100 text-emerald-700' :
                    item.status === 'running' ? 'bg-[#DDF4F0] text-[#12576D]' :
                    'bg-[#EEF7F5] text-[#12576D]'
                  }`}>
                    {item.status}
                  </span>
                </td>
                <td className="px-6 py-4 text-sm text-[#64748B]">
                  {new Date(item.createdAt).toLocaleDateString()}
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center justify-end gap-2">
                    <button className="p-2 hover:bg-[#EEF7F5] rounded-lg" title="View" aria-label="View">
                      <Eye size={16} />
                    </button>
                    <button className="p-2 hover:bg-[#EEF7F5] rounded-lg" title="Rerun" aria-label="Rerun">
                      <RefreshCw size={16} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  // ============================================
  // PREDICTIONS
  // ============================================

  const renderPredictions = () => (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-[#0A3340]">AI Predictions</h2>

      {/* Prediction Types */}
      <div className="grid grid-cols-4 gap-4">
        {[
          { name: 'Revenue Forecast', icon: TrendingUp, color: colors.emerald },
          { name: 'User Growth', icon: Users, color: colors.softBlue },
          { name: 'Market Trends', icon: LineChart, color: colors.purple },
          { name: 'Risk Analysis', icon: AlertTriangle, color: colors.mutedCrimson },
        ].map((type, i) => (
          <div key={i} className="bg-white rounded-xl p-5 shadow-sm border border-[#D7E7E4] cursor-pointer hover:border-[#0A3340]">
            <div className="w-10 h-10 rounded-lg flex items-center justify-center mb-3" style={{ backgroundColor: `${type.color}20` }}>
              <type.icon size={20} style={{ color: type.color }} />
            </div>
            <h3 className="font-medium text-[#0A3340]">{type.name}</h3>
          </div>
        ))}
      </div>

      {/* Recent Predictions */}
      <div className="bg-white rounded-xl p-5 shadow-sm border border-[#D7E7E4]">
        <h3 className="font-semibold text-[#0A3340] mb-4">Recent Predictions</h3>
        <div className="space-y-3">
          {[].map((pred, i) => (
            <div key={i} className="p-4 bg-[#F6FAF9] rounded-lg">
              <div className="flex items-center justify-between mb-2">
                <span className="px-2 py-0.5 bg-[#0A3340]/10 text-[#0A3340] rounded text-xs font-medium capitalize">{pred.type}</span>
                <span className="text-xs text-[#64748B]">{pred.date}</span>
              </div>
              <p className="text-sm text-[#12576D] mb-2">{pred.prediction}</p>
              <div className="flex items-center gap-2">
                <div className="flex-1 bg-[#DDF4F0] rounded-full h-2">
                  <div className="bg-[#0A3340] h-2 rounded-full" style={{ width: `${pred.confidence}%` }} />
                </div>
                <span className="text-xs font-medium text-[#64748B]">{pred.confidence}%</span>
              </div>
            </div>
          ))}<p className="col-span-full text-sm text-[#64748B]" role="status">No predictions have been recorded.</p>
        </div>
      </div>
    </div>
  );

  const renderModuleContent = () => {
    switch (activeModule) {
      case 'dashboard': return renderDashboard();
      case 'marketplace': return renderSimulator('marketplace', 'Marketplace Simulator', ShoppingCart, colors.emerald);
      case 'auction': return renderSimulator('auction', 'Auction Simulator', Gavel, colors.terracotta);
      case 'pricing': return renderSimulator('pricing', 'Pricing Simulator', DollarSign, colors.softBlue);
      case 'marketing': return renderSimulator('marketing', 'Marketing Simulator', Target, colors.mutedOrange);
      case 'growth': return renderSimulator('growth', 'Growth Simulator', TrendingUp, colors.purple);
      case 'scenarios': return renderScenarios();
      case 'whatif': return renderWhatIf();
      case 'predictions': return renderPredictions();
      case 'history': return renderHistory();
      default: return renderDashboard();
    }
  };

  return (
    <div className="min-h-screen bg-[#EEF7F5]">
      {/* Header */}
      <header className="bg-white border-b border-[#D7E7E4] sticky top-0 z-50">
        <div className="px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-[#0A3340] to-[#12576d] flex items-center justify-center">
                  <Binary size={20} className="text-white" />
                </div>
                <div>
                  <h1 className="text-lg font-bold text-[#0A3340]">Digital Twin Center</h1>
                  <p className="text-xs text-[#64748B]">Enterprise Simulation Platform</p>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm ${dashboard ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}>
                <span className={`w-2 h-2 rounded-full ${dashboard ? 'bg-emerald-500' : 'bg-slate-400'}`} />
                {dashboard ? 'Twin data loaded' : 'Twin status unavailable'}
              </div>
              <button onClick={loadData} className="p-2 hover:bg-[#EEF7F5] rounded-lg" aria-label="Refresh">
                <RefreshCw size={20} className="text-[#64748B]" />
              </button>
            </div>
          </div>
        </div>
      </header>

      <div className="flex">
        {/* Sidebar */}
        <aside className="w-64 bg-white border-r border-[#D7E7E4] min-h-[calc(100vh-73px)] sticky top-[73px] overflow-y-auto">
          <nav className="p-4 space-y-1">
            {modules.map((mod) => {
              const Icon = mod.icon;
              const isActive = activeModule === mod.id;
              return (
                <button
                  key={mod.id}
                  onClick={() => setActiveModule(mod.id)}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all ${
                    isActive
                      ? 'bg-[#0A3340] text-white'
                      : 'text-[#64748B] hover:bg-[#EEF7F5]'
                  }`}
                >
                  <Icon size={18} />
                  <span className="text-sm font-medium">{mod.label}</span>
                  {isActive && <ChevronRight size={16} className="ml-auto" />}
                </button>
              );
            })}
          </nav>

          {/* Quick Stats */}
          {dashboard && (
            <div className="p-4 border-t border-[#D7E7E4]">
              <p className="text-xs text-[#64748B] mb-2">Simulation Activity</p>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-[#64748B]">Completed</span>
                  <span className="text-sm font-medium text-[#0A3340]">{nv(dashboard.overview?.completedSimulations)}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-sm text-[#64748B]">Success Rate</span>
                  <span className="text-sm font-medium text-emerald-600">{Number.isFinite(dashboard.overview?.successRate) ? `${dashboard.overview.successRate}%` : 'Unavailable'}</span>
                </div>
              </div>
            </div>
          )}
        </aside>

        {/* Main Content */}
        <div className="flex-1 p-6 overflow-auto">
          {loadError && <div role="alert" className="mb-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800">Digital Twin data could not be loaded. Figures are unavailable, not zero.</div>}
          {renderModuleContent()}
        </div>
      </div>
    </div>
  );
}

