import { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import { getTeamMembers, inviteTeamMember, updateTeamMember, removeTeamMember } from '../../services/dealerPlatformApi';
import { useToast } from '../../context/ToastContext';
import { Users, Mail, Shield, ChevronDown, Trash2, Plus, RefreshCw, Settings, Eye, Edit3, DollarSign, MessageCircle } from 'lucide-react';

const ROLES = [
  { id: 'manager',         label: 'Manager',         desc: 'Full business access, can manage team',       color: '#5aafa4' },
  { id: 'sales_agent',     label: 'Sales Agent',     desc: 'List and edit cars, chat with buyers',         color: 'var(--brand)' },
  { id: 'lot_agent',       label: 'Lot Agent',       desc: 'Upload and manage car photos & listings',      color: '#176B87' },
  { id: 'finance_officer', label: 'Finance Officer', desc: 'View earnings and payment records',             color: '#22c55e' },
  { id: 'viewer',          label: 'Viewer',          desc: 'Read-only access to listings and analytics',   color: 'rgba(255,255,255,0.45)' },
];

const ROLE_DEFAULTS = {
  manager:         { canListCars:true,  canEditCars:true,  canDeleteCars:true,  canViewEarnings:true,  canManageTeam:true,  canApproveDeals:true,  canChatBuyers:true,  canEditSettings:true  },
  sales_agent:     { canListCars:true,  canEditCars:true,  canDeleteCars:false, canViewEarnings:false, canManageTeam:false, canApproveDeals:false, canChatBuyers:true,  canEditSettings:false },
  lot_agent:       { canListCars:true,  canEditCars:true,  canDeleteCars:false, canViewEarnings:false, canManageTeam:false, canApproveDeals:false, canChatBuyers:false, canEditSettings:false },
  finance_officer: { canListCars:false, canEditCars:false, canDeleteCars:false, canViewEarnings:true,  canManageTeam:false, canApproveDeals:false, canChatBuyers:false, canEditSettings:false },
  viewer:          { canListCars:false, canEditCars:false, canDeleteCars:false, canViewEarnings:false, canManageTeam:false, canApproveDeals:false, canChatBuyers:false, canEditSettings:false },
};

const PERMISSIONS = [
  { key: 'canListCars',     label: 'List Cars',        icon: Plus },
  { key: 'canEditCars',     label: 'Edit Cars',        icon: Edit3 },
  { key: 'canDeleteCars',   label: 'Delete Cars',      icon: Trash2 },
  { key: 'canViewEarnings', label: 'View Earnings',    icon: DollarSign },
  { key: 'canManageTeam',   label: 'Manage Team',      icon: Users },
  { key: 'canApproveDeals', label: 'Approve Deals',    icon: Shield },
  { key: 'canChatBuyers',   label: 'Chat with Buyers', icon: MessageCircle },
  { key: 'canEditSettings', label: 'Edit Settings',    icon: Settings },
];

function RoleBadge({ role }) {
  const r = ROLES.find(x => x.id === role) || ROLES[1];
  return (
    <span style={{ padding: '3px 10px', borderRadius: 9999, fontSize: 10, fontWeight: 700, background: `${r.color}14`, border: `1px solid ${r.color}35`, color: r.color, textTransform: 'capitalize', whiteSpace: 'nowrap' }}>
      {r.label}
    </span>
  );
}

function StatusDot({ status }) {
  const color = status === 'active' ? '#22c55e' : status === 'invited' ? 'var(--brand)' : '#ef4444';
  return <span style={{ width: 8, height: 8, borderRadius: '50%', background: color, display: 'inline-block', flexShrink: 0 }} />;
}

export default function DealerTeam() {
  const { user } = useAuth();
  const { toast } = useToast();
  const [members, setMembers]       = useState([]);
  const [loading, setLoading]       = useState(true);
  const [showInvite, setShowInvite] = useState(false);
  const [editingId, setEditingId]   = useState(null);
  const [inviting, setInviting]     = useState(false);

  const [invite, setInvite] = useState({ email: '', role: 'sales_agent' });
  const [customPerms, setCustomPerms] = useState({});

  const load = () => {
    setLoading(true);
    getTeamMembers().then(d => setMembers(d.members || [])).catch(() => {}).finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, []);

  const handleInvite = async () => {
    if (!invite.email) { toast('Enter an email address', 'error'); return; }
    setInviting(true);
    try {
      await inviteTeamMember({ email: invite.email, role: invite.role, permissions: customPerms });
      toast(`Invite sent to ${invite.email}`, 'success');
      setInvite({ email: '', role: 'sales_agent' });
      setCustomPerms({});
      setShowInvite(false);
      load();
    } catch (e) {
      toast(e?.response?.data?.message || 'Failed to send invite', 'error');
    } finally { setInviting(false); }
  };

  const handleRoleChange = async (memberId, newRole) => {
    try {
      await updateTeamMember(memberId, { role: newRole, permissions: ROLE_DEFAULTS[newRole] });
      setMembers(p => p.map(m => m._id === memberId ? { ...m, role: newRole, permissions: ROLE_DEFAULTS[newRole] } : m));
      toast('Role updated', 'success');
    } catch { toast('Failed', 'error'); }
  };

  const handlePermToggle = async (memberId, permKey, current) => {
    try {
      await updateTeamMember(memberId, { permissions: { [permKey]: !current } });
      setMembers(p => p.map(m => m._id === memberId ? { ...m, permissions: { ...m.permissions, [permKey]: !current } } : m));
    } catch { toast('Failed', 'error'); }
  };

  const handleRemove = async (memberId, name) => {
    if (!confirm(`Remove ${name} from your team?`)) return;
    try {
      await removeTeamMember(memberId);
      setMembers(p => p.filter(m => m._id !== memberId));
      toast('Removed from team', 'info');
    } catch { toast('Failed', 'error'); }
  };

  const handleSuspend = async (memberId, current) => {
    try {
      const next = current === 'active' ? 'suspended' : 'active';
      await updateTeamMember(memberId, { status: next });
      setMembers(p => p.map(m => m._id === memberId ? { ...m, status: next } : m));
      toast(next === 'suspended' ? 'Member suspended' : 'Member reinstated', 'info');
    } catch { toast('Failed', 'error'); }
  };

  return (
    <div style={{ background: '#0a3340', minHeight: '100vh' }}>
      {/* HEADER */}
      <div style={{ background: 'linear-gradient(180deg, rgba(19, 184, 166, 0.04) 0%, transparent 100%)', borderBottom: '1px solid rgba(255,255,255,0.05)', padding: '36px 0 32px' }}>
        <div style={{ maxWidth: 1100, margin: '0 auto', padding: '0 32px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', flexWrap: 'wrap', gap: 16 }}>
          <div>
            <div style={{ fontSize: 9, color: 'var(--brand)', fontWeight: 700, letterSpacing: '0.22em', textTransform: 'uppercase', marginBottom: 6 }}>Dealer Hub</div>
            <h1 style={{ fontFamily: 'var(--font-display)', fontWeight: 900, fontStyle: 'italic', fontSize: 'clamp(1.6rem,3vw,2.2rem)', color: '#fff', margin: 0 }}>
              My <span style={{ color: 'var(--brand)' }}>Team</span>
            </h1>
            <p style={{ color: 'rgba(255,255,255,0.3)', fontSize: 13, marginTop: 6 }}>
              You are the admin of your dealership. Invite staff, assign roles, and control access.
            </p>
          </div>
          <div style={{ display: 'flex', gap: 10 }}>
            <button onClick={load} style={{ padding: '10px 16px', borderRadius: 10, background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: '#fff', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6, fontSize: 12 }}>
              <RefreshCw size={13} /> Refresh
            </button>
            <button onClick={() => setShowInvite(true)} style={{ padding: '10px 20px', borderRadius: 10, background: 'var(--brand)', border: 'none', color: '#0a3340', fontSize: 12, fontWeight: 900, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6, textTransform: 'uppercase', letterSpacing: '0.06em' }}>
              <Plus size={14} /> Invite Member
            </button>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: 1100, margin: '0 auto', padding: '32px 32px' }}>

        {/* INVITE MODAL */}
        {showInvite && (
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(10, 51, 64, 0.85)', backdropFilter: 'blur(8px)', zIndex: 200, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
            <div style={{ background: '#0D0D0D', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 20, padding: 32, width: '100%', maxWidth: 520, maxHeight: '90vh', overflowY: 'auto' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
                <h2 style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.4rem', color: '#fff', margin: 0 }}>Invite Team Member</h2>
                <button onClick={() => setShowInvite(false)} style={{ background: 'none', border: 'none', color: 'rgba(255,255,255,0.4)', fontSize: 20, cursor: 'pointer' }}>✕</button>
              </div>

              <div style={{ marginBottom: 18 }}>
                <label style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.1em', color: 'rgba(255,255,255,0.4)', display: 'block', marginBottom: 8 }}>Email Address</label>
                <input placeholder="colleague@example.com" value={invite.email} onChange={e => setInvite(p => ({ ...p, email: e.target.value }))}
                  style={{ width: '100%', padding: '11px 14px', borderRadius: 10, border: '1px solid rgba(255,255,255,0.1)', background: 'rgba(255,255,255,0.05)', color: '#fff', fontSize: 13, outline: 'none', boxSizing: 'border-box' }}
                  onFocus={e => e.target.style.borderColor = 'rgba(19, 184, 166, 0.4)'}
                  onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.1)'} />
              </div>

              <div style={{ marginBottom: 20 }}>
                <label style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.1em', color: 'rgba(255,255,255,0.4)', display: 'block', marginBottom: 10 }}>Role</label>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {ROLES.map(r => (
                    <div key={r.id} onClick={() => { setInvite(p => ({ ...p, role: r.id })); setCustomPerms(ROLE_DEFAULTS[r.id]); }}
                      style={{ padding: '12px 16px', borderRadius: 10, border: `1px solid ${invite.role === r.id ? r.color + '50' : 'rgba(255,255,255,0.07)'}`, background: invite.role === r.id ? `${r.color}0a` : 'transparent', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 12, transition: 'all 0.15s' }}>
                      <div style={{ width: 10, height: 10, borderRadius: '50%', background: invite.role === r.id ? r.color : 'rgba(255,255,255,0.15)', flexShrink: 0 }} />
                      <div>
                        <div style={{ fontSize: 13, fontWeight: 700, color: invite.role === r.id ? '#fff' : 'rgba(255,255,255,0.65)' }}>{r.label}</div>
                        <div style={{ fontSize: 11, color: 'rgba(255,255,255,0.3)', marginTop: 2 }}>{r.desc}</div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Custom permissions */}
              <div style={{ marginBottom: 24 }}>
                <label style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.1em', color: 'rgba(255,255,255,0.4)', display: 'block', marginBottom: 10 }}>
                  Fine-tune Permissions
                </label>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                  {PERMISSIONS.map(p => {
                    const on = customPerms[p.key] ?? ROLE_DEFAULTS[invite.role]?.[p.key] ?? false;
                    return (
                      <div key={p.key} onClick={() => setCustomPerms(prev => ({ ...prev, [p.key]: !on }))}
                        style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '9px 12px', borderRadius: 8, border: `1px solid ${on ? 'rgba(19, 184, 166, 0.25)' : 'rgba(255,255,255,0.06)'}`, background: on ? 'rgba(19, 184, 166, 0.06)' : 'rgba(255,255,255,0.02)', cursor: 'pointer', transition: 'all 0.15s' }}>
                        <div style={{ width: 16, height: 16, borderRadius: 4, background: on ? 'var(--brand)' : 'rgba(255,255,255,0.08)', border: `1px solid ${on ? 'var(--brand)' : 'rgba(255,255,255,0.12)'}`, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                          {on && <span style={{ color: '#0a3340', fontSize: 10, fontWeight: 900 }}>✓</span>}
                        </div>
                        <span style={{ fontSize: 12, color: on ? '#fff' : 'rgba(255,255,255,0.4)', fontWeight: on ? 600 : 400 }}>{p.label}</span>
                      </div>
                    );
                  })}
                </div>
              </div>

              <div style={{ display: 'flex', gap: 10 }}>
                <button onClick={() => setShowInvite(false)} style={{ flex: 1, padding: '12px', borderRadius: 10, background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: 'rgba(255,255,255,0.6)', fontSize: 13, fontWeight: 600, cursor: 'pointer' }}>Cancel</button>
                <button onClick={handleInvite} disabled={inviting || !invite.email} style={{ flex: 2, padding: '12px', borderRadius: 10, background: invite.email ? 'var(--brand)' : 'rgba(255,255,255,0.05)', border: 'none', color: invite.email ? '#0a3340' : 'rgba(255,255,255,0.2)', fontSize: 13, fontWeight: 900, cursor: invite.email ? 'pointer' : 'default', textTransform: 'uppercase', letterSpacing: '0.06em' }}>
                  {inviting ? 'Sending…' : 'Send Invite'}
                </button>
              </div>
            </div>
          </div>
        )}

        {/* TEAM MEMBERS TABLE */}
        {loading ? (
          <div style={{ display: 'flex', justifyContent: 'center', padding: '60px 0' }}><div className="spinner" /></div>
        ) : members.length === 0 ? (
          <div style={{ background: '#0a3340', border: '1px solid rgba(255,255,255,0.07)', borderRadius: 16, padding: '60px', textAlign: 'center' }}>
            <div style={{ fontSize: 40, marginBottom: 14 }}>👥</div>
            <h3 style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.3rem', color: '#fff', marginBottom: 8 }}>No Team Members Yet</h3>
            <p style={{ color: 'rgba(255,255,255,0.35)', fontSize: 14, maxWidth: 380, margin: '0 auto 24px', lineHeight: 1.7 }}>
              Invite your sales agents, lot managers, and finance officers to collaborate in your dealership dashboard.
            </p>
            <button onClick={() => setShowInvite(true)} style={{ padding: '12px 28px', background: 'var(--brand)', border: 'none', borderRadius: 9999, color: '#0a3340', fontSize: 12, fontWeight: 900, cursor: 'pointer', textTransform: 'uppercase', letterSpacing: '0.08em' }}>
              Invite First Member
            </button>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {members.map(m => {
              const isEditing = editingId === m._id;
              const memberUser = m.member || {};
              const name = memberUser.name || m.inviteEmail || 'Invited User';
              return (
                <div key={m._id} style={{ background: '#0a3340', border: '1px solid rgba(255,255,255,0.07)', borderRadius: 14, overflow: 'hidden', transition: 'border-color 0.2s' }}>
                  {/* Member row */}
                  <div style={{ padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 16 }}>
                    {/* Avatar */}
                    <div style={{ width: 44, height: 44, borderRadius: 11, background: 'linear-gradient(135deg, rgba(19, 184, 166, 0.3), rgba(19, 184, 166, 0.1))', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 17, fontWeight: 900, color: 'var(--brand)', flexShrink: 0, fontFamily: 'var(--font-display)' }}>
                      {name[0]?.toUpperCase()}
                    </div>

                    {/* Info */}
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 3 }}>
                        <span style={{ fontSize: 14, fontWeight: 700, color: '#fff' }}>{name}</span>
                        <StatusDot status={m.status} />
                        <span style={{ fontSize: 10, color: 'rgba(255,255,255,0.25)', textTransform: 'capitalize' }}>{m.status}</span>
                      </div>
                      <div style={{ fontSize: 12, color: 'rgba(255,255,255,0.35)' }}>{memberUser.email || m.inviteEmail}</div>
                    </div>

                    {/* Role selector */}
                    <div style={{ position: 'relative' }}>
                      <select value={m.role} onChange={e => handleRoleChange(m._id, e.target.value)}
                        style={{ padding: '7px 28px 7px 12px', borderRadius: 9, border: '1px solid rgba(255,255,255,0.1)', background: '#0a3340', color: '#fff', fontSize: 12, fontWeight: 600, cursor: 'pointer', outline: 'none', appearance: 'none' }}>
                        {ROLES.map(r => <option key={r.id} value={r.id} style={{ background: '#0a3340' }}>{r.label}</option>)}
                      </select>
                      <ChevronDown size={12} style={{ position: 'absolute', right: 8, top: '50%', transform: 'translateY(-50%)', color: 'rgba(255,255,255,0.4)', pointerEvents: 'none' }} />
                    </div>
                    <RoleBadge role={m.role} />

                    {/* Actions */}
                    <div style={{ display: 'flex', gap: 8, flexShrink: 0 }}>
                      <button onClick={() => setEditingId(isEditing ? null : m._id)}
                        style={{ padding: '7px 14px', borderRadius: 8, background: isEditing ? 'rgba(19, 184, 166, 0.12)' : 'rgba(255,255,255,0.05)', border: `1px solid ${isEditing ? 'rgba(19, 184, 166, 0.3)' : 'rgba(255,255,255,0.09)'}`, color: isEditing ? 'var(--brand)' : 'rgba(255,255,255,0.55)', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>
                        {isEditing ? 'Done' : 'Permissions'}
                      </button>
                      <button onClick={() => handleSuspend(m._id, m.status)}
                        style={{ padding: '7px 14px', borderRadius: 8, background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.08)', color: m.status === 'active' ? 'rgba(19,184,166,0.75)' : '#22c55e', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>
                        {m.status === 'active' ? 'Suspend' : 'Reinstate'}
                      </button>
                      <button onClick={() => handleRemove(m._id, name)}
                        style={{ padding: '7px 12px', borderRadius: 8, background: 'rgba(239,68,68,0.07)', border: '1px solid rgba(239,68,68,0.14)', color: 'rgba(239,68,68,0.7)', cursor: 'pointer', display: 'flex', alignItems: 'center' }}>
                        <Trash2 size={13} />
                      </button>
                    </div>
                  </div>

                  {/* Permission expander */}
                  {isEditing && (
                    <div style={{ padding: '0 20px 18px', borderTop: '1px solid rgba(255,255,255,0.05)' }}>
                      <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.12em', color: 'rgba(255,255,255,0.3)', margin: '14px 0 12px' }}>Fine-grained Permissions</div>
                      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 165px), 1fr))', gap: 8 }}>
                        {PERMISSIONS.map(p => {
                          const on = m.permissions?.[p.key] ?? false;
                          return (
                            <div key={p.key} onClick={() => handlePermToggle(m._id, p.key, on)}
                              style={{ display: 'flex', alignItems: 'center', gap: 7, padding: '9px 12px', borderRadius: 8, border: `1px solid ${on ? 'rgba(19, 184, 166, 0.22)' : 'rgba(255,255,255,0.06)'}`, background: on ? 'rgba(19, 184, 166, 0.06)' : 'transparent', cursor: 'pointer', transition: 'all 0.15s' }}>
                              <div style={{ width: 15, height: 15, borderRadius: 4, background: on ? 'var(--brand)' : 'rgba(255,255,255,0.08)', border: `1px solid ${on ? 'var(--brand)' : 'rgba(255,255,255,0.12)'}`, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                                {on && <span style={{ color: '#0a3340', fontSize: 9, fontWeight: 900 }}>✓</span>}
                              </div>
                              <span style={{ fontSize: 11, color: on ? 'rgba(255,255,255,0.85)' : 'rgba(255,255,255,0.35)', fontWeight: on ? 600 : 400 }}>{p.label}</span>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* ROLES LEGEND */}
        <div style={{ marginTop: 32, background: '#0a3340', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 14, padding: '20px 24px' }}>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.14em', color: 'rgba(255,255,255,0.25)', marginBottom: 14 }}>Role Guide</div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 148px), 1fr))', gap: 12 }}>
            {ROLES.map(r => (
              <div key={r.id}>
                <RoleBadge role={r.id} />
                <div style={{ fontSize: 11, color: 'rgba(255,255,255,0.3)', marginTop: 6, lineHeight: 1.5 }}>{r.desc}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { carsAPI, auctionAdminAPI, formatKES } from '../../api/api';
import { useToast } from '../../context/ToastContext';
import { useAuth } from '../../context/AuthContext';
import { getIdFromPathPrefix } from '../../utils/navigation';


export default function EditCarPage() {
  // STAGE 4 ACCOUNT/SESSION/IDENTITY CONVERGENCE FIX: this page reproduced
  // the exact Stage-3 routing defect (useParams() always returns {} - this
  // app has no react-router <Routes>/<Route> tree anywhere, confirmed in
  // src/main.tsx). Unlike the two pages Stage 3 fixed, this one is
  // currently unreachable (not imported/routed from anywhere in
  // AuthRouteSurface or AppInner), so the bug has zero production impact
  // today - but it is a landmine: the moment someone adds a nav link to
  // it (DealerLayout.tsx already carries a `'edit-car': 'Edit Listing'`
  // label for exactly this page), `id` would silently be undefined and
  // the ownership check below would run against a car fetched with
  // `id === undefined`. Fixed now, using this codebase's established
  // manual-routing convention (the same helper the two already-fixed
  // Stage-3 pages use) rather than waiting for it to go live broken.
  const location = useLocation();
  const id = useMemo(() => getIdFromPathPrefix(location.pathname, '/dealer/edit-car/'), [location.pathname]);
  const { toast }  = useToast();
  const { user, isAdmin } = useAuth();
  const navigate   = useNavigate();
  const [car, setCar]       = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [form, setForm]     = useState({});
  const [auctionAction, setAuctionAction] = useState(null);
  const [extendHours, setExtendHours]     = useState(2);
  const [ownershipError, setOwnershipError] = useState(false);
  const [newImages, setNewImages] = useState([]);
  const [previews, setPreviews] = useState([]);

  useEffect(() => {
    carsAPI.get(id).then(d => {
      const c = d.car || d.data || d;
      // Ownership check — only the listing owner can edit
      if (c?.dealer?._id && c.dealer._id !== user?._id) {
        setOwnershipError(true);
        setCar(c);
        return;
      }
      setCar(c);
      setForm({
        title: c.title || '', brand: c.brand || '', model: c.model || '',
        year: String(c.year || ''), price: String(c.price || ''),
        fuel: c.fuel || '', transmission: c.transmission || '',
        bodyType: c.bodyType || '', mileage: String(c.mileage || ''),
        dealerPhone: c.dealerPhone || '',
        allowBuy: c.allowBuy ?? true, allowBid: c.allowBid ?? false,
        auctionEnd: c.auctionEnd ? new Date(c.auctionEnd).toISOString().slice(0, 16) : '',
      });
    }).finally(() => setLoading(false));
  }, [id]);

  const set = (k, v) => setForm(p => ({ ...p, [k]: v }));

  const handleImages = (e) => {
    const files = Array.from(e.target.files).slice(0, 8);
    setNewImages(files);
    setPreviews(files.map(f => URL.createObjectURL(f)));
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      if (newImages.length > 0) {
        const fd = new FormData();
        Object.entries(form).forEach(([k, v]) => {
          if (v !== '' && v !== null) fd.append(k, v);
        });
        newImages.forEach(img => fd.append('images', img));
        await carsAPI.update(id, fd);
      } else {
        await carsAPI.update(id, form);
      }
      toast('Listing updated!', 'success');
      navigate('/dealer');
    } catch (err) {
      // STAGE 2 API CONTRACT CONVERGENCE FIX: this previously discarded the
      // error entirely (a bare `catch {}`), so a precise, actionable 409
      // from the backend — e.g. AUCTION_TERMS_LOCKED, which explains exactly
      // why the save was rejected and that a controlled amendment is needed
      // instead — surfaced as the same flat "Failed to update" as any other
      // failure. handleAuctionStart right below already forwards the real
      // backend message; this now does the same.
      toast(err.response?.data?.message || 'Failed to update', 'error');
    }
    finally { setSaving(false); }
  };

  const handleAuctionStart = async () => {
    if (!form.auctionEnd) { toast('Set an auction end time first', 'error'); return; }
    setAuctionAction('starting');
    try {
      await auctionAdminAPI.start(id, { auctionEnd: form.auctionEnd });
      toast('🔴 Auction is now LIVE!', 'success');
      setCar(prev => ({ ...prev, auctionStatus: 'live' }));
    } catch (err) { toast(err.response?.data?.message || 'Failed', 'error'); }
    finally { setAuctionAction(null); }
  };

  const handleAuctionEnd = async () => {
    if (!confirm('End this auction now?')) return;
    setAuctionAction('ending');
    try {
      await auctionAdminAPI.end(id);
      toast('Auction ended.', 'info');
      setCar(prev => ({ ...prev, auctionStatus: 'ended' }));
    } catch { toast('Failed', 'error'); }
    finally { setAuctionAction(null); }
  };

  const handleExtend = async () => {
    setAuctionAction('extending');
    try {
      await auctionAdminAPI.extend(id, { hours: extendHours });
      toast(`Auction extended by ${extendHours}h`, 'success');
    } catch { toast('Failed', 'error'); }
    finally { setAuctionAction(null); }
  };

  if (loading) return <div className="page loading-center"><div className="spinner" /></div>;
  if (!car) return <div className="page loading-center"><h3>Car not found</h3></div>;
  if (ownershipError) return (
    <div className="page loading-center" style={{ flexDirection: 'column', gap: 16 }}>
      <div style={{ fontSize: 48 }}>🚫</div>
      <h3>Access Denied</h3>
      <p style={{ color: 'var(--text-muted)', textAlign: 'center', maxWidth: 400 }}>
        You can only edit your own listings. This car was listed by <strong>{car.dealer?.name}</strong>.
      </p>
      <div style={{ display: 'flex', gap: 12, marginTop: 8 }}>
        <button className="btn btn-outline" onClick={() => navigate(-1)}>← Go Back</button>
        <button className="btn btn-gold" onClick={() => navigate('/dealer')}>My Listings</button>
      </div>
    </div>
  );

  const Field = ({ label, children }) => (
    <div className="input-group"><label className="input-label">{label}</label>{children}</div>
  );

  return (
    <div className="page">
      <div className="container" style={{ paddingTop: 32, paddingBottom: 32, maxWidth: 760 }}>
        <div style={{ marginBottom: 32 }}>
          <div className="section-eyebrow">Dealer Hub</div>
          <h2>Edit: {car.title}</h2>
        </div>

        <div style={{ display: 'grid', gap: 20 }}>

          {/* Main form */}
          <div className="card" style={{ padding: 28 }}>
            <h3 style={{ marginBottom: 20 }}>Listing Details</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              <Field label="Title">
                <input className="input" value={form.title} onChange={e => set('title', e.target.value)} />
              </Field>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
                <Field label="Brand">
                  <input className="input" value={form.brand} onChange={e => set('brand', e.target.value)} />
                </Field>
                <Field label="Model">
                  <input className="input" value={form.model} onChange={e => set('model', e.target.value)} />
                </Field>
                <Field label="Year">
                  <input className="input" type="text" inputMode="numeric" pattern="[0-9]*" value={form.year} onChange={e => set('year', e.target.value)} />
                </Field>
                <Field label="Price (KES)">
                  <input className="input" type="text" inputMode="numeric" pattern="[0-9]*" value={form.price} onChange={e => set('price', e.target.value)} />
                </Field>
                <Field label="Fuel">
                  <input className="input" value={form.fuel} onChange={e => set('fuel', e.target.value)} />
                </Field>
                <Field label="Transmission">
                  <input className="input" value={form.transmission} onChange={e => set('transmission', e.target.value)} />
                </Field>
                <Field label="Mileage (km)">
                  <input className="input" type="text" inputMode="numeric" pattern="[0-9]*" value={form.mileage} onChange={e => set('mileage', e.target.value)} />
                </Field>
                <Field label="Dealer Phone">
                  <input className="input" value={form.dealerPhone} onChange={e => set('dealerPhone', e.target.value)} />
                </Field>
              </div>

              {/* Toggles */}
              <div style={{ display: 'flex', gap: 12 }}>
                {[
                  { key: 'allowBuy', label: '💳 Allow Direct Buy' },
                  { key: 'allowBid', label: '⚡ Allow Bidding' },
                ].map(t => (
                  <button
                    key={t.key}
                    onClick={() => set(t.key, !form[t.key])}
                    className={`btn btn-sm ${form[t.key] ? 'btn-gold' : 'btn-outline'}`}
                  >
                    {form[t.key] ? '✓ ' : ''}{t.label}
                  </button>
                ))}
              </div>

              <button className="btn btn-gold" onClick={handleSave} disabled={saving} style={{ alignSelf: 'flex-start' }}>
                {saving ? 'Saving...' : 'Save Changes'}
              </button>
            </div>
          </div>

          {/* Auction Controls */}
          {form.allowBid && (
            <div className="card" style={{ padding: 28 }}>
              <h3 style={{ marginBottom: 8 }}>⚡ Auction Controls</h3>
              <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
                <span className={`badge ${car.auctionStatus === 'live' ? 'badge-green' : car.auctionStatus === 'ended' ? 'badge-muted' : 'badge-orange'}`}>
                  {car.auctionStatus === 'live' && <span className="live-dot" />}
                  {car.auctionStatus}
                </span>
                <span style={{ fontSize: 13, color: 'var(--text-muted)' }}>
                  {car.bidsCount || 0} bids · Current: {formatKES(car.currentBid || car.price)}
                </span>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                {car.auctionStatus !== 'live' && (
                  <>
                    <Field label="Auction End Time">
                      <input className="input" type="datetime-local" value={form.auctionEnd}
                        onChange={e => set('auctionEnd', e.target.value)} />
                    </Field>
                    <button className="btn btn-gold" onClick={handleAuctionStart} disabled={!!auctionAction}>
                      {auctionAction === 'starting' ? '...' : '🔴 Start Live Auction'}
                    </button>
                  </>
                )}

                {car.auctionStatus === 'live' && (
                  <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
                    <button className="btn btn-danger" onClick={handleAuctionEnd} disabled={!!auctionAction}>
                      🏁 End Auction Now
                    </button>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                      <select className="input" value={extendHours} onChange={e => setExtendHours(Number(e.target.value))}
                        style={{ width: 100 }}>
                        {[1, 2, 4, 6, 12, 24].map(h => <option key={h} value={h}>+{h}h</option>)}
                      </select>
                      <button className="btn btn-outline" onClick={handleExtend} disabled={!!auctionAction}>
                        Extend
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* ─── Images ─── */}
          <div className="card" style={{ padding: 28 }}>
            <h3 style={{ marginBottom: 16 }}>Photos ({car.images?.length || 0})</h3>
            {car.images?.length > 0 && (
              <div className="grid-4" style={{ gap: 8, marginBottom: 16 }}>
                {car.images.map((img, i) => (
                  <div key={i} style={{ aspectRatio: '4/3', borderRadius: 8, overflow: 'hidden', position: 'relative', background: 'var(--surface)' }}>
                    <img src={img.url || img} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                    {i === 0 && (
                      <div style={{ position: 'absolute', top: 4, left: 4, background: 'var(--brand)', color: '#0A3340', fontSize: 9, fontWeight: 700, padding: '2px 6px', borderRadius: 4 }}>MAIN</div>
                    )}
                  </div>
                ))}
              </div>
            )}
            <div
              style={{ border: '2px dashed var(--border-soft)', borderRadius: 'var(--radius-lg)', padding: 24, textAlign: 'center', cursor: 'pointer' }}
              onClick={() => document.getElementById('edit-car-images').click()}
              onDragOver={e => e.preventDefault()}
              onDrop={e => {
                e.preventDefault();
                const files = Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/')).slice(0, 8);
                setNewImages(files); setPreviews(files.map(f => URL.createObjectURL(f)));
              }}
            >
              <div style={{ fontSize: 32, marginBottom: 8 }}>📷</div>
              <div style={{ fontWeight: 600, marginBottom: 4, fontSize: 13 }}>{newImages.length > 0 ? `${newImages.length} new image(s) selected` : 'Tap to replace / add photos'}</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Up to 8 images · JPG, PNG, WEBP</div>
              <input id="edit-car-images" type="file" multiple accept="image/*" onChange={handleImages} style={{ display: 'none' }} />
            </div>
            {previews.length > 0 && (
              <div className="grid-4" style={{ gap: 8, marginTop: 12 }}>
                {previews.map((src, i) => (
                  <div key={i} style={{ aspectRatio: '4/3', borderRadius: 8, overflow: 'hidden', background: 'var(--surface)' }}>
                    <img src={src} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Live stats */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12 }}>
            {[
              { label: 'Views', val: car.views || 0, icon: '👁' },
              { label: 'Bids', val: car.bidsCount || 0, icon: '⚡' },
              { label: 'Saved', val: car.favoritesCount || 0, icon: '❤️' },
              { label: 'Trust Score', val: `${car.trustScore || 100}%`, icon: '✅' },
            ].map(s => (
              <div key={s.label} className="stat-box" style={{ padding: 16 }}>
                <div style={{ fontSize: 20, marginBottom: 6 }}>{s.icon}</div>
                <div className="stat-value" style={{ fontSize: '1.4rem' }}>{s.val}</div>
                <div className="stat-label" style={{ fontSize: 11 }}>{s.label}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef } from 'react';

const BRANDS  = ['Toyota','Mercedes-Benz','BMW','Land Rover','Subaru','Mazda','Nissan','Honda','Volkswagen','Lexus','Audi','Mitsubishi','Hyundai','Kia','Ford','Jeep','Peugeot','Isuzu'];
const BODIES  = ['SUV','Sedan','Hatchback','Pickup','Wagon','Van','Coupe','Convertible','Bus'];
const CITIES  = ['Nairobi','Mombasa','Kisumu','Nakuru','Eldoret','Thika','Nyeri','Machakos','Meru'];

function Field({ label, children }) {
  return <div className="input-group">{label && <label className="input-label">{label}</label>}{children}</div>;
}

function SelectField({ label, field, form, set, options }) {
  return (
    <Field label={label}>
      <select className="input" value={form[field]} onChange={e => set(field, e.target.value)}>
        <option value="">Select {label}</option>
        {options.map(o => <option key={o} value={o}>{o}</option>)}
      </select>
    </Field>
  );
}

export default function AddCarStepBasic({ form, set }) {
  const titledRef = useRef(false);

  useEffect(() => {
    const parts = [form.year, form.brand, form.model].filter(Boolean);
    if (parts.length >= 2 && !titledRef.current) {
      set('title', parts.join(' '));
    }
    // `set` is a non-memoized prop recreated every parent render; only year/brand/model
    // changes should re-trigger the auto-title logic (guarded by titledRef besides).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [form.year, form.brand, form.model]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <h3 style={{ marginBottom: 4 }}>Basic Information</h3>
      <Field label="Listing Title *">
        <input className="input" placeholder="e.g. 2020 Toyota Land Cruiser V8 — Excellent Condition"
          value={form.title} onChange={e => { titledRef.current = true; set('title', e.target.value); }} />
        {!titledRef.current && [form.year, form.brand, form.model].filter(Boolean).length >= 2 && (
          <span style={{ fontSize: 10, color: 'rgba(255,255,255,0.3)', marginTop: 2 }}>Auto-generated from brand, model, year</span>
        )}
      </Field>
      <div className="grid-2">
        <SelectField label="Brand *" field="brand" form={form} set={set} options={BRANDS} />
        <Field label="Model">
          <input className="input" placeholder="e.g. Land Cruiser" value={form.model} onChange={e => set('model', e.target.value)} />
        </Field>
        <Field label="Year">
          <input className="input" type="text" inputMode="numeric" pattern="[0-9]*"
            value={form.year} onChange={e => set('year', e.target.value)} />
        </Field>
        <SelectField label="Body Type" field="bodyType" form={form} set={set} options={BODIES} />
      </div>
      <div className="grid-2">
        <SelectField label="City" field="city" form={form} set={set} options={CITIES} />
        <Field label="Dealer Phone">
          <input className="input" placeholder="0712 345 678" value={form.dealerPhone} onChange={e => set('dealerPhone', e.target.value)} />
        </Field>
      </div>
      <Field label="Address (Optional)">
        <input className="input" placeholder="e.g. Ngong Road, Nairobi" value={form.address} onChange={e => set('address', e.target.value)} />
      </Field>
      <Field label="Description *">
        <textarea className="input" rows={4} placeholder="Describe your vehicle — condition, service history, reason for selling, unique features..."
          value={form.description} onChange={e => set('description', e.target.value)} style={{ resize: 'vertical' }} />
      </Field>
    </div>
  );
}

